window.EXAMS_PAU=[{"id": "cv2007-jun-a", "official": true, "year": 2007, "conv": "June 2007", "opt": "A", "label": "PAU June 2007 · Text A", "cat": "Technology", "topic": "Boredom online", "color": "#7ec9e6", "title": "Brilliantly boring", "source": "Oliver Burkeman, The Guardian, 3 April 2007", "text": ["It is agreed that we are more bored today than ever before. And at the age of the Internet, when the average person has access to vastly more fascinating information than at any point in history, what are the sites that consistently achieve cult status, from the birth of the web up to the present day? The most boring ones.", "Just as frequently, though, boredom seems to be the very point of a boring website - as if we truly appreciate the quiet, uncomplicated space of a few moments spent watching, for example, a nest full of eggs or chicken in a farm with our web cam. In an information-saturated society, writes sociologist Orrin Klapp, we suffer anxiety, since the slow horse of our comprehension is unable to keep up with the fast horse of the information that we can access. It would be nice to believe that boring websites are popular because they are a rebellion against too much information overload - a space for our slow horses to live.", "Except for one problem. The truth is that we all know how the web has a power of distraction, somehow absorbing our boredom without really curing it. This is what we mean when we say that web-surfing is addictive. Big Brother has this effect, too: you don't feel bored while you're watching it, but afterwards, you still wish you hadn't spent so long in front of the TV. Similarly, the fact that you just spent 10 minutes watching the Big Brother website does not automatically mean that you really wanted to, nor that it was good for you to do so."], "q1": [{"s": "Only the websites that contain fascinating information achieve cult status.", "a": "F", "ev": "what are the sites that consistently achieve cult status, from the birth of the web up to the present day? The most boring ones."}, {"s": "According to Orrin Klapp, having too much information makes us feel anxious.", "a": "T", "ev": "In an information-saturated society, writes sociologist Orrin Klapp, we suffer anxiety"}, {"s": "People watch Big Brother on the Internet only if they really want to.", "a": "F", "ev": "does not automatically mean that you really wanted to"}, {"s": "Today the average person can access more information than ever before.", "a": "T", "ev": "the average person has access to vastly more fascinating information than at any point in history"}], "q2": [{"q": "Why does so much information generate anxiety?", "m": "We feel anxious because there is much more information available than we are able to understand: our comprehension is too slow to keep up with it."}, {"q": "Why may boring websites be so popular?", "m": "They may be popular because they offer a quiet, simple space that works as an escape from information overload, although in reality they only distract us."}], "q3": {"mode": "find", "opts": ["achieve", "frequently", "unable", "overload", "space", "mean"], "items": [["incapable", "unable"], ["imply", "mean"], ["excess", "overload"], ["obtain", "achieve"]]}, "q4": [{"q": "We are anxious today because...", "o": ["we cannot process all the information that is available.", "we only process the information that is communicated slowly.", "information comes from too many different sources.", "most information on the Internet is false."], "a": 0}, {"q": "Web-surfing is addictive because...", "o": ["users spend hours and hours on the Internet.", "users are attracted by its power of distraction.", "users feel depressed after using the Internet.", "the Internet is very cheap."], "a": 1}, {"q": "After watching Big Brother on TV...", "o": ["you wish the program was longer.", "you regret wasting your time.", "you wish you were even more bored.", "you feel more relaxed than before."], "a": 1}], "q5": {"A": "Do you think the Internet can become addictive? Give reasons.", "B": "Explain what you use the Internet for."}}, {"id": "cv2007-sep-a", "official": true, "year": 2007, "conv": "September 2007", "opt": "A", "label": "PAU September 2007 · Text A", "cat": "Environment", "topic": "Arctic ice", "color": "#7eb991", "title": "Arctic Sea Ice Melting Faster", "source": "Andrew C. Revkin, The New York Times, 1 May 2007", "text": ["Climate scientists may have significantly underestimated the power of global warming from human-generated heat-trapping gases to shrink the cap of sea ice floating on the Arctic Ocean. A new study concluded that an open-water Arctic in summers could be more likely in this century than had been estimated in the latest international review of climate research released in February.", "\"There are huge changes going on,\" said Julienne Stroeve, author of this new study. \"Just with warm waters entering the Arctic, combined with warming air temperatures, this is causing destruction on the sea ice.\"", "She also concluded that if emissions of heat-trapping gases like carbon dioxide were not significantly reduced, the region could end up with no floating ice in summers sometime between 2050 and the early decades of the next century.", "For the new study, Dr. Stroeve reviewed nearly six decades of measurements by ships, airplanes and satellites estimating the maximum and minimum area of Arctic sea ice, which typically expands most in March and shrinks most in September.", "With an expert from the National Center for Atmospheric Research, they then compared the observed trends with the projections made for the United Nations Intergovernmental Panel on Climate Change, using the world's most advanced computer models of climate.", "Dr. Stroeve found that since 1953 the area of sea ice in September has declined at an average rate of 7.8 per cent per decade. Computer climate simulations of the same period had an average rate of ice loss of 2.5 per cent per decade.", "ANDREW C. REVKIN"], "q1": [{"s": "This century could see the Arctic Ocean without the cap of sea ice during the summer.", "a": "T", "ev": "an open-water Arctic in summers could be more likely in this century than had been estimated"}, {"s": "The largest area of sea ice can be seen in September.", "a": "F", "ev": "which typically expands most in March and shrinks most in September"}, {"s": "Since the fifties, the area of sea ice is decreasing at a rate of more than 7% every ten years.", "a": "T", "ev": "since 1953 the area of sea ice in September has declined at an average rate of 7.8 per cent per decade"}, {"s": "Computer models predicted that the ice would disappear faster than it actually has.", "a": "F", "ev": "Computer climate simulations of the same period had an average rate of ice loss of 2.5 per cent per decade"}], "q2": [{"q": "Why is sea ice rapidly disappearing?", "m": "Sea ice is melting because of global warming caused by gases produced by human activity; warm water entering the Arctic and warmer air are destroying it."}, {"q": "How did Dr. Stroeve collect information for her study?", "m": "She analysed almost sixty years of measurements taken by ships, planes and satellites and compared them with the predictions of advanced computer climate models."}], "q3": {"mode": "find", "opts": ["shrink", "released", "huge", "reviewed", "trends", "simulations"], "items": [["made public", "released"], ["tendencies", "trends"], ["examined", "reviewed"], ["diminish", "shrink"]]}, "q4": [{"q": "Human-generated gases produce...", "o": ["ice on the Arctic Ocean in summer.", "the melting of sea ice during the summer.", "small changes during the summer.", "the growth of sea ice in winter."], "a": 1}, {"q": "If carbon dioxide is not reduced...", "o": ["floating ice will produce heat-trapping gases.", "floating ice will disappear before 2050.", "floating ice will disappear just after 2050.", "floating ice could disappear in summer between 2050 and the early decades of the next century."], "a": 3}, {"q": "The author of this study examined...", "o": ["data collected over a period of sixty years.", "data collected by the scientist herself over a period of sixty years.", "data collected for nearly sixty years.", "only satellite images from the last ten years."], "a": 2}], "q5": {"A": "Give your opinion about the devastating consequences of global warming.", "B": "How do you think you could contribute to the preservation of our planet? 1?"}}, {"id": "cv2008-jun-a", "official": true, "year": 2008, "conv": "June 2008", "opt": "A", "label": "PAU June 2008 · Text A", "cat": "Environment", "topic": "Amphibians", "color": "#7eb991", "title": "Amphibians may soon disappear", "source": "Doug Porter, stopglobalwarming.org, 2 April 2008", "text": ["The Chinese calendar says 2008 is the year of the Rat, but according to the Association of Zoos and Aquariums (AZA), 2008 should be the Year of the Frog. The reason is that frogs are disappearing from our planet at an alarming rate and, in a few years, they may all be extinct.", "In August 2007, more than 230 delegates representing zoos and aquariums from 35 countries gathered in Hungary to sign a petition, calling on governments to help preserve amphibian life. This marks the first time that zoos and aquariums have initiated a global call to action on behalf of an endangered class of animals. Their concern is that one-third to one-half of all species of frogs are in danger of becoming extinct in the near future - which would be the largest mass extinction since the disappearance of the dinosaurs.", "About 4,000 species of amphibians exist worldwide and most of them are frogs and toads. The term amphibian comes from the Greek amphibios and means double life, referring to the fact that they begin life in the water as tadpoles and gradually transform themselves into land dwelling creatures with legs. Frogs are \"cold-blooded\" and rely on the environment to regulate their body temperature. The skin of a frog is moistened by the secretion of numerous mucous glands and plays a vital part in the frog's water balance, respiration and protection. But since the skin is highly permeable to water, it also makes them highly susceptible to environmental changes."], "q1": [{"s": "Most frogs became extinct just after the disappearance of dinosaurs.", "a": "F", "ev": "frogs are disappearing from our planet at an alarming rate"}, {"s": "Frogs and toads are the most common amphibians.", "a": "T", "ev": "most of them are frogs and toads"}, {"s": "The skin of frogs is waterproof.", "a": "F", "ev": "the skin is highly permeable to water"}, {"s": "It was the first time that zoos and aquariums had started a global campaign to protect an endangered class of animals.", "a": "T", "ev": "This marks the first time that zoos and aquariums have initiated a global call to action"}], "q2": [{"q": "Why does AZA state that 2008 should be the Year of the Frog?", "m": "Because frogs are disappearing very fast and between a third and a half of all species could become extinct soon, so they want to draw attention to the problem."}, {"q": "Why does the Greek word amphibios mean double life?", "m": "Because amphibians have two lives: they begin in the water as tadpoles and later change into animals with legs that live on land."}], "q3": {"mode": "find", "opts": ["rate", "petition", "endangered", "concern", "worldwide", "moistened"], "items": [["dampened", "moistened"], ["request", "petition"], ["worry", "concern"], ["pace", "rate"]]}, "q4": [{"q": "In August 2007, delegates from 35 countries gathered …", "o": ["to discuss the preservation of amphibian life.", "to study the extinction of dinosaurs.", "to write a book about frogs.", "to open new zoos in Hungary."], "a": 0}, {"q": "Frogs are born as …", "o": ["land dwelling creatures with legs.", "toads.", "tadpoles.", "small frogs with long legs."], "a": 2}, {"q": "The body temperature of frogs …", "o": ["is rarely affected by the environment.", "is only sensitive to rain.", "changes depending on the weather.", "remains the same all year round."], "a": 2}], "q5": {"A": "Are all animals equally important and necessary? Give reasons.", "B": "Why do you think some animals became extinct and others are in danger of extinction?"}}, {"id": "cv2008-sep-a", "official": true, "year": 2008, "conv": "September 2008", "opt": "A", "label": "PAU September 2008 · Text A", "cat": "Society", "topic": "Youth violence", "color": "#cc7da7", "title": "Britain's mean streets", "source": "Catherine Mayer, Time, 26 March 2008", "text": ["Staying home in the face of danger isn't the British way. Yet last year more than a fifth of Britons avoided going out at night rather than risk encounters with a new form of terror: groups of children. Britons are frightened of their own young.", "On any Saturday night it's easy to see why. \"It usually starts outside McDonald's -that's the hot spot\", explains one London youth. There are always people there, with nothing to do but intimidate and get kicks.", "The English boys and girls who casually pick fights are often fuelled by cheap alcohol. And they try drugs or start smoking earlier than other Europeans. As Gordon Brown has recently said: \"Kids are out of control... They're roaming the streets. They're out late at night. There's an issue about gangs in Britain and an issue about gun crime as well as knife crime\".", "According to one expert, for a \"significant minority\" of British children, criminality, excessive drinking, drug-taking and promiscuity really have created a crisis. \"If I was sitting in government, I'd be really worried, not about terrorist bombs but about this\".", "All over the world, teenagers give their parents headaches. Why are British kids worse? It may be that parents aren't always around to help socialise their children or even just to show them affection. Compared to other cultures, British kids are less integrated into the adult world and spend more time with other kids. Many British adults seem to view children as an entirely separate species. And if no adult has love for you, you aren't going to feel love for other people when you get older."], "q1": [{"s": "British youngsters' violence is favoured by access to alcohol.", "a": "T", "ev": "fuelled by cheap alcohol"}, {"s": "Gordon Brown is worried about terrorist bombs and teenage violence.", "a": "F", "ev": "\"If I was sitting in government, I'd be really worried, not about terrorist bombs but about this\""}, {"s": "Many British children lack affection from their parents.", "a": "T", "ev": "parents aren't always around to help socialise their children or even just to show them affection"}, {"s": "British children spend more time with adults than children in other cultures.", "a": "F", "ev": "British kids are less integrated into the adult world and spend more time with other kids"}], "q2": [{"q": "Why did more than a fifth of Britons avoid going out at night last year?", "m": "They were afraid of meeting groups of young people in the streets, who often intimidate people, start fights and drink too much."}, {"q": "According to Gordon Brown, why are British kids out of control?", "m": "He says they wander the streets until late at night, and there are problems with gangs and with crimes involving guns and knives."}], "q3": {"mode": "find", "opts": ["encounters", "frightened", "significant", "worried", "headaches", "integrated"], "items": [["substantial", "significant"], ["meetings", "encounters"], ["scared", "frightened"], ["preoccupied", "worried"]]}, "q4": [{"q": "Kids intimidate and get kicks outside McDonald's because…", "o": ["there are many people outside and cannot enter the restaurant.", "they have no intention to do anything else.", "they can only socialise outside and not inside.", "they work at the restaurant."], "a": 1}, {"q": "Fights and alcohol...", "o": ["are the only two factors of kids' lives that the government should be worried about.", "are two of the factors of kids' lives that have caused a crisis in Britain.", "are the two factors that lead to kids' promiscuity and drug-taking.", "have been completely solved by the government."], "a": 1}, {"q": "British kids...", "o": ["need their parents in order to be positively integrated into society.", "need their parents more than children from other cultures.", "need their parents in order to stop giving them headaches.", "should spend more time with other kids."], "a": 0}], "q5": {"A": "Do you think that Spanish kids are like British kids and have similar problems?", "B": "What can be done to integrate kids into society? How can we prevent kids from being violent, taking drugs, drinking heavily and being promiscuous?"}}, {"id": "cv2009-jun-a", "official": true, "year": 2009, "conv": "June 2009", "opt": "A", "label": "PAU June 2009 · Text A", "cat": "Technology", "topic": "Distracted driving", "color": "#7ec9e6", "title": "How's My Driving? Ask My Car", "source": "Alan Boyle, msnbc.com, 16 April 2009", "text": ["Using gadgets while you're driving can be a very bad thing, but an expert on automotive distractions says using a gadget that watches you while you're driving can be a very good thing.", "\"People don't always understand the degree of distraction they may be exposing themselves to ... so the idea is to help people understand that distraction by providing them with feedback,\" says John D. Lee. Lee outlines the magnitude of the problem: More than 40,000 people die every year in motor vehicle crashes, and research indicates that failures of attention - including distractions or drowsiness - probably played a role in most of those crashes.", "Crashes and near-crashes are about three times as likely to happen when the driver is performing a complex task not related to driving (such as dialing a phone or even texting), and twice as likely during a moderately complex task (such as inserting a CD), Lee reported.", "As new technologies are introduced, the list of potential distractions keeps getting longer. Of course, most drivers overestimate their own abilities: In one survey, 88 percent of the respondents judged themselves to be safer than the average driver.", "So how does watching the driver help? Lee's method was to install a special camera system that saves video snippets for the 10 seconds before and after every abrupt movement on the road.", "After the feedback sessions, the number of events triggered by risky drivers declined 89 percent, Lee said, and the rate of risky driving remained low even six weeks later."], "q1": [{"s": "In most deadly car accidents, lack of attention seems to be involved.", "a": "T", "ev": "failures of attention - including distractions or drowsiness - probably played a role in most of those crashes"}, {"s": "The use of new technologies diminishes the frequency of distractions.", "a": "F", "ev": "As new technologies are introduced, the list of potential distractions keeps getting longer"}, {"s": "In Lee's study, the video camera installed in the car helps you watch for holes in the ground.", "a": "F", "ev": "saves video snippets for the 10 seconds before and after every abrupt movement on the road"}, {"s": "Most drivers in the survey believed they drove more safely than the average driver.", "a": "T", "ev": "88 percent of the respondents judged themselves to be safer than the average driver"}], "q2": [{"q": "According to the text, what can be good and/or bad about using \"gadgets\" while driving?", "m": "Using devices such as phones while driving is dangerous because they distract us, but a device that records the driver can be useful because it shows people their mistakes."}, {"q": "How can feedback provided to drivers help improve their driving?", "m": "Watching videos of their own risky moments makes drivers aware of how distracted they are, so they drive more carefully: in Lee's study risky events fell by 89%."}], "q3": {"mode": "find", "opts": ["gadget", "crashes", "drowsiness", "survey", "snippets", "rate"], "items": [["The state of being almost asleep", "drowsiness"], ["Small fragments of information such as data or images", "snippets"], ["A study to gather specific information", "survey"], ["A device or tool designed to perform a particular task or function", "gadget"]]}, "q4": [{"q": "Most people who die in a car accident…", "o": ["failed to pay attention and drowned.", "were driving too fast.", "were not paying attention to their driving.", "had drunk alcohol."], "a": 2}, {"q": "According to the author, when driving:", "o": ["Texting is a less dangerous task than inserting a CD.", "Non-related driving tasks can lead to crashes.", "You can perform a moderately complex task, but not a complex task.", "Inserting a CD is completely safe."], "a": 1}, {"q": "When the author says that \"most drivers overestimate their own abilities\", he means that:", "o": ["Most drivers drive safer than others.", "Most drivers feel safe when judging other drivers.", "Most drivers think they are very competent at driving.", "Most drivers never have accidents."], "a": 2}], "q5": {"A": "What can be done to reduce the number of car accidents?", "B": "How do you think technology can prevent road accidents?"}}, {"id": "cv2009-sep-a", "official": true, "year": 2009, "conv": "September 2009", "opt": "A", "label": "PAU September 2009 · Text A", "cat": "Society", "topic": "Abortion law", "color": "#cc7da7", "title": "Abortion on demand a step too far for Spanish right", "source": "Dale Fuchs, The Guardian, 28-3-2009", "text": ["A move to allow abortion on demand for Spanish women is provoking a virulent clash between the conservative clergy and the socialist government of Rodríguez Zapatero, whose gay marriage law drove hundreds of thousands of people on to the streets.", "Currently, it is a crime to have an abortion unless a woman can prove that she was raped, that the foetus is malformed or that the pregnancy endangers her physical or mental health. In practice, however, the law is interpreted liberally across a network of private clinics, which perform more than 100,000 abortions a year.", "The new abortion law, which would also allow the procedure up to 22 weeks with a doctor's certificate, is expected to be approved before the summer, with a provision that would allow girls over 16 to have an abortion without parental consent. \"They can't smoke, they can't drink alcohol but nevertheless they can abort without their parents' permission\", said a spokeswoman for the Right to Life movement.", "Thousands of activists are expected to join demonstrations throughout Spain this weekend. Hundreds of doctors, scientists and other Spanish professionals also signed a manifesto earlier this month rejecting the government's plans.", "However, apparently only 15% of Spaniards oppose abortion under any condition, and 45% support abortion on demand. A survey found 65% of Spaniards support abortion in the first three months. Women's groups also welcome the proposed reforms but also call for other measures, such as sex education in schools. A feminist coalition launched a counter-offensive to the church on Friday, with posters that say \"For motherhood with liberty and abortion with security\"."], "q1": [{"s": "With the new law, girls over 16 can have an abortion even if their parents disagree.", "a": "T", "ev": "a provision that would allow girls over 16 to have an abortion without parental consent"}, {"s": "All Spanish professionals support abortion on demand.", "a": "F", "ev": "Hundreds of doctors, scientists and other Spanish professionals also signed a manifesto earlier this month rejecting the government's plans"}, {"s": "A minority of Spaniards are entirely against abortion.", "a": "T", "ev": "only 15% of Spaniards oppose abortion under any condition"}, {"s": "Women's groups reject the proposed reforms.", "a": "F", "ev": "Women's groups also welcome the proposed reforms"}], "q2": [{"q": "In which cases is abortion allowed in Spain?", "m": "At present abortion is only legal when the woman has been raped, when the foetus is malformed or when the pregnancy is a risk to her physical or mental health."}, {"q": "What's new in the socialist government's abortion law?", "m": "It would allow abortion up to 22 weeks with a doctor's certificate, and girls over 16 could have an abortion without their parents' permission."}], "q3": {"mode": "find", "opts": ["clash", "endangers", "demonstrations", "oppose", "support", "measures"], "items": [["to be in favour", "support"], ["confrontation", "clash"], ["protests", "demonstrations"], ["puts at risk", "endangers"]]}, "q4": [{"q": "Private clinics…", "o": ["never follow the law.", "follow the law loosely.", "only perform legal abortions.", "are run by the Church."], "a": 1}, {"q": "The new law…", "o": ["allows abortions under 22 weeks of pregnancy.", "allows abortions beyond 22 weeks of pregnancy.", "allows abortions only at the 22nd week of pregnancy.", "bans all abortions after 16 weeks."], "a": 0}, {"q": "Women's groups…", "o": ["are not in favour of the new law unless other measures are added.", "are not in favour of the new law even if sex education is taught in schools.", "are in favour of the new law but they would like to see additional measures too.", "organised the demonstrations against the law."], "a": 2}], "q5": {"A": "What do you think about the government's new law?", "B": "What role can schools and parents play in preventing teenage pregnancies? ·?"}}, {"id": "cv2010-jun-a", "official": true, "year": 2010, "conv": "June 2010", "opt": "A", "label": "PAU June 2010 · Text A", "cat": "Technology", "topic": "YouTube", "color": "#7ec9e6", "title": "How Five Years of YouTube Turns a Nobody into a Star", "source": "S. Hoby and T. Lamont (The Guardian, 11-4-2010)", "text": ["Five years after Karim and two fellow PayPal employees founded their video-sharing website YouTube, it hosts more than 120 million videos. The site is a phenomenon that's generated a whole culture of YouTube celebrities. Never before had anyone with a video camera been able to reach a potential audience of millions and for many they did so by accident. But when the site started including advertisements related to the user's search, some people were able to make money out of their hobbies.", "The science behind what makes a video a hit remains vague. It's easier to bathe cats than to predict whether the public will like or dislike something. It's an illuminating choice of elements: cats are, of course, a pretty good bet. Also babies, though it's still surprising that a merely moderately amusing family moment is the most watched YouTube video of all time: \"Charlie bit my finger\", a clip in which Charlie, aged one, bites the finger of his big brother Harry.", "With its ability to grant an audience of millions to any clip the site has extraordinary democratic potential. Last year, a clip of Neda Agha-Soltan being shot in the chest in Iran was put on YouTube instantly and became a powerful tool in the protest movement against the Iranian government.", "The site's democratic character had already taken on new, practical uses with the so-called \"YouTube election\" of 2008, when what many had dismissed as simply a site for teenagers became a battleground for one of the most interesting presidential fights in history."], "q1": [{"s": "YouTube videos reach an audience of one hundred and twenty million users.", "a": "F", "ev": "it hosts more than 120 million videos"}, {"s": "Videos featuring cats are likely to draw the users' attention.", "a": "T", "ev": "cats are, of course, a pretty good bet"}, {"s": "YouTube only interests teenagers.", "a": "F", "ev": "what many had dismissed as simply a site for teenagers became a battleground"}, {"s": "The most watched YouTube video of all time shows a baby biting his brother's finger.", "a": "T", "ev": "a clip in which Charlie, aged one, bites the finger of his big brother Harry"}], "q2": [{"q": "Why can YouTube users get money from video sharing?", "m": "Because the site started showing adverts related to what users search for, so some people were able to earn money from videos they made as a hobby."}, {"q": "How can YouTube be used for democratic purposes?", "m": "It allows anyone to reach millions of people, so it can spread political protest, as with the video of Neda Agha-Soltan in Iran, and it played an important role in the 2008 US presidential election."}], "q3": {"mode": "find", "opts": ["generated", "accident", "hit", "choice", "amusing", "dismissed"], "items": [["ignored", "dismissed"], ["selection", "choice"], ["produced", "generated"], ["chance", "accident"]]}, "q4": [{"q": "We can...", "o": ["predict whether a video on YouTube will be a hit or not.", "never be sure whether a video on YouTube will be a hit or not.", "predict that a video featuring cats with babies will be a hit.", "only predict the success of videos about babies."], "a": 1}, {"q": "Videos on YouTube can...", "o": ["defeat a government.", "turn a country into a democracy.", "be used as a mass form of political protest.", "only be watched in the USA."], "a": 2}, {"q": "YouTube...", "o": ["has proved to be useful beyond teenage use.", "has proved to be useful only for teenagers.", "has proved to be useful for electing presidents.", "has stopped being popular."], "a": 0}], "q5": {"A": "Do you think that YouTube is a powerful tool in today's society? Give reasons.", "B": "Narrative: Write a story about a video that went viral."}}, {"id": "cv2010-jun-b", "official": true, "year": 2010, "conv": "June 2010", "opt": "B", "label": "PAU June 2010 · Text B", "cat": "Environment", "topic": "Green shopping", "color": "#7eb991", "title": "Shoppers Go Green 'to Impress Neighbours, Not to Save the Planet'", "source": "The Daily Telegraph, March, 17, 2010, p. 13", "text": ["Shoppers are hypocritical about buying environmentally friendly goods, according to a report which has found consumers are more concerned about impressing the neighbours than saving the planet. While consumers are more likely to 'go green' on the high street where they can be seen making altruistic choices, the privacy of online shopping brings out an entirely different behaviour.", "When people are not being watched by their peers they are more willing to shun the ethical products in favour of comfort and convenience, the report says.", "The habit has been studied by Vladas Griskevicius, of the University of Minnesota, who found eco-friendly shopping decisions are not always motivated by a social concern. He discovered that people were more likely to buy energy efficient light bulbs from the shops, but tended to opt for the old-fashioned type online. The same trend was also found when people purchased white goods, electronics and even domestic cleaning products over the internet.", "Mr Griskevicius picks out the Toyota Prius car as a prime example. Celebrities including Leonardo Di Caprio and Cameron Diaz have been photographed behind the wheel of a Prius, despite being well able to afford a more powerful and expensive car, sending the message that they are concerned for the environment. 'When you publicly display your environmentally friendly nature, you send the signal that you care,' said the report. The study also showed that people were often more willing to buy green products when they were the most expensive option, because it showed they could afford to be caring."], "q1": [{"s": "People tend to buy more green products online.", "a": "F", "ev": "the privacy of online shopping brings out an entirely different behaviour"}, {"s": "The car that most film stars own is a Toyota Prius.", "a": "F", "ev": "Celebrities including Leonardo Di Caprio and Cameron Diaz have been photographed behind the wheel of a Prius"}, {"s": "People don't mind buying 'green' products when they are more expensive if other people notice what they are buying.", "a": "T", "ev": "people were often more willing to buy green products when they were the most expensive option, because it showed they could afford to be caring"}, {"s": "People choose old-fashioned light bulbs more often online than in shops.", "a": "T", "ev": "people were more likely to buy energy efficient light bulbs from the shops, but tended to opt for the old-fashioned type online"}], "q2": [{"q": "What are the real reasons why consumers buy eco-friendly goods?", "m": "Many consumers buy eco-friendly products mainly to impress other people and show that they care about the environment, not really to protect the planet."}, {"q": "Why do some film stars promote eco-friendly products?", "m": "By being seen with green products such as the Toyota Prius, they send the message that they care about the environment, which improves their public image."}], "q3": {"mode": "find", "opts": ["concerned", "privacy", "behaviour", "peers", "purchased", "prime"], "items": [["bought", "purchased"], ["representative, characteristic", "prime"], ["intimacy", "privacy"], ["preoccupied", "concerned"]]}, "q4": [{"q": "According to the report, people who buy eco-friendly products...", "o": ["are more interested in impressing their neighbours.", "are more interested in saving the planet.", "are more interested in comfort and convenience.", "are mostly university students."], "a": 0}, {"q": "When buying goods on the Internet ...", "o": ["consumers always 'go green'.", "consumers rarely 'go green'.", "consumers 'go green' if the bulbs are energy efficient.", "consumers only buy electronics."], "a": 1}, {"q": "Leonardo Di Caprio and Cameron Diaz have both …", "o": ["photographed cars including the Toyota Prius.", "promoted the Toyota Prius.", "bought powerful and expensive cars such as the Toyota Prius.", "refused to drive a Toyota Prius."], "a": 1}], "q5": {"A": "What is your opinion about eco-friendly products? Do you think they are an urgent need or just a passing fashion? 4 --· ·-· .. ·-· .. .. - ® e:?", "B": "For and against: Should eco-friendly products be cheaper than other products?"}}, {"id": "cv2010-sep-a", "official": true, "year": 2010, "conv": "September 2010", "opt": "A", "label": "PAU September 2010 · Text A", "cat": "Society", "topic": "Store brands", "color": "#cc7da7", "title": "Store Brands Lift Grocers in Troubled Times", "source": "Andrew Martin, The New York Times", "text": ["As the economy plunges into a deep recession, grocery stores are one of the few sectors doing well. That is because cash-short consumers are eating out less and stocking up at the supermarket. And store brand products, which tend to be cheaper than national brands and more profitable for grocers, are doing especially well.", "Led by chains like Kroger, Wegmans and Safeway, grocers have expanded their store brands beyond cheap generics and simple knockoffs of Cheerios, Oreos and Coca-Cola. Now, retailers are increasingly adding premium store-brand items like organics, or creating products without direct competition. In this economic climate, many shoppers are willing to try the newly developed store brands. They also say it is hard to resist the low prices of store brands for staple goods like milk, sugar and cheese. Jan-Benedict E. M . Steenkamp, marketing professor at the University of North Carolina, said past recessions had given consumers a reason to trade down from national brands. This time, he said, the gains may stick because the quality and consistency of store brands have improved.", "Besides the weak economy, the growth of store brands reflects a historic shift in the balance of power between packaged food manufacturers and grocery retailers. As these grocery retailers have consolidated and grown bigger, they are increasingly able to stock their shelves with their own store brands, which bring higher profits and drive customer loyalty ! all to the detriment of major food brands. Of course, major branded food companies dispute the idea that store brands are just as good as their products and they argue that branded products offer better taste, consistency and innovation, justifying a premium price."], "q1": [{"s": "National brands are usually more profitable for grocers than store brands.", "a": "F", "ev": "store brand products, which tend to be cheaper than national brands and more profitable for grocers"}, {"s": "Shoppers find it difficult to resist buying store brand milk and sugar.", "a": "T", "ev": "it is hard to resist the low prices of store brands for staple goods like milk, sugar and cheese"}, {"s": "Major food manufacturers claim their products are as good as store brands.", "a": "F", "ev": "they argue that branded products offer better taste, consistency and innovation"}, {"s": "According to Professor Steenkamp, store brands have improved their quality.", "a": "T", "ev": "the quality and consistency of store brands have improved"}], "q2": [{"q": "According to the text, why are grocery stores, nowadays, successful in comparison to other businesses?", "m": "Because during the recession people have less money, so they eat out less and buy more food at supermarkets, especially cheaper store brands."}, {"q": "On what basis do food companies justify the higher price of their brand-name products?", "m": "They claim that their products taste better, are more consistent and more innovative, which justifies paying more for them."}], "q3": {"mode": "find", "opts": ["plunges", "retailers", "staple", "trade down", "stick", "products"], "items": [["merchants who sell goods directly to the consumers", "retailers"], ["stay, remain", "stick"], ["drops steeply", "plunges"], ["basic, essential, necessary", "staple"]]}, "q4": [{"q": "Nowadays, consumers are short of cash; as a result, they...", "o": ["line up at supermarkets to get groceries.", "go to restaurants less frequently.", "eat less than before the recession.", "only buy national brands."], "a": 1}, {"q": "Food chains like Wegmans...", "o": ["are introducing more quality store-brand products.", "are expanding by opening more stores.", "have decreased the amount of generics.", "have stopped selling organic products."], "a": 0}, {"q": "According to the text, the growth of store brands reflects...", "o": ["the consolidation of grocery retailers to the detriment of major food manufacturers.", "customers' loyalty to national brands.", "the power of national manufacturers.", "the end of the economic recession."], "a": 0}], "q5": {"A": "How has the financial crisis affected daily life in Spain?", "B": "Opinion: Do you prefer store brands or famous brands? Why?"}}, {"id": "cv2010-sep-b", "official": true, "year": 2010, "conv": "September 2010", "opt": "B", "label": "PAU September 2010 · Text B", "cat": "Education", "topic": "Pupil power", "color": "#b3a5cc", "title": "Now Teachers Are Ordered to Smile at Their Pupils", "source": "Daily Mail, 6 April 2010", "text": ["A secondary school has ordered teachers to welcome children with a smile at the start of every lesson as part of a drive to hand more power to pupils. Staff have also been told to ensure they are not boring students by setting work that is too hard.", "The move is the latest example of a Government initiative to give pupils a major say in many aspects of their schooling, but some critics say this is putting children in charge. Yesterday the Mail revealed that 20 students at a Kent secondary school were given iPhones to provide instant feedback of teachers to senior staff. In another incident, a teacher being interviewed for a job by a student panel was asked to sing the Michael Jackson song \"Bad\". She failed to get the job after refusing. Pupils on another interview panel voted in favour of a female candidate because she was the \"prettiest\", although she was not hired.", "Schools Secretary Ed Balls admitted the approach used by some schools was \"completely wrong\", \"absurd\" and \"ridiculous\". \"The people who are in charge are the head teachers, the governors and the teachers,\" he said. \"The idea that you would give out iPhones to secretly spy on teachers, that would be in my view, completely wrong\". \"Any head teacher doing that needs to look hard at themselves and consider the way in which they are doing things\".", "But far from dismissing the practice, he added: \"Some schools do ask teachers to get a report from the children about how lessons are going\"."], "q1": [{"s": "Teachers have been told not to assign homework.", "a": "F", "ev": "ensure they are not boring students by setting work that is too hard"}, {"s": "In Kent, iPhones were given to every student.", "a": "F", "ev": "20 students at a Kent secondary school were given iPhones"}, {"s": "Some schools want their students to express their opinion about their classes.", "a": "T", "ev": "Some schools do ask teachers to get a report from the children about how lessons are going"}, {"s": "Ed Balls approves of all the methods used by these schools.", "a": "F", "ev": "Ed Balls admitted the approach used by some schools was"}], "q2": [{"q": "What measures have teachers been forced to take in secondary schools?", "m": "They have been told to welcome students with a smile at the start of every lesson and to avoid boring them by setting work that is too difficult."}, {"q": "Why have mobile phones been used in some schools?", "m": "In one school, some students were given iPhones so that they could send instant feedback about their teachers to senior staff."}], "q3": {"mode": "find", "opts": ["staff", "schooling", "feedback", "incident", "panel", "governors"], "items": [["jury, committee", "panel"], ["event, episode", "incident"], ["employees", "staff"], ["response, opinion", "feedback"]]}, "q4": [{"q": "A teacher who was asked to sing \"Bad\"...", "o": ["got the job.", "never got the job.", "was then asked to refuse the job.", "sang the song perfectly."], "a": 1}, {"q": "Ed Balls stated that...", "o": ["students should have more power.", "teachers should be secretly observed.", "iPhones are not a good tool to provide feedback.", "head teachers should be chosen by students."], "a": 2}, {"q": "Some schools want students to...", "o": ["give their opinion on lessons.", "describe teachers.", "report about the use of iPhones.", "choose the prettiest teachers."], "a": 0}], "q5": {"A": "What is your opinion about giving more power to students in schools?", "B": "Narrative: Write about a teacher who changed your life."}}, {"id": "cv2011-jun-a", "official": true, "year": 2011, "conv": "June 2011", "opt": "A", "label": "PAU June 2011 · Text A", "cat": "Environment", "topic": "Nuclear risk", "color": "#7eb991", "title": "Chernobyl \"Poses More Risk than Fukushima\"", "source": "Irish Independent, 22nd April, 2011, p. 13", "text": ["The recent nuclear disaster at the Fukushima plant in Japan has been described as the \"next Chernobyl\" - but Chernobyl itself poses an even greater threat, according to campaigners. Twenty-five years on from the accident, the sarcophagus hastily put in place to prevent further poisons seeping into the atmosphere is now crumbling. And this poses a great danger to the people of the region, according to Adi Roche, Chief Executive of Chernobyl Children International (CCI).", "A quarter of the region is now unoccupiable and already 200,000 people have been displaced from their homes, but the nightmare may not be over for the people of Belarus.", "In the aftermath of the explosion in 1986, emergency teams covered the stricken reactor with a massive steel and concrete structure to seal in the lethal mix of radioactive fuel and materials like concrete and sand that fused together in the 1986 blast. That has come to the end of its lifespan and must be replaced but, to date, nothing has been done.", "\"It is a crumbling sarcophagus\", and \"The next Chernobyl could be Chernobyl\", said M s Roche of the structure of nearly 700,000 tons of steel and 400,000 tons of concrete. She estimates that just three per cent of the radiation escaped in the original explosion - leaving 97% of the material \"still rumbling away\". She was \"heartbroken\" when the catastrophe struck at the Fukushima plant in Japan. She also pointed out immediately after the Japanese disaster, experts had said: \"This is not Chernobyl\". But now, weeks later:\"It is Chernobyl\"."], "q1": [{"s": "The sarcophagus is now in perfect condition.", "a": "F", "ev": "the sarcophagus hastily put in place to prevent further poisons seeping into the atmosphere is now crumbling"}, {"s": "In 1986 workers used steel and concrete to build a brand-new reactor.", "a": "F", "ev": "emergency teams covered the stricken reactor with a massive steel and concrete structure"}, {"s": "According to Ms Roche, most of the radioactive material did not escape in the original explosion.", "a": "T", "ev": "just three per cent of the radiation escaped in the original explosion"}, {"s": "About 200,000 people have had to leave their homes.", "a": "T", "ev": "already 200,000 people have been displaced from their homes"}], "q2": [{"q": "What is the main problem in Chernobyl nowadays?", "m": "The protective structure built over the reactor in 1986 is falling apart and has not been replaced, so radioactive material could escape and endanger the people of the region."}, {"q": "What happened just after the explosion in 1986?", "m": "Emergency teams covered the damaged reactor with a huge structure of steel and concrete to keep the radioactive fuel and materials inside."}], "q3": {"mode": "find", "opts": ["crumbling", "aftermath", "lethal", "lifespan", "rumbling", "heartbroken"], "items": [["consequence", "aftermath"], ["very sad", "heartbroken"], ["disintegrating", "crumbling"], ["working time", "lifespan"]]}, "q4": [{"q": "Twenty-five per cent of the Chernobyl region is...", "o": ["ready for people to live safely.", "dangerous for people to live safely.", "ready for up to 200,000 people to live safely.", "completely free of radiation."], "a": 1}, {"q": "In the 1986 blast, ...", "o": ["sand and concrete just disappeared.", "sand and concrete rumbled away.", "sand and concrete melted and intermixed.", "sand and concrete were removed from the site."], "a": 2}, {"q": "In Chernobyl, ...", "o": ["more than 90% of the radioactive material is still active and dangerous.", "less than 90% of the radioactive material is still active and dangerous.", "only 3% of the radioactive material is still active and dangerous.", "all the radioactive material escaped in 1986."], "a": 0}], "q5": {"A": "Write about whether you are in favour or against nuclear power plants.", "B": "For and against: Nuclear energy or renewable energy?"}}, {"id": "cv2011-jun-b", "official": true, "year": 2011, "conv": "June 2011", "opt": "B", "label": "PAU June 2011 · Text B", "cat": "Work", "topic": "Youth emigration", "color": "#c3a48e", "title": "Spain: No Country for the Young?", "source": "Giles Tremlett, The Guardian, 28th M arch, 2011", "text": ["During the last 10 years booming Spain was a magnet for immigrants, attracting 5 million foreigners. Now Spaniards are talking of a return to the mass emigration of 1960s, when 2 million left looking for jobs in northern Europe. \"I only see jobs for exploited interns who earn €300 (£263) a month. That's barely enough to cover the costs of getting to work and back every day,\" said Luna, a Spanish graduate. \"Opportunities are scarce in a country with youth unemployment over 40% .\" The crucial difference between those leaving now and the manual labourers who sought work in Germany in the 1960s is that today's emigrants are mostly young graduates. It is no longer clear that a degree is useful in Spain's paralysed job market. Unemployment among graduates aged 29 or under is running at 19%, almost the same as the national average for all age groups, regardless of education.", "Many graduates lie about their education when applying for work, worried that they will be rejected for being overqualified. And 44% of those who find work do so at below their skills level, twice the European average. The contrast with booming Germany, which is short of 48,000 engineers, could not be greater. Those graduates who have left say that opportunities are far more plentiful abroad. \"Salaries, working hours, conditions and opportunities to advance in your career are far greater here,\" said 28-year-old Paula, who left Valencia five years ago and is now an IT consultant in Edinburgh."], "q1": [{"s": "Spain attracted millions of immigrants during its years of economic boom.", "a": "T", "ev": "During the last 10 years booming Spain was a magnet for immigrants, attracting 5 million foreigners"}, {"s": "In Spain's job market a degree is still a guarantee of a job.", "a": "F", "ev": "It is no longer clear that a degree is useful in Spain's paralysed job market"}, {"s": "Many graduates do not tell the truth about their studies to get a job.", "a": "T", "ev": "Many graduates lie about their education when applying for work"}, {"s": "Spanish emigrants in the 1960s were mostly young graduates.", "a": "F", "ev": "the manual labourers who sought work in Germany in the 1960s"}], "q2": [{"q": "What does the author mean by \"Spain: No country for the young?\"?", "m": "He means that Spain does not offer young people a future: there are few jobs and many young people, even graduates, have to emigrate to find work."}, {"q": "Why do young graduates look for jobs abroad?", "m": "Because in Spain many graduates are unemployed or work below their qualifications for very low salaries, while abroad they find better pay, working conditions and career opportunities."}], "q3": {"mode": "find", "opts": ["scarce", "manual", "paralysed", "regardless", "plentiful", "advance"], "items": [["abundant", "plentiful"], ["motionless", "paralysed"], ["few", "scarce"], ["move forward", "advance"]]}, "q4": [{"q": "People are exploited in Spain because they are offered salaries...", "o": ["that hardly pay for the cost of transportation.", "that do not cover the cost of transportation.", "and conditions to advance in their careers.", "that are higher than in Germany."], "a": 0}, {"q": "The difference between today's emigrants and those in the 1960's is that...", "o": ["today's emigrants have got a degree.", "today's emigrants are manual workers.", "today's emigrants are aged 29.", "today's emigrants go to southern Europe."], "a": 0}, {"q": "In Spain...", "o": ["44% of graduates are underqualified for their jobs.", "more than half of graduates are overqualified for their jobs.", "less than half of graduates are overqualified for their jobs.", "no graduates work below their skills level."], "a": 2}], "q5": {"A": "What do you think of the future for young people like you in Spain? 4 I. Answer the following questions using your own words but taking into account the information in the text (2 points: 1 point each) a) Why may there be a connection between global warming and geological disasters? b) Why can heavy rain provoke earthquakes? II. Are the following statements true (T) or false (F)? Identify the part of the text that supports your answer by copying the exact passage on the answer sheet (1.5 point: 0.5 each) a) It has been scientifically demonstrated that climate change will make geological dangers more likely. b) A high amount of water can produce more pressure on the Earth's surface. c) Studies indicate that a warmer world may bring about a higher risk of geological dangers. III. Find a synonym for each of the four words below from these six options: (1 point: 0.25 each) warming distant link likely actually rise a) probable b) increase c) connection d) far away IV. Choose a, b, or c, in each question below. Only one choice is correct (1.5 points: 0.5 each)?", "B": "Warming atmosphere in the past... a) was produced by changes in geological activity. b) may be related to changes in geological activity. c) appeared exactly at the same time as changes in geological activity."}}, {"id": "cv2011-sep-a", "official": true, "year": 2011, "conv": "September 2011", "opt": "A", "label": "PAU September 2011 · Text A", "cat": "Technology", "topic": "Screen time", "color": "#7ec9e6", "title": "Are Your Kids Awake? They're Online", "source": "Tamar Lewin The New York Times 21st January, 2010", "text": ["The average young American now spends practically every waking minute - except for the time in school - using a smart phone, computer, television or other electronic device, according to a new study. Those ages 8 to 18 spend more than seven and a half hours a day with such devices, compared with less than six and a half hours five years ago, when the study was last conducted. And that does not count the hour and a half that youths spend texting, or the half-hour they talk on their cell phones. And because so many of them are multitasking - say, surfing the Internet while listening to music - they pack on average nearly 11 hours of media content into that seven and a half hours.", "The study's findings shocked its authors, who had concluded in 2005 that use could not possibly grow further, and confirmed the fears of many parents whose children are constantly tethered to media devices. It found, moreover, that heavy media use is associated with behavior problems and lower grades. The third in a series, the study found that young people's media consumption grew far more in the last five years than from 1999 to 2004, as sophisticated mobile technology like iPods and smart phones brought media access into teenagers' pockets and beds.", "On average, young people spend about two hours a day consuming media on a mobile device, the study found. They spend almost another hour on \"old\" content like television or music delivered through newer pathways like the Web site Hulu or iTunes. Youths now spend more time listening to or watching media on their cell phones, or playing games, than talking on them."], "q1": [{"s": "Young Americans spend every minute they are awake using electronic devices.", "a": "F", "ev": "except for the time in school"}, {"s": "Multitasking increases the average of media consumption.", "a": "T", "ev": "they pack on average nearly 11 hours of media content into that seven and a half hours"}, {"s": "Heavy media consumption is related to poor school performance.", "a": "T", "ev": "heavy media use is associated with behavior problems and lower grades"}, {"s": "Young people now spend more time talking on their phones than using them for media.", "a": "F", "ev": "Youths now spend more time listening to or watching media on their cell phones, or playing games, than talking on them"}], "q2": [{"q": "Why were the authors surprised about the results of their study?", "m": "They had concluded in 2005 that media use could not grow any more, but it increased a lot: young people now spend more than seven and a half hours a day with devices."}, {"q": "According to the text, how do the authors explain the increase in media consumption among the young?", "m": "They explain it by modern mobile technology, such as iPods and smartphones, which allows teenagers to access media everywhere, even in their pockets and in bed."}], "q3": {"mode": "find", "opts": ["pack", "findings", "fears", "tethered", "behavior", "delivered"], "items": [["suspicions", "fears"], ["compress", "pack"], ["results", "findings"], ["attached", "tethered"]]}, "q4": [{"q": "The title of this text suggests that…", "o": ["young people spend most of their time awake using electronic devices.", "parents may think their kids are in bed, sleeping, but instead they are on the Internet.", "kids have behavioral problems because they surf the Internet too much.", "children should not have phones."], "a": 1}, {"q": "Youth…", "o": ["spend an average of seven and a half hours on their cell phones.", "spend less time using electronic devices than before.", "spend more time texting than talking on their cell phones.", "do not use media at night."], "a": 2}, {"q": "Young people use their cell phones…", "o": ["mostly to talk to their friends.", "less frequently than in the previous study.", "mostly to consume media rather than to make calls.", "only to play games."], "a": 2}], "q5": {"A": "What kinds of media devices do you usually use and what for?", "B": "For and against: Should teenagers be allowed to keep their phones in their bedrooms at night?"}}, {"id": "cv2011-sep-b", "official": true, "year": 2011, "conv": "September 2011", "opt": "B", "label": "PAU September 2011 · Text B", "cat": "Science", "topic": "Climate and earthquakes", "color": "#8c92cb", "title": "Scientists Call for Research on Climate Link to Geological Disasters", "source": "David Adam, The Guardian, 9 April 2010", "text": ["Scientists today called for research into whether more volcanoes, earthquakes and tsunamis could be triggered by rising global temperatures under global warming. Significant warming of the atmosphere in the distant past can be linked to changes in geological activity, they say. Suggestions that climate change predicted for coming decades could bring similar changes remain speculative, but the scientists say there is enough evidence to take the threat seriously.", "Richard Betts, from Exeter, said: \"It was previously assumed that there was no link at all between climate change and these events, but it is possible to speculate that climate change might make some events more likely. If we do get large amounts of climate change in the long term then we might see some impacts\". Experts say global warming could affect geological dangers such as earthquakes because of the way it can move large amounts of materials around on the Earth's surface. Melting glaciers and rising sea levels affect the distribution of huge amounts of water, which release and increase pressures through the ground. Research suggests that the Earth's surface can sometimes be so close to failure that small changes in surface pressure provoked by heavy rain can produce earthquakes. Actually, tropical storms, snowfall and shifting tides have all been linked to shifts in seismic activity.", "Bill McGuire, from University College London, says: \"studies point towards increased risk in relation to a warmer world, and observations suggest that the rise in global temperatures may already be producing disasters in the earth's surface\"."], "q1": [{"s": "It has been scientifically demonstrated that climate change will make geological dangers more likely.", "a": "F", "ev": "Suggestions that climate change predicted for coming decades could bring similar changes remain speculative"}, {"s": "A high amount of water can produce more pressure on the Earth's surface.", "a": "T", "ev": "Melting glaciers and rising sea levels affect the distribution of huge amounts of water, which release and increase pressures through the ground"}, {"s": "Studies indicate that a warmer world may bring about a higher risk of geological dangers.", "a": "T", "ev": "studies point towards increased risk in relation to a warmer world"}, {"s": "Scientists have always believed that climate change and geological events were connected.", "a": "F", "ev": "It was previously assumed that there was no link at all between climate change and these events"}], "q2": [{"q": "Why may there be a connection between global warming and geological disasters?", "m": "Global warming moves large amounts of material on the Earth's surface: melting glaciers and rising sea levels change the distribution of water, which changes the pressure on the ground."}, {"q": "Why can heavy rain provoke earthquakes?", "m": "Because sometimes the Earth's surface is so close to breaking that even small changes in pressure, like those caused by heavy rain, can trigger an earthquake."}], "q3": {"mode": "find", "opts": ["warming", "distant", "link", "likely", "actually", "rise"], "items": [["probable", "likely"], ["increase", "rise"], ["connection", "link"], ["far away", "distant"]]}, "q4": [{"q": "Warming of the atmosphere in the past...", "o": ["was produced by changes in geological activity.", "may be related to changes in geological activity.", "appeared exactly at the same time as changes in geological activity.", "stopped completely after the last ice age."], "a": 1}, {"q": "Global warming could affect geological dangers because...", "o": ["the Earth's surface is mainly covered by water.", "large quantities of materials are moved to places where earthquakes are likely.", "it produces a movement of lots of materials in certain parts of the Earth's surface.", "glaciers are getting bigger."], "a": 2}, {"q": "Seismic activity...", "o": ["can only be altered by the movement of large amounts of materials.", "can only be altered by heavy rain.", "can be altered by many different climate phenomena.", "has never been studied by scientists."], "a": 2}], "q5": {"A": "What can be done to protect the environment and reduce global warming? Give reasons.", "B": "Narrative: Write a story about a natural disaster."}}, {"id": "cv2012-jun-a", "official": true, "year": 2012, "conv": "June 2012", "opt": "A", "label": "PAU June 2012 · Text A", "cat": "Society", "topic": "The Titanic", "color": "#cc7da7", "title": "What the Titanic Means Today", "source": "Time, 13 April 2012", "text": ["A century ago, on an April night in the cold waters of the North Atlantic, a world came to an end. When RMS Titanic struck that iceberg and sank, killing 1,500 people, the disaster became one of those few truly landmark events before which things were one way and after which things were quite another. The great lesson of the disaster is that no matter how smart we think we are, how skilled and how technologically advanced, we remain at the mercy of events beyond our control.", "Writing in 1955, Walter Lord understood the significance of the subject in A Night to Remember. \"The Titanic marked the end of a general feeling of confidence. Until then men felt they had found the answer to a steady and civilized life. For 100 years the Western world had been at peace, technology had steadily improved and the benefits of peace and industry seemed to be filtering satisfactorily through society. The Titanic woke them up. Never again would they be quite so sure of themselves.\"", "It seems fair to argue that the 20th century really began the night the Titanic sank. Two years later came the Great War, and the tragedy of Versailles, and the rise of Hitler, and the splitting of the atom, and so on. Yet perhaps the most interesting part of the centennial of the Titanic for us now lies in the fact that technology, like any other human endeavor, is flawed and subject to disaster. We can never innovate nor create ourselves totally out of harm's way."], "q1": [{"s": "The lesson to learn is that everything is under control when technology is advanced.", "a": "F", "ev": "we remain at the mercy of events beyond our control"}, {"s": "Before the Titanic sank, most people were confident in technology and industrial development.", "a": "T", "ev": "The Titanic marked the end of a general feeling of confidence"}, {"s": "The Great War, the tragedy of Versailles and the rise of Hitler were the real consequences of this tragedy.", "a": "F", "ev": "Two years later came the Great War"}, {"s": "About 1,500 people died when the Titanic sank.", "a": "T", "ev": "killing 1,500 people"}], "q2": [{"q": "What are people supposed to have learnt after the sinking of the Titanic?", "m": "That however intelligent and technologically advanced we are, we can never control everything, so we are still at the mercy of events."}, {"q": "Why does the author suggest that the 20th century really started that day in April?", "m": "Because the sinking ended people's confidence in progress and technology, and soon afterwards came events such as the First World War and the rise of Hitler that marked the century."}], "q3": {"mode": "find", "opts": ["disaster", "landmark", "smart", "mercy", "steady", "flawed"], "items": [["bright", "smart"], ["imperfect", "flawed"], ["transcendental", "landmark"], ["free from change", "steady"]]}, "q4": [{"q": "When the Titanic sank...", "o": ["1,500 people were killed and then the iceberg sank, too.", "1,500 people were struck and killed.", "1,500 people died and the world changed drastically.", "nobody survived the accident."], "a": 2}, {"q": "In 1955, Walter Lord stated that...", "o": ["this tragedy put an end to a period of peace because of the rise of Hitler.", "people would not be so confident any more.", "people were confident with technology and industry before and after this tragedy.", "technology would make the world completely safe."], "a": 1}, {"q": "This tragedy reminds us that technology is...", "o": ["perfect if carefully planned.", "innovative and creative and always safe.", "defective and we cannot be sure of its final results.", "no longer used in ships."], "a": 2}], "q5": {"A": "Do you think that life is possible without technology these days? Give reasons. 2?", "B": "Opinion: Has technology made our lives safer?"}}, {"id": "cv2012-jun-b", "official": true, "year": 2012, "conv": "June 2012", "opt": "B", "label": "PAU June 2012 · Text B", "cat": "Leisure & culture", "topic": "Modern art", "color": "#f6bb83", "title": "Cleaner Ruins 800,000€ Artwork That She Thought Was Dirty", "source": "Adapted from an article published in guardian.co.uk, 3 November 2011", "text": ["An overzealous cleaner in Germany has ruined a piece of modern art worth 800,000€ after mistaking it for an eyesore that needed a good scrub.", "The sculpture, by Martin Kippenberger, had been on loan to the Ostwall Museum in Dortmund. The work, called When It Starts Dripping from the Ceiling, comprised a rubber bucket. Inside the bucket, Kippenberger had spread a layer of paint representing dried rainwater. He thought it was art, but the cleaner saw it as a challenge, and set about making the bucket look like new and removed the patina from the four walls of the bucket.", "\"It is now impossible to return it to its original state.\" a spokeswoman for the museum said. She said that cleaning crews had been told to keep 20cm away from artworks, but it was unclear if the woman had received the memo.", "But Kippenberger is not the only artist to have his works ruined by cleaners. In 1986, a \"grease stain\" by Joseph Beuys valued at about 400,000€ was mopped away at the Academy of Fine Arts in Düsseldorf. In 2004, a cleaner at Tate Britain in London threw away part of a work by another German artist, Gustav Metzger, after mistaking it for rubbish. The cleaner failed to realise that a plastic bag containing discarded paper and cardboard was an integral part of Recreation of First Public Demonstration of Auto-Destructive Art, and not just some litter. The bag was later recovered, but it was too damaged to display, so Metzger replaced it with another bag."], "q1": [{"s": "Kippenberger's sculpture belonged to the Ostwall Museum in Dortmund.", "a": "F", "ev": "had been on loan to the Ostwall Museum in Dortmund"}, {"s": "The cleaner thought Kippenberger's sculpture needed cleaning.", "a": "T", "ev": "mistaking it for an eyesore that needed a good scrub"}, {"s": "The spokeswoman told the cleaner to clean the artwork.", "a": "F", "ev": "cleaning crews had been told to keep 20cm away from artworks"}, {"s": "Metzger's bag could be exhibited again after it was recovered.", "a": "F", "ev": "it was too damaged to display"}], "q2": [{"q": "Why did the cleaner clean the bucket of the sculpture?", "m": "She thought that the layer of paint inside the bucket was dirt, so she cleaned it to make the bucket look new."}, {"q": "What happened to Gustav Metzger's work?", "m": "A cleaner at Tate Britain threw away part of it, a plastic bag full of paper and cardboard, because she thought it was rubbish; it was recovered but too damaged, so Metzger replaced it."}], "q3": {"mode": "find", "opts": ["challenge", "removed", "failed", "litter", "damaged", "display"], "items": [["eliminated", "removed"], ["deteriorated", "damaged"], ["rubbish", "litter"], ["show", "display"]]}, "q4": [{"q": "Someone told the cleaning crews that...", "o": ["they had to keep 20 cm away from artworks.", "they all had to keep 20 cm away from artworks except the cleaning woman.", "they had received the memo.", "they could clean all the artworks."], "a": 0}, {"q": "Joseph Beuys' work was worth...", "o": ["under 400,000€.", "more than 400,000€.", "around 400,000€.", "exactly 800,000€."], "a": 2}, {"q": "In 2004, a cleaner...", "o": ["didn't realise that a plastic bag with discarded paper and cardboard was an artwork.", "replaced a plastic bag with another bag.", "displayed an integral part of Recreation of First Public Demonstration of Autodestructive Art.", "was fired by Tate Britain."], "a": 0}], "q5": {"A": "Do you agree with the statement: \"Modern and contemporary art is not real art\"? Discuss.", "B": "Narrative: Write about a mistake that turned out to be very expensive."}}, {"id": "cv2012-sep-a", "official": true, "year": 2012, "conv": "September 2012", "opt": "A", "label": "PAU September 2012 · Text A", "cat": "Leisure & culture", "topic": "TV piracy", "color": "#f6bb83", "title": "Young Turn to Piracy to Watch Pay TV for Free", "source": "Adapted from an article by Vanessa Thorpe, The Observer, 6 February, 2011", "text": ["Broadcasting analysts are predicting a fresh tide of television piracy with the launch of Sky Atlantic, the satellite channel that has bought the UK rights to many of America's most successful drama series. Fans of popular US shows are already developing new, illicit ways of accessing episodes of the shows they love without the need to pay at least £20 a month to subscribe to Sky. While many non-subscription viewers are still happy to wait for the release of DVD box sets, younger audiences are already resorting to accessing episodes from illegal sites.", "\"If I have a good connection I will download a whole show in bits and see it whenever I like,\" said Jake, from Bournemouth. \"It is not about the money. It is about impatience and getting some power back.\" Jake and his friends tend to watch television on the screens of their Macs, occasionally gathering together around a traditional TV set for live shows.", "The trend is growing among those who are used to accessing music from pirate sites, says John Enser, a partner at media law firm Olswang. \"Young people already know where to move from. And, broadly speaking, they know a legal site from an illegal one,\" said Enser.", "Yet the truth is that few who transgress will ever be fined, or even reprimanded. Broadcasters would not enjoy seeing their name linked to a legal action against a 12-year-old who has downloaded from the wrong place. As a result, the chances of any individual being pursued are tiny."], "q1": [{"s": "The launch of Sky Atlantic will probably increase television piracy.", "a": "T", "ev": "Broadcasting analysts are predicting a fresh tide of television piracy with the launch of Sky Atlantic"}, {"s": "Young people do not distinguish a legal site from an illegal one.", "a": "F", "ev": "they know a legal site from an illegal one"}, {"s": "People who download illegally will definitely be fined.", "a": "F", "ev": "few who transgress will ever be fined, or even reprimanded"}, {"s": "Jake says that he downloads shows mainly to save money.", "a": "F", "ev": "It is not about the money. It is about impatience and getting some power back."}], "q2": [{"q": "Why do young people prefer to access their favourite TV series from pirate sites?", "m": "They are impatient and want to watch the episodes whenever they like; they also want to feel they have some control, not only to save money."}, {"q": "Why will broadcasters avoid undertaking legal action against law transgressors?", "m": "Because they would not like their name to be associated with legal action against a child who downloaded something from the wrong site, which would give them a bad image."}], "q3": {"mode": "find", "opts": ["sets", "bits", "screens", "linked", "chances", "downloaded"], "items": [["monitors", "screens"], ["pieces", "bits"], ["connected", "linked"], ["opportunities", "chances"]]}, "q4": [{"q": "To subscribe to Sky Atlantic...", "o": ["people have to pay £ 20 a month or more.", "people have to pay less than £ 20 a month.", "people need to pay up to £ 20 a month.", "people only need an internet connection."], "a": 0}, {"q": "Many non-subscription viewers...", "o": ["can get a DVD box set of their favourite series at the same time the episodes are broadcast.", "can get a DVD box set of their favourite series after the episodes have been broadcast.", "can get a DVD box set of their favourite series before the episodes are broadcast.", "can never buy DVD box sets."], "a": 1}, {"q": "Watching programs on a traditional TV set ...", "o": ["is getting more and more common among young people.", "is getting less and less common among young people.", "makes young people impatient.", "is only possible for live football matches."], "a": 1}], "q5": {"A": "How can piracy be prevented?", "B": "Opinion: Is it fair to download films and series for free?"}}, {"id": "cv2012-sep-b", "official": true, "year": 2012, "conv": "September 2012", "opt": "B", "label": "PAU September 2012 · Text B", "cat": "Society", "topic": "Solidarity", "color": "#cc7da7", "title": "Alert Pizza Delivery Driver Saves Customer's Life", "source": "By Nick Kenney, 22 February, 2011 WMC-TV", "text": ["A pizza delivery driver was called a hero on Monday after she likely saved an elderly woman's life. Before Monday's incident, most neighbors knew little about Memphis resident Jean Wilson, except that she's eaten pizza daily for the past three years. \"We make her pizza every day before she even calls, because we know she's going to call,\" delivery driver Susan Guy said. Guy often delivers Wilson's regular order, one large pepperoni pizza, but recently workers at her restaurant noticed an unusual break in the pattern. \"She hadn't called in three days,\" Guy said. \"My boss told me about it today.\" Guy insisted to her boss that she be allowed to check on Wilson.", "Guy drove to Wilson's house and knocked on her door, but no one answered. Then, she banged on Wilson's windows, but there was still no response. Running out of options, Wilson ran to neighbor Larry Comeaux's house for help. \"The pizza lady came over and knocked on the door wanting to know if I'd seen the lady across the street,\" Comeaux said. \"And he said, 'No, maybe she's not home,'\" Guy said. \"And I said, 'Well, not home?' I said, 'How many times have you seen her leave?' And he said, 'Never.'\" Guy quickly called 911. When police arrived, they broke down the door to Wilson's home, and found her lying on the floor inside.", "They soon learned that Wilson had fallen on Saturday, and couldn't get over to a telephone to call for help. Investigators said it's possible that her pizza-only diet may have saved her life."], "q1": [{"s": "Jean Wilson's pizza was usually ready by the time she ordered it.", "a": "T", "ev": "We make her pizza every day before she even calls"}, {"s": "Guy's boss went to check on Jean Wilson.", "a": "F", "ev": "Guy insisted to her boss that she be allowed to check on Wilson"}, {"s": "Guy called the police because Jean Wilson had left the house.", "a": "F", "ev": "found her lying on the floor inside"}, {"s": "Wilson's neighbour had often seen her leave the house.", "a": "F", "ev": "How many times have you seen her leave?"}], "q2": [{"q": "What had been unusual about Jean Wilson behavior?", "m": "She ordered a pizza every single day, but she suddenly stopped calling for three days."}, {"q": "What actions did the delivery driver take when he arrived at Jean Wilson's house?", "m": "She knocked on the door and banged on the windows, then went to a neighbour's house for help and finally called 911."}], "q3": {"mode": "find", "opts": ["alert", "likely", "elderly", "noticed", "break", "banged"], "items": [["old", "elderly"], ["probably", "likely"], ["variation", "break"], ["knocked", "banged"]]}, "q4": [{"q": "Jean Wilson's neighbors …", "o": ["knew she was not home.", "did not know much about the old lady.", "knew she followed a pizza-free diet.", "ordered pizza only at weekends."], "a": 1}, {"q": "When Susan Guy arrived at Wilson's home, she…", "o": ["went over to the neighbor's house for help.", "broke Jean Wilson's window and called the police.", "broke into Jean Wilson's house.", "waited in the car for the police."], "a": 0}, {"q": "Jean Wilson…", "o": ["rarely left the house.", "could not call for help because she did not have a phone.", "drove to the pizza place to get a large pepperoni pizza every day.", "had moved to another city."], "a": 0}], "q5": {"A": "Do you think people show solidarity and help each other nowadays? Give reasons.", "B": "Narrative: Write about a time when you helped a stranger."}}, {"id": "cv2013-jun-b", "official": true, "year": 2013, "conv": "June 2013", "opt": "B", "label": "PAU June 2013 · Text B", "cat": "Society", "topic": "Teenagers", "color": "#cc7da7", "title": "Teen Spirit: What's It Really Like to Be a Teenager?", "source": "Charlotte Philby, The Independent, 14 July 2012", "text": ["15-year-old Ellie Wilson says \"The problem with being a teenager is that one minute we're up and then we're down; one minute I want to shout the house down, the next I feel very happy.\" The turbulent process of becoming an adult is one that for generations has baffled parents and scientists. When almost every other species manages the transition from infancy to adulthood with relative ease, why do we seem to find it so hard?", "First we blamed hormones. Then scientists found that the human mind undergoes a massive restructuring during the 12th to 25th years. Between childhood and adulthood, critical physical changes are taking place. These result in behaviours that parents might have thought were designed to cause them pain, but which are in fact vital processes in the brain's development. The truth remains that science offers a rational explanation, but it doesn't make everyday communication with teenagers any easier. Which is where Lovegrove and Bedwell step in. These friends published a book, Teenagers Explained, that was designed to help adults understand adolescence. Because \"there are things we talk about that adults just don't understand.\" \"Try to let us make our own mistakes,\" pleads Lovegrove. \"If we don't get to make our own mistakes when we're young then, at some point, as soon as you're not around, we're just going to explode. It's OK to be concerned and to ask questions but please don't question us on everything. Do try to talk to us and make an effort to get to know us, but also understand that there are some things we don't want to talk to you about.\""], "q1": [{"s": "Scientists first thought that hormones explained teenage behaviour.", "a": "T", "ev": "First we blamed hormones"}, {"s": "Teenage behaviour is closely related to how the brain develops.", "a": "T", "ev": "which are in fact vital processes in the brain's development"}, {"s": "Scientific discoveries have helped parents get on with their sons and daughters.", "a": "F", "ev": "it doesn't make everyday communication with teenagers any easier"}, {"s": "Lovegrove asks parents to stop asking questions completely.", "a": "F", "ev": "It's OK to be concerned and to ask questions but please don't question us on everything"}], "q2": [{"q": "Why do teenagers behave the way they do?", "m": "Because their brains go through a huge restructuring between the ages of 12 and 25, and these changes are necessary for the brain to develop."}, {"q": "Why was the book Teenagers Explained published?", "m": "Two teenage friends wrote it to help adults understand adolescents, because there are things teenagers talk about that adults do not understand."}], "q3": {"mode": "find", "opts": ["baffled", "transition", "hard", "massive", "vital", "concerned"], "items": [["shift", "transition"], ["worried", "concerned"], ["puzzled", "baffled"], ["huge", "massive"]]}, "q4": [{"q": "Teenagers' behaviour...", "o": ["causes an acceleration of a massive restructuring of the mind.", "causes a massive restructuring of their minds.", "is caused by a massive restructuring of their minds.", "has no relation to the brain."], "a": 2}, {"q": "Science…", "o": ["has really helped parents communicate with their teenage sons and daughters.", "has not really helped parents communicate with their teenage sons and daughters.", "has really helped teenagers communicate with their teenage friends.", "has made teenagers' lives more difficult."], "a": 1}, {"q": "Lovegrove...", "o": ["thinks that parents' concern and questions are understandable.", "thinks that parents' concern and questions are unnecessary.", "thinks that parents' concern and questions will make teenagers explode.", "thinks parents should never talk to teenagers."], "a": 0}], "q5": {"A": "How is your life as a teenager nowadays? Discuss.", "B": "Narrative: Write about a day when you and your parents disagreed about something important."}}, {"id": "cv2013-jul-a", "official": true, "year": 2013, "conv": "July 2013", "opt": "A", "label": "PAU July 2013 · Text A", "cat": "Health", "topic": "Tobacco", "color": "#ef908a", "title": "Cigarettes May Have to Be Sold in Plain Packets", "source": "David Batty, The Guardian, 13 April 2012", "text": ["Cigarette packets could be stripped of all branding following a consultation, the health secretary, Andrew Lansley, has revealed. The minister said that he was \"open minded\" about putting the idea of plain cigarette packaging to the public, but added: \"We don't work in partnership with the tobacco companies because we are trying to arrive at a point where they have no business in this country.\" Deborah Arnott, of Action on Smoking and Health, said: \"The consultation is just the first step, putting us in pole position to be the first European nation to put tobacco in plain, standardised packs. \"Cigarettes are not like sweets or toys and should not be sold in colourful packaging which makes them appealing to children. Cigarettes are full of toxins and cause fatal diseases: plain, standardised packaging makes this explicit.\"", "But pro-smoking group Forest, the Freedom Organisation for the Right to Enjoy Smoking Tobacco, has launched a Hands Off Our Packs (Hoops) campaign. Director Simon Clark has described plain packaging as \"the persecution of a minority lifestyle choice\". He said: \"Plain packaging is yet another attack on retailers and adult consumers.\"", "The move comes a week after a law on tobacco promotion in England came into force, requiring all large shops and supermarkets to cover up cigarettes and hide tobacco products from public view. Lansley, who said that all levels of smoking are harmful, added that the ban on displaying cigarettes was part of a move to ensure \"we no longer see smoking as a part of life.\""], "q1": [{"s": "According to the minister, companies will always have the right to sell cigarettes in England.", "a": "F", "ev": "we are trying to arrive at a point where they have no business in this country"}, {"s": "According to Arnott, standardized packaging makes it clear that tobacco is dangerous.", "a": "T", "ev": "plain, standardised packaging makes this explicit"}, {"s": "According to Lansley, some levels of smoking are not dangerous.", "a": "F", "ev": "all levels of smoking are harmful"}, {"s": "Large shops must now hide tobacco products from customers.", "a": "T", "ev": "requiring all large shops and supermarkets to cover up cigarettes and hide tobacco products from public view"}], "q2": [{"q": "Why should cigarettes be sold in plain packets?", "m": "Because colourful packets make cigarettes attractive, especially to children, while plain packets show clearly that they are toxic and cause deadly diseases."}, {"q": "Why was tobacco hidden from public view in large shops and supermarkets?", "m": "Because a new law wants people to stop seeing smoking as a normal part of life, so tobacco products must not be on display."}], "q3": {"mode": "find", "opts": ["plain", "appealing", "cause", "choice", "requiring", "ban"], "items": [["prohibition", "ban"], ["attractive", "appealing"], ["generic", "plain"], ["demanding", "requiring"]]}, "q4": [{"q": "The minister wants to reach a point in which...", "o": ["tobacco companies hide their product from public view.", "tobacco companies can't sell cigarettes in England.", "tobacco companies use the same colourful packaging.", "tobacco companies pay higher taxes."], "a": 1}, {"q": "England...", "o": ["is the first European nation in which cigarettes are sold in plain packaging.", "will not be the first European nation in which cigarettes are sold in plain packaging.", "might be the first European nation in which cigarettes are sold in plain packaging.", "has banned smoking completely."], "a": 2}, {"q": "The pro-smoking group Forest...", "o": ["thinks that plain packaging is an aggression on smokers' freedom of choice.", "thinks that plain packaging should not be hidden from public view.", "thinks that plain packaging will not attract children.", "is financed by the government."], "a": 0}], "q5": {"A": "What measures can be taken to prevent people from smoking?", "B": "For and against: Should smoking be banned in all public places, including outdoor areas?"}}, {"id": "cv2013-jul-b", "official": true, "year": 2013, "conv": "July 2013", "opt": "B", "label": "PAU July 2013 · Text B", "cat": "Technology", "topic": "Tablets", "color": "#7ec9e6", "title": "Tablets to Beat Desktop Sales", "source": "Daily Mail, 29 March 2013", "text": ["Tablet computers are set to beat bulky desktops for the first time this year, according to research. Millions are replacing their old-fashioned computers with slimline, touchscreen gadgets.", "Sales of tablets such as Apple's iPad and Google's Nexus are about to overtake the type of computers that introduced the internet to the masses, said the International Data Corporation (IDC).The IDC said 128 million tablets were sold last year worldwide, an increase of nearly 80 per cent in 2011.The trend represents a rapid transformation in computer use, just three years after Apple introduced the iPad. And the growth in sales is forecast to continue, meaning tablets will overtake desktops in months and outsell laptops by the end of next year.", "Experts said that computers are seen as a device for work, but tablets are preferred for leisure activities, such as surfing the web and watching videos. Technology researcher Martin Garner, from CCS Insight, said: \"People are using the money they previously used to replace a PC to buy a tablet. In the long term, nearly every person will have their own tablet.\"", "The battle for domination of the mobile and tablet market has become intense in the past 18 months, with Apple's competitors taking it on with a series of new products. Nokia and Microsoft joined forces to launch two new phones which run on the Windows operating system. Apple registered figures for the Christmas period that showed its rocket-like growth had come to a standstill."], "q1": [{"s": "Desktops are slimline, touchscreen gadgets.", "a": "F", "ev": "replacing their old-fashioned computers with slimline, touchscreen gadgets"}, {"s": "Instead of buying a new desktop, people are now buying a tablet.", "a": "T", "ev": "People are using the money they previously used to replace a PC to buy a tablet"}, {"s": "Apple increased its sales a lot during the Christmas period.", "a": "F", "ev": "its rocket-like growth had come to a standstill"}, {"s": "Tablet sales are expected to keep growing.", "a": "T", "ev": "the growth in sales is forecast to continue"}], "q2": [{"q": "Can you explain what is changing in relation to computer use?", "m": "People are replacing traditional desktop computers with tablets, whose sales are growing fast and will soon be higher than those of desktops and even laptops."}, {"q": "What differences in use are there between desktops and tablets?", "m": "Desktops are mainly used for work, while tablets are preferred for leisure activities, such as browsing the internet or watching videos."}], "q3": {"mode": "find", "opts": ["overtake", "trend", "forecast", "device", "launch", "standstill"], "items": [["machine", "device"], ["start", "launch"], ["estimated", "forecast"], ["tendency", "trend"]]}, "q4": [{"q": "The IDC found that nearly 80%…", "o": ["of the computers sold last year were tablets.", "of the tablets are either iPad or Nexus.", "was the rising rate of tablets sold last year.", "of desktops were sold by Apple."], "a": 2}, {"q": "Experts state that computers are chosen to work, …", "o": ["and considered essential for leisure activities.", "to surf the web and to watch videos.", "and not so much for leisure activities.", "and are never used at home."], "a": 2}, {"q": "During the Christmas period …", "o": ["Apple made more profits than ever before.", "Apple made lower profits than ever before.", "Apple's sales slowed down.", "Nokia stopped making phones."], "a": 2}], "q5": {"A": "What are the benefits of using tablets? Can you think of any disadvantages? 4?", "B": "Opinion: Should tablets replace textbooks at school?"}}, {"id": "cv2014-jun-a", "official": true, "year": 2014, "conv": "June 2014", "opt": "A", "label": "PAU June 2014 · Text A", "cat": "Environment", "topic": "Polar ice", "color": "#7eb991", "title": "Research Ship Trapped in Antarctic Ice Because of Weather, Not Climate Change", "source": "Adapted from an article by John Turner, theguardian.com, 3 January 2014", "text": ["The Russian ship Akademik Shokalskiy is stuck in the Antarctic, in an area where there has been an increase in sea ice extent since the late 1970s, making ship operations difficult. Is this situation evidence that global warming is exaggerated?", "The impact of climate change on ice at both poles is complex. Actually, the two polar regions have experienced very different trends in ice extent. Arctic sea ice has been declining in extent in every month of the year, with the maximum loss of almost 14% per decade being found in September. In contrast, sea ice extent around the Antarctic has increased in every month of the year with the largest increase being almost 4% per decade in March.", "The reasons for the trends in sea ice are still being debated. However, for the Arctic it is estimated that the emission of greenhouse gases has contributed 50-60% of the decline of Arctic sea ice. The remaining contribution is believed to come from natural variability. But in the Antarctic the reason for the increase in ice is less clear. The pattern of sea ice change around the Antarctic is dominated by a decrease to the west of the Antarctic Peninsula and an increase across the Ross Sea, which can be attributed to more storm activity between these two areas and to the strength and direction of the winds. This pattern of change is consistent with the increasing temperatures observed over the west Antarctica, where temperatures have risen as much as anywhere in the southern hemisphere."], "q1": [{"s": "The Arctic region has had an increase of sea ice throughout the year, and mainly in September.", "a": "F", "ev": "Arctic sea ice has been declining in extent in every month of the year"}, {"s": "Scientists know the causes of the trends in sea ice.", "a": "F", "ev": "The reasons for the trends in sea ice are still being debated"}, {"s": "The decrease in sea ice in the west of the Antarctic Peninsula can be attributed to higher temperatures.", "a": "T", "ev": "This pattern of change is consistent with the increasing temperatures observed over the west Antarctica"}, {"s": "Sea ice around the Antarctic has increased.", "a": "T", "ev": "sea ice extent around the Antarctic has increased in every month of the year"}], "q2": [{"q": "Why is the impact of climate change on ice at both poles complex?", "m": "Because the two poles show very different trends: Arctic ice is decreasing while Antarctic ice is increasing, and scientists are still discussing the reasons."}, {"q": "Which factors influence the patterns of sea ice change in the Antarctic?", "m": "The changes are linked to more storms between the Antarctic Peninsula and the Ross Sea, to the strength and direction of the winds and to rising temperatures in west Antarctica."}], "q3": {"mode": "find", "opts": ["impact", "actually", "declining", "loss", "strength", "remaining"], "items": [["indeed", "actually"], ["force", "strength"], ["effect", "impact"], ["decreasing", "declining"]]}, "q4": [{"q": "Ship operations in the Antarctic...", "o": ["have not varied since the late 1970s.", "do not depend on the amount of ice in the area.", "are not easy because the sea ice in the area has increased.", "are forbidden by Russia."], "a": 2}, {"q": "Greenhouse gas emissions are estimated...", "o": ["to have contributed to the decrease of sea ice in the two polar regions.", "to have contributed partly to the decrease of sea ice in the Arctic.", "to come from natural variability.", "to be the only cause of the increase in Antarctic ice."], "a": 1}, {"q": "Sea ice in the Antarctic has declined in extent...", "o": ["across the Ross Sea.", "in the west of the Peninsula.", "in the southern region.", "all over the continent."], "a": 1}], "q5": {"A": "How is climate change affecting us?", "B": "Opinion: Is enough being done to fight climate change?"}}, {"id": "cv2014-jun-b", "official": true, "year": 2014, "conv": "June 2014", "opt": "B", "label": "PAU June 2014 · Text B", "cat": "Technology", "topic": "Digital divide", "color": "#7ec9e6", "title": "Rural Americans Have Inferior Internet Access", "source": "Adapted from an article by Emily Guerin, High Country News, 3 February 2014", "text": ["The 260 residents of Ten Sleep, Wyoming, drive at least 26 miles to buy groceries and 112 to catch a plane. You wouldn't expect an Internet entrepreneur to launch a startup here. But in 2006, Kent Holiday did just that, opening Eleutian Technology, where local teachers tutor Asian students in English through live online videos. He now employs about 500 teachers around the region.", "Holiday was visiting his in-laws when he noticed the local telephone utility laying fiber-optic cable: Ten Sleep was getting high-speed Internet. In 2011, President Obama used Eleutian as an example of the Internet's effects on rural economic development: \"For local businesses, broadband access is helping them grow, prosper and compete in a global economy.\"", "But such access - the basic modern infrastructure many city-folk take for granted - is far from universal. Of the 19 million Americans who lack broadband access 14.5 million live in rural areas. Thirty percent of Indians living on reservations also lack access.", "The more densely populated a place is, the more likely it is to have fast, affordable Internet. When people live far apart, service providers don't profit enough to cover the costs of building and maintaining the physical infrastructure. If they do provide access, it's often at higher prices and slower speeds than in urban areas. In the rural West, where 2 million people lack broadband access, topography is also a barrier. Mountains and narrow valleys can block signals from wireless towers and satellites and make it difficult to install fiber-optic cables."], "q1": [{"s": "In theory, the population and location of Ten Sleep are not attractive characteristics for Internet entrepreneurs.", "a": "T", "ev": "You wouldn't expect an Internet entrepreneur to launch a startup here"}, {"s": "Around 75% of the American population without broadband access lives in rural areas.", "a": "T", "ev": "Of the 19 million Americans who lack broadband access 14.5 million live in rural areas"}, {"s": "Signals from wireless towers and satellites are always accessible.", "a": "F", "ev": "Mountains and narrow valleys can block signals from wireless towers and satellites"}, {"s": "Kent Holiday's company teaches Spanish to American students.", "a": "F", "ev": "local teachers tutor Asian students in English through live online videos"}], "q2": [{"q": "According to President Obama, how can broadband access favour local economic development?", "m": "He said that fast Internet connections help local companies to grow, become more successful and compete with businesses all over the world."}, {"q": "Why is it difficult to get broadband access in rural areas?", "m": "Because when people live far from each other, companies do not earn enough to pay for the infrastructure, and mountains and valleys can block signals and make it hard to install cables."}], "q3": {"mode": "find", "opts": ["groceries", "entrepreneur", "prosper", "lack", "provide", "barrier"], "items": [["succeed", "prosper"], ["supply", "provide"], ["businessperson", "entrepreneur"], ["food", "groceries"]]}, "q4": [{"q": "Eleutian Technology employs teachers living in...", "o": ["many different parts in the world.", "Ten Sleep only.", "Wyoming.", "only big cities."], "a": 2}, {"q": "Holiday discovered that...", "o": ["broadband Internet connection was being laid in Ten Sleep.", "people at Ten Sleep were getting new telephone lines.", "people at Ten Sleep had access to cable TV.", "there was no electricity in the town."], "a": 0}, {"q": "In areas which are not densely populated, Internet service providers offer...", "o": ["the same prices and speed as in densely populated areas.", "better prices and speed than in densely populated areas.", "worse prices and speed than in densely populated areas.", "free Internet to every home."], "a": 2}], "q5": {"A": "Could you live in a world without access to the Internet?", "B": "For and against: Living in a small village or in a big city."}}, {"id": "cv2014-jul-a", "official": true, "year": 2014, "conv": "July 2014", "opt": "A", "label": "PAU July 2014 · Text A", "cat": "Work", "topic": "Women entrepreneurs", "color": "#c3a48e", "title": "Spain's Jobless Women Become the Boss to Beat the Recession", "source": "Adapted from an article by Ashifa Kassam, The Guardian, 3 February 2014", "text": ["When it comes to finding a job in Europe, not all citizens are born equal. If you are Spanish you have a one in four chance of being unemployed, rising to one in two if you are young. And if you are a young woman in Spain? The chances of finding yourself among the unemployed are even higher, at 54.7%. Now however, young Spanish women are finding their own solutions to the crisis, discovering the value of enterprises that has resulted in a record 800,000 businesses being set up by women in the past five years. \"The crisis allowed women to seriously consider becoming businesswomen, something many had never thought of before,\" said Joan Torrent Sellens. In the past decades Spanish women have advanced in government and the public sector, but are still behind in setting up enterprises, creating less than 20% of businesses. When analysing the same figures during the crisis, Torrent Sellens found a surprising result: the number of businesses created by women had nearly doubled during the crisis, to just under 40%. \"These days you can act like a big businessman without having a lot of employees,\" said Torrent Sellens. \"The crisis allowed women to ask: 'Why do I have to be a director at a multinational, earning a third of what my male counterparts are earning when I can create, my own business and lead my own project?' The crisis gave them an alternative, their own way of breaking through the glass ceiling,\" he added."], "q1": [{"s": "Young people in Spain have a one in two chance of being unemployed.", "a": "T", "ev": "rising to one in two if you are young"}, {"s": "Spanish women have advanced in certain sectors during the past decades.", "a": "T", "ev": "In the past decades Spanish women have advanced in government and the public sector"}, {"s": "Women can only be successful in business if they have a lot of employees.", "a": "F", "ev": "These days you can act like a big businessman without having a lot of employees"}, {"s": "Women created more businesses before the crisis than during it.", "a": "F", "ev": "the number of businesses created by women had nearly doubled during the crisis"}], "q2": [{"q": "Why are young Spanish women now starting so many new businesses?", "m": "Because unemployment among young women is extremely high, so the crisis made them consider starting their own businesses as a way to find work."}, {"q": "What are the benefits of owning a business if you are a woman?", "m": "They can lead their own projects instead of earning much less than men in a big company, and in this way they break through the glass ceiling."}], "q3": {"mode": "find", "opts": ["chance", "rising", "resulted in", "set up", "surprising", "alternative"], "items": [["created", "set up"], ["option", "alternative"], ["led", "resulted in"], ["possibility", "chance"]]}, "q4": [{"q": "Setting up a business is the strategy that Spanish women have used...", "o": ["to earn a higher salary than men.", "to solve the crisis in Spain.", "to avoid unemployment.", "to move to other countries."], "a": 2}, {"q": "In the past decades, Spanish women...", "o": ["have not made serious advances in creating private businesses.", "have created a lot of jobs for men at the government and public sector.", "have made advances in 20% of enterprises in the public sector.", "have stopped working in the public sector."], "a": 0}, {"q": "If women create their own businesses they can...", "o": ["become managers at multinationals.", "lead their own business initiatives.", "get a lot of employees in their enterprises.", "earn the same as men at multinationals."], "a": 1}], "q5": {"A": "What are the advantages and disadvantages of starting your own business?", "B": "Opinion: Is there still a glass ceiling for women at work?"}}, {"id": "cv2014-jul-b", "official": true, "year": 2014, "conv": "July 2014", "opt": "B", "label": "PAU July 2014 · Text B", "cat": "Education", "topic": "Flipped classroom", "color": "#b3a5cc", "title": "Turning Education Upside Down", "source": "Adapted from an article by T. Rosenberg, The New York Times, October 2013", "text": ["Three years ago, Clintondale High School became a \"flipped school,\" one where students watch teachers' lectures at home and do what we'd otherwise call \"homework\" in class. Teachers record video lessons, which students watch on their smartphones, home computers or at lunch in the school's tech lab. In class, they do projects, exercises or lab experiments while the teacher circulates.", "Now flipped classrooms are popping up all over. Havana High School (Illinois) is flipping, too, after the school superintendent visited Clintondale. The principal of Clintondale says that some 200 school officials have visited them.", "It's well known by now that online education is booming. You can study any subject free in a massive open online course. Courses are being offered by universities like Harvard and by the teenager next door making videos in his garage. But while online courses can make high-quality education available to anyone with an Internet connection, they also have the potential to displace humans, with all that implies for teachers and students.", "Like everything innovative, online education is highly controversial. But the flipped classroom is a strategy that nearly everyone agrees on. \"It's the only thing I write about as having broad positive agreement,\" said Justin Reich, from Harvard University.", "Flipping is still in the early stages, with much experimentation about how to do it right. Flipping's track record in schools, while impressive, is anecdotal and short. But many people are holding it up as a potential model of how to use technology to humanize the classroom."], "q1": [{"s": "Officials from other schools have shown an interest in Clintondale High School.", "a": "T", "ev": "some 200 school officials have visited them"}, {"s": "Online education is becoming increasingly popular.", "a": "T", "ev": "online education is booming"}, {"s": "Online courses are only offered by highly qualified institutions.", "a": "F", "ev": "by the teenager next door making videos in his garage"}, {"s": "Everybody agrees that online education is positive.", "a": "F", "ev": "online education is highly controversial"}], "q2": [{"q": "What is a flipped school?", "m": "It is a school where students watch the teachers' explanations on video at home and do exercises, projects and experiments in class with the teacher's help."}, {"q": "What are some of the advantages of online courses?", "m": "They allow anyone with an Internet connection to study almost any subject for free, often with high-quality materials from universities like Harvard."}], "q3": {"mode": "find", "opts": ["popping up", "booming", "available", "displace", "controversial", "impressive"], "items": [["accessible", "available"], ["expanding", "booming"], ["outstanding", "impressive"], ["relegate", "displace"]]}, "q4": [{"q": "In a flipped classroom…", "o": ["homework is done at school.", "the teacher has to do less work.", "students have to work harder.", "students never use smartphones."], "a": 0}, {"q": "According to the article…", "o": ["online courses are never free.", "almost anyone can develop an online course.", "online education is free of controversy.", "online courses are only offered by Harvard."], "a": 1}, {"q": "Many people…", "o": ["seem to agree on flipped classrooms.", "think that flipped classrooms do not require further experimentation.", "find that flipped classrooms dehumanize education.", "think flipped classrooms should be banned."], "a": 0}], "q5": {"A": "What are the advantages of online courses compared to traditional education?", "B": "For and against: Should homework be eliminated?"}}, {"id": "cv2015-jun-a", "official": true, "year": 2015, "conv": "June 2015", "opt": "A", "label": "PAU June 2015 · Text A", "cat": "Technology", "topic": "Wearable tech", "color": "#7ec9e6", "title": "The Rise of Wearable Technology", "source": "Adapted from an article by Dominic Rushe, The Observer.", "text": ["Wearable technology (the one you wear on your body) is hardly a new phenomenon. But thanks to the internet and computing speed, a whole new world of possibilities is opening up, and with it comes a lot of questions that may eclipse all previous debate over online privacy.", "Governments around the world are pouring money into wearable tech. US soldiers have been testing a device that can locate the exact place of gunfire and display it on a small screen attached to a soldier's body armour. Devices are also being used to monitor soldiers' health. Many of these technologies are likely to filter down to civilian life. Indeed, wearable technology makes you look at technology in a different way. We are moving to a world where technology interacts with us -you are not just staring at a screen. It is suggesting things to you. Maybe go for a walk, or reminding you that you need to shop for food.", "But supporters of privacy are increasingly concerned. People need to be very careful about the ways in which they adopt technology. There is always an issue with who uses your data. Who else is seeing this? Employers? Insurance companies? Much of these data will be stored in the \"cloud\", which is not secure. And this is just the start. Google's glasses will potentially be watching your every move. Do you really need another device? There's a lot of money betting that you soon will and this new device will look a lot like something you own already (a belt, a watch, glasses). The body is the new tech battleground, and wearable tech may be about to become the 21st-century version of body armour."], "q1": [{"s": "Wearable technology has just been discovered.", "a": "F", "ev": "Wearable technology (the one you wear on your body) is hardly a new phenomenon"}, {"s": "Technology applied to soldiers will never be applied to people in general.", "a": "F", "ev": "Many of these technologies are likely to filter down to civilian life"}, {"s": "Wearable technology is not radically different from what you wear already.", "a": "T", "ev": "this new device will look a lot like something you own already"}, {"s": "Data stored in the cloud are completely safe.", "a": "F", "ev": "which is not secure"}], "q2": [{"q": "Why does wearable technology make us look at technology in a different way?", "m": "Because instead of just looking at a screen, the technology interacts with us and makes suggestions, for example reminding us to go for a walk or to buy food."}, {"q": "Why is there an issue with who uses your data?", "m": "Because we do not know who can see our personal data, such as employers or insurance companies, and the cloud where they are stored is not safe."}], "q3": {"mode": "find", "opts": ["eclipse", "locate", "monitor", "concerned", "secure", "move"], "items": [["spot", "locate"], ["safe", "secure"], ["shadow", "eclipse"], ["control", "monitor"]]}, "q4": [{"q": "The new possibilities created by wearable technology...", "o": ["provide a solution to the issue of privacy.", "raise further dilemmas about privacy.", "destroy human privacy altogether.", "are only useful for soldiers."], "a": 1}, {"q": "We have to be careful about how we adopt technology because…", "o": ["with technology, our data are only private in the cloud.", "with technology, our data are given to employers when contracting people.", "with technology, we are losing our right to privacy.", "technology is always free."], "a": 2}, {"q": "Technological companies...", "o": ["think that you will only buy technology that looks like something you own.", "think that wearable technology is something you will soon need.", "think that betting money on wearable technology is not profitable.", "have stopped investing in wearables."], "a": 1}], "q5": {"A": "What do you think of wearable technology? Has it got any future in your opinion? 2?", "B": "Narrative: Imagine a day in 2050 wearing smart devices. Describe what happens."}}, {"id": "cv2015-jun-b", "official": true, "year": 2015, "conv": "June 2015", "opt": "B", "label": "PAU June 2015 · Text B", "cat": "Education", "topic": "Bilingualism", "color": "#b3a5cc", "title": "Bilingual Brains: Variety Makes You Mentally Fit", "source": "Adapted from The Economist, 17th October, 2014", "text": ["For years, researchers in bilingualism have reported findings about how bilingualism affects the brain. Two of the most memorable involve \"executive control\" and delayed dementia. With the first, bilinguals have shown that they are better able to focus on demanding mental tasks despite distractions. In other studies, it has been estimated that bilinguals see the initial stages of dementia, on average, about five years later than monolinguals do.", "This week comes new evidence. Researchers led by Roberto Filippi of Anglia Ruskin University have found that young bilingual pupils did a better job answering tricky questions with a noisy voice in the background than a monolingual group. The researchers in this line of inquiry tend to share a common hypothesis: that being bilingual is a kind of constant mental exercise. With two languages in the mind, every time a thing is named, an alternative must be suppressed. Every time a sentence is constructed, the other way of constructing it must be suppressed.", "Blocking out distracting information is exactly what researchers find that bilinguals do well. And as for dementia, the effect seems to be a kind of analogue to physical activity over the course of a lifetime keeping a body fit. Mental exercise keeps the brain fit, and bilingualism is just that kind of exercise.", "Why bilinguals seem to do better in quite a few differently designed studies does, however, need more research. Besides, some parents still think that bilingualism might harm a child's development."], "q1": [{"s": "Bilingualism may delay mental illnesses.", "a": "T", "ev": "bilinguals see the initial stages of dementia, on average, about five years later than monolinguals do"}, {"s": "Bilingualism keeps the brain fit.", "a": "T", "ev": "Mental exercise keeps the brain fit, and bilingualism is just that kind of exercise"}, {"s": "Parents always think that bilingualism may influence their children's development.", "a": "F", "ev": "some parents still think that bilingualism might harm a child's development"}, {"s": "Monolingual pupils were better than bilinguals at answering difficult questions with noise in the background.", "a": "F", "ev": "young bilingual pupils did a better job answering tricky questions with a noisy voice in the background than a monolingual group"}], "q2": [{"q": "What have bilinguals shown regarding \"executive control\"?", "m": "They have shown that they can concentrate better on difficult mental tasks even when there are distractions."}, {"q": "What did Filippi and other colleagues find?", "m": "They found that bilingual children answered difficult questions better than monolingual children when there was a noisy voice in the background."}], "q3": {"mode": "find", "opts": ["dementia", "average", "evidence", "tricky", "inquiry", "hypothesis"], "items": [["investigation", "inquiry"], ["proof", "evidence"], ["insanity", "dementia"], ["premise", "hypothesis"]]}, "q4": [{"q": "Researchers…", "o": ["have studied the effects of bilingualism for years.", "have just discovered the benefits of bilingualism.", "have found a relationship between physical activity and bilingualism.", "have proved that bilingualism causes dementia."], "a": 0}, {"q": "The effect of bilingualism on dementia is…", "o": ["different from the effect of physical activity on keeping a body fit.", "similar to the effect of physical activity on keeping a body fit.", "exactly the same as the effect of physical activity on keeping a body fit.", "the cause of physical activity."], "a": 1}, {"q": "More research is needed…", "o": ["to examine design studies differently.", "to examine why bilinguals do better than monolinguals.", "to examine why bilingualism might damage children's development.", "to stop children learning two languages."], "a": 1}], "q5": {"A": "In your opinion, what are the advantages of multilingual education?", "B": "Narrative: Write about your experience learning a foreign language."}}, {"id": "cv2015-jul-a", "official": true, "year": 2015, "conv": "July 2015", "opt": "A", "label": "PAU July 2015 · Text A", "cat": "Society", "topic": "Child poverty", "color": "#cc7da7", "title": "Child Poverty in Spain Seen Through the Eyes of Encarni", "source": "Inter Press Service News Agency, 1st November, 2014", "text": ["\"I would like to have a big house, and I wish my family didn't have to go out and ask for food or clothes,\" Encarni, who just turned 12, is one of the faces of child poverty in Spain. Almost every day, she goes with her mother and her aunt to get food at the Er Banco Güeno, a soup kitchen which has been operating for the last two years. \"I worked in construction until the start of the 2008 crisis, when I was laid off,\" Encarni's stepfather says. Since then he has not found work, and has done a little of everything, from picking up junk to selling things in street markets. Encarni explains that her mother found work for a couple of months taking care of an elderly person, but was fired.", "\"I really like to go to school. I especially love gymnastics,\" Encarni says, although she adds that she gets sad when she feels they leave her out sometimes, \"because they saw me go into the soup kitchen for food. But I just ignore them,\" she adds.", "A few days ago her aunt and three cousins moved to another house nearby. But until then there were 11 people living in Encarni's house. She slept in the top bunk with her cousin while the other members of her family slept in the rest of the rooms of the house, which only has one small bathroom near the kitchen.", "Encarni wants to be a judge when she grows up. But she says that for now she would be happy just to be able to \"dress well\" and be able to buy more things in the supermarket."], "q1": [{"s": "Her mother is looking after an old woman.", "a": "F", "ev": "her mother found work for a couple of months taking care of an elderly person, but was fired"}, {"s": "She has been sharing the same room with other eleven people.", "a": "F", "ev": "She slept in the top bunk with her cousin while the other members of her family slept in the rest of the rooms"}, {"s": "In the future, she would like to study Law.", "a": "T", "ev": "Encarni wants to be a judge when she grows up"}, {"s": "Encarni's stepfather lost his job when the 2008 crisis started.", "a": "T", "ev": "I worked in construction until the start of the 2008 crisis, when I was laid off"}], "q2": [{"q": "What are Encarni's hopes for the future?", "m": "She would like to become a judge, and for now she would be happy to wear nice clothes, buy more food and not have to ask for help."}, {"q": "Why does Encarni feel she is sometimes rejected by other people?", "m": "Because some classmates have seen her going into the soup kitchen and sometimes they exclude her for that reason."}], "q3": {"mode": "find", "opts": ["poverty", "laid off", "stepfather", "junk", "elderly", "moved"], "items": [["trash", "junk"], ["neediness", "poverty"], ["senile", "elderly"], ["made redundant", "laid off"]]}, "q4": [{"q": "She goes very often to a place…", "o": ["where her mother gets some money.", "where jobs are provided to people.", "where food is served to the poor.", "where she does gymnastics."], "a": 2}, {"q": "She feels unhappy…", "o": ["when some people reject her.", "when some people give food to her family.", "when some people see her queuing.", "when she goes to school."], "a": 0}, {"q": "Encarni would like…", "o": ["to grow up and help her family.", "to wear better clothes and buy more food.", "to sell things in a street market.", "to live in another country."], "a": 1}], "q5": {"A": "Write about the problems of unemployment among young people in Spain.", "B": "Opinion: What can be done to reduce child poverty?"}}, {"id": "cv2015-jul-b", "official": true, "year": 2015, "conv": "July 2015", "opt": "B", "label": "PAU July 2015 · Text B", "cat": "Technology", "topic": "Instagram", "color": "#7ec9e6", "title": "Do the Instagram Stars Show We're Now All Living in a False Reality?", "source": "Adapted from an article by Bella Mackie, The Guardian, 27th November, 2014", "text": ["Celebrities have always been paid to promote products through social media. But increasingly, Instagram users without real-world fame are cashing in too. While you've been putting up photos of your dog, others have been busy building up their own brand identity. Companies have sprung up that encourage followers to buy the clothes on your back, the pillows on your bed, the bowl your cat eats from... You can now assemble your identity through photos that shape your style and your home. One of the first Instagram stars was a woman called Jen Selter, who got noticed after posting multiple shots of the results of her fitness regime. Looking through her photos you can see why people feel compelled to follow her: an ordinary girl who encourages you to work out for similar results. Much has been written about celebrity culture -the dangers of attempting to emulate our favourite Hollywood heroes. Why are these new insta-celebs any different? They're not sharing spontaneous moments or candid pictures that give you a realistic look at their lives, they're presenting a stage set. The idea behind it is to make you believe that if you spend enough, work out enough, you can be like them. And it works, because they're not megastars but people like you. This is why you think their status is achievable.", "When your own life becomes your job, though, you're bound to present it dishonestly. Let's demand a bit more reality, and present a more honest version of our own lives in response. We might find that there is no need to emulate a life that reaches us only through a heavily filtered lens."], "q1": [{"s": "Only famous celebrities are paid to promote products through social media.", "a": "F", "ev": "increasingly, Instagram users without real-world fame are cashing in too"}, {"s": "Instagram stars do not present their real lives.", "a": "T", "ev": "They're not sharing spontaneous moments or candid pictures that give you a realistic look at their lives, they're presenting a stage set"}, {"s": "Instagram works because insta-celebs are like you.", "a": "T", "ev": "because they're not megastars but people like you"}, {"s": "Jen Selter became famous as a Hollywood actress.", "a": "F", "ev": "who got noticed after posting multiple shots of the results of her fitness regime"}], "q2": [{"q": "How do companies advertise their products on Instagram?", "m": "Companies encourage the followers of ordinary Instagram users to buy the products that appear in their photos, such as clothes or objects in their homes."}, {"q": "Why are people interested in Jen Selter?", "m": "Because she is an ordinary girl, so her photos make people believe that if they exercise as she does, they can get the same results."}], "q3": {"mode": "find", "opts": ["brand", "fitness", "encourages", "look", "demand", "reaches"], "items": [["motivates", "encourages"], ["ask for", "demand"], ["attains", "reaches"], ["view", "look"]]}, "q4": [{"q": "Selter's photos of her fitness regime make people think that…", "o": ["they can shoot her.", "they can obtain the same results.", "they can upload their own photos.", "they must pay to see her photos."], "a": 1}, {"q": "Instagram stars...", "o": ["work for advertising companies.", "show an honest version of their lives.", "give an unrealistic image of their lives.", "never earn any money."], "a": 2}, {"q": "Insta-celebs attract interest because...", "o": ["they put up photos of their dog.", "they construct lives that people want to imitate.", "they want to become Hollywood celebrities.", "they are paid by the government."], "a": 1}], "q5": {"A": "What are the advantages and disadvantages of being a celebrity?", "B": "Opinion: Do social networks show a false reality?"}}, {"id": "cv2016-jun-a", "official": true, "year": 2016, "conv": "June 2016", "opt": "A", "label": "PAU June 2016 · Text A", "cat": "Technology", "topic": "Screen time", "color": "#7ec9e6", "title": "Why Are British Kids So Unhappy? Two Words: Screen Time", "source": "Bob Granleese, The Guardian, 7-1-2016", "text": ["Peter Wanless has warned of a nation of deeply unhappy children, due to \"the pressure to keep up with friends and have the perfect life online... adding to the sadness that many young people feel every day\". New research by Action For Children (AFC) finds that one in four parents struggles to control their children's screen use, 10% of parents find it hard to get their kids to do homework, and 18% can't get them to go to sleep at night. AFC suggests limiting children's screen time by planning fun activities for the whole family that don't involve technology and creating a balance between technology use and other activities, insisting that, for every hour of screen, children should have to do an hour of something else.", "Sorry, none of that's ever going to work on any teen I know, for that matter; it's too late for that now. No, it's time for some Victorian-style parenting. So last night we sat our son Fred down and laid down the law: from this Sunday, he's to hand in his phone to us by 10.30 pm on school nights -no discussion, no argument, just good old-fashioned \"because I said so\". His response? \"No way. That is so unfair. I've done nothing wrong!\" Sure, you can blame the parents for this whole mess -if we hadn't filled our homes with smartphones and tablets and laptops and desktops, none of this would ever have happened. You can even blame society or the government. Or it could be Tim Berners-Lee's fault for inventing the web."], "q1": [{"s": "Other activities should be more frequent than the use of technology.", "a": "F", "ev": "for every hour of screen, children should have to do an hour of something else"}, {"s": "Fred and his parents reached an agreement on technology use.", "a": "F", "ev": "That is so unfair"}, {"s": "Parents have some responsibility in what has happened.", "a": "T", "ev": "you can blame the parents for this whole mess"}, {"s": "According to the research, a quarter of parents find it hard to control their children's screen use.", "a": "T", "ev": "one in four parents struggles to control their children's screen use"}], "q2": [{"q": "What does AFC suggest to reduce children's hours in front of the screen?", "m": "It suggests planning fun family activities without technology and balancing screen time with other activities: for every hour in front of a screen, an hour of something else."}, {"q": "Who is to blame for this situation that we are facing now about children and technology?", "m": "The author suggests that parents are partly responsible for filling homes with devices, but society, the government or even the inventor of the web could also be blamed."}], "q3": {"mode": "find", "opts": ["keep up with", "involve", "planning", "balance", "work", "fault"], "items": [["equilibrium", "balance"], ["mistake", "fault"], ["maintain", "keep up with"], ["arranging", "planning"]]}, "q4": [{"q": "The pressure to have a perfect life online...", "o": ["is the main reason why British kids are unhappy nowadays.", "is part of why British kids are unhappy nowadays.", "is part of the reason why they use their smartphones all the time.", "has nothing to do with unhappiness."], "a": 1}, {"q": "Asking children to do something else instead of using technology...", "o": ["is a good way to keep the family together at weekends.", "is a good way to stop the use of technology by children.", "is useless because they are too addicted to technology.", "is recommended by Fred."], "a": 2}, {"q": "The author...", "o": ["has a clear picture that only parents are responsible for the current situation.", "has a clear picture of who is to blame for the current situation.", "does not have a clear picture of who is to blame for the current situation.", "blames only Tim Berners-Lee."], "a": 2}], "q5": {"A": "Are you addicted to technology? Discuss.", "B": "For and against: Should parents control their teenagers' phones?"}}, {"id": "cv2016-jun-b", "official": true, "year": 2016, "conv": "June 2016", "opt": "B", "label": "PAU June 2016 · Text B", "cat": "Society", "topic": "Refugees", "color": "#cc7da7", "title": "Migrant Crisis: Norway Will Return Back to Russia Refugees Who Exploited Legal Bicycle Gap", "source": "William Watkison, International Business Times, 15-1-2016", "text": ["Sylvi Listhaug, Norway's immigration minister, has told refugees that exploited a legal gap to enter the country on bikes through an Arctic Circle crossing will have to return to Russia. Around 5,500 asylum seekers used bikes to travel through the Storskog crossing last year and, although Russia does not allow people to cross the border on foot and Norway does not let in motorists carrying people without documents, people on bicycles are allowed in on both sides.", "Listhaug also announced that immigrants without a transit visa would be sent back to Russia. The two nations have been sending refugees back and forth since November 2015 when the new route was identified by authorities. Once they reach Norway, refugees spend time at a centre that provides shelter for around 600 people in barracks on a former military camp bordering the airport of Kirkenes. New arrivals are given fleece jumpers, waterproof jackets and other clothes appropriate for the Arctic climate, with most of them sleeping in bunk beds. On Thursday, Norwegian police confirmed that the refugees would not be forced to return across the border on two wheels, and could instead be taken by bus.", "The number of people taking the Arctic route is tiny compared with the estimated 750,000 who arrived via the Mediterranean in 2015, a perilous journey that has led to the loss of at least 3,400 lives."], "q1": [{"s": "Both Norway and Russia do not allow people to cross without documents.", "a": "F", "ev": "people on bicycles are allowed in on both sides"}, {"s": "Once in Norway, refugees sleep in king-size beds.", "a": "F", "ev": "with most of them sleeping in bunk beds"}, {"s": "The number of people entering Norway is rather small in comparison with those taking the Eastern Mediterranean route.", "a": "T", "ev": "The number of people taking the Arctic route is tiny compared with the estimated 750,000 who arrived via the Mediterranean in 2015"}, {"s": "Refugees will have to cycle back to Russia.", "a": "F", "ev": "the refugees would not be forced to return across the border on two wheels, and could instead be taken by bus"}], "q2": [{"q": "What differences and similarities are there when crossing the border between Russia and Norway?", "m": "Russia does not let people cross on foot and Norway does not let in drivers carrying people without documents, but both countries allow people to cross by bicycle."}, {"q": "What kind of objects are people given when arriving in Norway and why?", "m": "They receive fleece jumpers, waterproof jackets and other warm clothes, because they need protection from the cold Arctic climate."}], "q3": {"mode": "find", "opts": ["seekers", "shelter", "barracks", "former", "bunk", "loss"], "items": [["quarters", "barracks"], ["aspirants", "seekers"], ["preceding", "former"], ["refuge", "shelter"]]}, "q4": [{"q": "Norway's immigration minister declared that immigrants…", "o": ["will no longer need a permit to enter the country.", "will compulsorily need a permit to enter the country.", "will have to choose whether entering without a visa or on a motorbike.", "will be given a bicycle."], "a": 1}, {"q": "Once in Norway, immigrants are sent to a…", "o": ["camp.", "castle.", "condominium.", "hotel."], "a": 0}, {"q": "Immigrants will not be mandatorily sent back to Russia on two wheels but…", "o": ["on foot.", "by public transport.", "in big groups of 600 people.", "by plane."], "a": 1}], "q5": {"A": "What problems do immigrants face when they get to a new country?", "B": "Narrative: Imagine you have to leave your country. Write about your journey."}}, {"id": "cv2016-jul-a", "official": true, "year": 2016, "conv": "July 2016", "opt": "A", "label": "PAU July 2016 · Text A", "cat": "Health", "topic": "Zika", "color": "#ef908a", "title": "Now That Zika Is the World's Latest Infection, Should You Be Worried?", "source": "Dennis Romero, LA Weekly, 4-2-2016", "text": ["Zika's a particularly evil little virus that could cause microcephaly, a rare neurological condition that could cause affected infants to be born with abnormally small heads.", "This week the U.S. Centers for Disease Control announced a recent case of Zika reported in the Dallas area: \"According to a Dallas County Health Department investigation, a person who recently traveled to an area with Zika virus returned to the United States and developed Zika-like symptoms\". The person later tested positive for Zika.", "Experts say the most common form of transmission is via mosquito bites in South America, particularly Brazil, as well as in the Caribbean, Central America, Mexico, Cape Verde and certain Pacific islands. Health officials warned pregnant women to avoid or postpone travel to those areas. Los Angeles County Department of Public Health says pregnant women who have traveled to those regions and who have \"symptoms suggestive of Zika virus infection during or within two weeks of travel should get tested\". \"The most important messages concern people who may be traveling to locations in the world where Zika virus outbreaks are currently occurring, and advising them on measures they need to take to protect their own health and prevent bringing the disease back\", Dr Jeffrey Gunzenhauser said yesterday.", "There has been one case of Zika reported in Los Angeles, and given LA pathways to Latin America, it shouldn't surprise anyone if there are more."], "q1": [{"s": "Pregnant women should not be worried of traveling to places with Zika.", "a": "F", "ev": "Health officials warned pregnant women to avoid or postpone travel to those areas"}, {"s": "After visiting areas with Zika, tests are compulsory in all pregnant women.", "a": "F", "ev": "symptoms suggestive of Zika virus infection during or within two weeks of travel should get tested"}, {"s": "There are no connections between people in California and South America.", "a": "F", "ev": "given LA pathways to Latin America, it shouldn't surprise anyone if there are more"}, {"s": "The person in Dallas had recently travelled to an area with Zika.", "a": "T", "ev": "a person who recently traveled to an area with Zika virus returned to the United States"}], "q2": [{"q": "What do doctors suspect this virus causes and how would you describe the consequence?", "m": "They suspect it can cause microcephaly, a rare neurological condition in which babies are born with abnormally small heads, which is a very serious consequence."}, {"q": "What do authorities advise people to do if they still need to visit areas affected by this virus?", "m": "They advise them to protect their health and avoid bringing the disease back; pregnant women should avoid or postpone the trip and get tested if they have symptoms."}], "q3": {"mode": "find", "opts": ["evil", "pregnant", "suggestive", "outbreaks", "measures", "pathways"], "items": [["eruptions", "outbreaks"], ["actions", "measures"], ["harmful", "evil"], ["expectant", "pregnant"]]}, "q4": [{"q": "The Dallas County Health Department…", "o": ["found a pregnant woman with symptoms.", "found a pregnant woman with symptoms and a person who had not.", "found a person with Zika after being tested.", "found the mosquito that transmitted the virus."], "a": 2}, {"q": "LA County Department of Public Health…", "o": ["stated that symptoms of Zyka in pregnant women usually develop in one or two weeks.", "stated that all pregnant women who have traveled to those areas have developed symptoms.", "stated that all pregnant women with symptoms should be checked.", "stated that Zika cannot affect pregnant women."], "a": 2}, {"q": "The possibilities of finding more people infected in California…", "o": ["are very limited due to LA pathways to Latin America.", "are likely to happen due to their connections with Latin America.", "are likely to happen due to the fact that pathways to Latin America are increasing year after year.", "are zero because there are no mosquitoes in California."], "a": 1}], "q5": {"A": "How can Zika spread across Europe? Discuss.", "B": "Opinion: Should people avoid travelling to countries with health risks?"}}, {"id": "cv2016-jul-b", "official": true, "year": 2016, "conv": "July 2016", "opt": "B", "label": "PAU July 2016 · Text B", "cat": "Society", "topic": "Refugee camps", "color": "#cc7da7", "title": "Life in a Refugee Camp: \"The Cold and Fear Get in Your Bones\"", "source": "Suzanne Moore, The Guardian, 28-11-2015", "text": ["\"I was not born to live here like this\", says Ali. He is from Iran. We are in a refugee camp. But to describe this as a camp is wrong. There are no basic facilities. None. It's a field of mud and tents. I am surrounded by people waiting to see a doctor holding little tickets, looking at each other with suspicion.", "Families are arriving all the time. The average refugee is a young man, but there are more and more women and children. Women sit in tents frying potatoes. They smile and chat, but everyone is cold. Everything is wet. Everyone has a story of how they got here. Some show me on their phones images of them getting out of boats. As they have travelled from Syria or Eritrea, fleeing Islamic State, torture, unimaginable darkness, the phones are their lifelines. They connect them back to where they have come from and to a world they are now locked out of.", "Ali considers getting to England as \"an exam, a challenge. I have failed five times. But I will do it\". Every night, people try different ways to get over the wire or into the trucks. And many of the injuries the doctors treat are the direct result of attempts to reach the UK. But the way these people are forced to live is also making them ill. Respiratory and stomach infections are everywhere, as are rats, mice. The conditions of these \"camps\" don't meet any basic UN humanitarian standards. Everything here is dangerous. Fires start as candles tip over. Trapped, desperate people do desperate things. The cold and fear get inside your bones."], "q1": [{"s": "There are more women and children than men in the camp.", "a": "F", "ev": "The average refugee is a young man"}, {"s": "Ali thinks that he will never manage to get to England.", "a": "F", "ev": "I have failed five times. But I will do it"}, {"s": "People in the camps do not have a minimum quality of life.", "a": "T", "ev": "don't meet any basic UN humanitarian standards"}, {"s": "Many refugees use their phones to stay connected with the places they come from.", "a": "T", "ev": "They connect them back to where they have come from"}], "q2": [{"q": "Why shouldn't this place be called a camp?", "m": "Because there are no basic facilities at all: it is just a muddy field full of tents, with rats, infections and dangerous conditions."}, {"q": "Why are refugees' phones so important?", "m": "Because they keep them connected to their homes and families and to the world they can no longer be part of; they also keep images of their journey."}], "q3": {"mode": "find", "opts": ["holding", "fleeing", "considers", "injuries", "result", "fear"], "items": [["outcome", "result"], ["regards", "considers"], ["fright", "fear"], ["escaping", "fleeing"]]}, "q4": [{"q": "Refugees in the camp...", "o": ["have no idea how they got to the camp.", "have clear memories of how they got to the camp.", "have a story about how they can cross over the wire.", "were born in the camp."], "a": 1}, {"q": "Every night...", "o": ["refugees are injured in the camps and treated by doctors.", "refugees cross over the wire and climb onto a lorry.", "refugees think of possible ways to get to UK.", "refugees sleep in hotels."], "a": 2}, {"q": "The way refugees are living in the camps...", "o": ["is making them ill due to desperation.", "is making their clothes wet and dirty.", "is making their health deteriorate.", "is improving their health."], "a": 2}], "q5": {"A": "What problems do refugees face nowadays?", "B": "Opinion: What should Europe do to help refugees?"}}, {"id": "cv2017-jun-a", "official": true, "year": 2017, "conv": "June 2017", "opt": "A", "label": "PAU June 2017 · Text A", "cat": "Technology", "topic": "Messaging apps", "color": "#7ec9e6", "title": "'Read Receipts' Such as WhatsApp's 'Blue Double Tick' Can Destroy Your Life", "source": "Adapted from an article by Elle Hunt, The Guardian, March 17th 2017", "text": ["Most platforms tell you when your message has been opened. On WhatsApp, the double tick turns blue. It sounds straightforward enough, but when a message lingers on \"seen\" without a reply for anything beyond a few minutes, you think you've been ignored. It's enough to make you feel depressed.", "Was what you said so inappropriate? You thought not, but you were obviously wrong, because why else would they have read it and not replied? It works both ways, too: if you've read a message and you're either unable or unwilling to respond to it immediately, the countdown has already started. The implicit message of your silence is that you're ignoring them -not the best starting point for a conversation.", "The anxiety of not getting a reply is silly but it is real, and unique to this time, the web 2.0, when everyone is assumed to be available at all times. And, if not, it's personal. Combined with notifications for \"last active\" (which tell you how long since someone was on the platform) and \"is typing\" (which tell you when they've started typing their reply), well, is it any wonder that anxiety is so common among the young nowadays? Communication has gone downhill, even though it's ostensibly improved. When we're used to good things happening instantly, time taken to type a reply is considered a bad thing. Personally, I want \"read receipts\" abolished. Ignorance (of the exact moment you read my message and decided not to reply to it) is wonderful."], "q1": [{"s": "Only WhatsApp tells you when a message has been opened.", "a": "F", "ev": "Most platforms tell you when your message has been opened"}, {"s": "The fact that we are supposed to be connected all the time makes this anxiety of \"no reply\" special.", "a": "T", "ev": "unique to this time, the web 2.0, when everyone is assumed to be available at all times"}, {"s": "Today, you are not expected to spend a long time writing a message.", "a": "T", "ev": "time taken to type a reply is considered a bad thing"}, {"s": "The author would like read receipts to disappear.", "a": "T", "ev": "Personally, I want read receipts abolished"}], "q2": [{"q": "Why does the double tick make people feel depressed?", "m": "Because when your message has been read but there is no reply after a few minutes, you think the other person is ignoring you or that you said something wrong."}, {"q": "Why is anxiety so typical among the young nowadays?", "m": "Because everybody is expected to be available all the time, and notifications such as 'last active' or 'is typing' make young people worry even more about replies."}], "q3": {"mode": "find", "opts": ["turns", "lingers", "wonder", "considered", "decided", "receipts"], "items": [["regarded", "considered"], ["remains", "lingers"], ["chose", "decided"], ["becomes", "turns"]]}, "q4": [{"q": "You think you've been ignored...", "o": ["when, after a few minutes, the double tick turns blue and you get no reply.", "when the double tick turns blue and you expect an immediate reply.", "when the double tick turns blue and you get no reply after a few minutes.", "when the double tick stays grey."], "a": 2}, {"q": "If you don't reply to a message immediately...", "o": ["the person who sent the message is right in thinking that you are ignoring him/her.", "the person who sent the message may think that you are ignoring him/her.", "the person who sent the message may also ignore you.", "the person who sent the message will delete it."], "a": 1}, {"q": "Notifications and \"is typing\" messages...", "o": ["contribute to the anxiety of today's youth.", "increase the need to be available in today's youth.", "allow today's youth to be more in control of their interactions.", "have made communication easier."], "a": 0}], "q5": {"A": "How do blue double ticks, notifications and \"is typing\" messages make you feel? Do you think they should be eliminated? Give reasons.", "B": "For and against: Instant messaging apps."}}, {"id": "cv2017-jun-b", "official": true, "year": 2017, "conv": "June 2017", "opt": "B", "label": "PAU June 2017 · Text B", "cat": "Leisure & culture", "topic": "Viral trends", "color": "#f6bb83", "title": "The Victorian Origins of the Mannequin Challenge", "source": "Adapted from an article by Ellen J. Stockstill, The Conversation, December 2016", "text": ["A group of Florida high schoolers made the first Mannequin Challenge video, and they started a movement that went viral, with pop music groups, sports teams and politicians jumping in to make videos of their own.", "Like most internet fads, the Mannequin Challenge's moment will likely be brief. However, in this case, there's some historical precedent. It was called tableau vivant (literally, \"living picture\"). The technique has its roots in medieval drama, but it became a fashionable Victorian-era dinner party game. People would select a famous scene from history or literature or art and position themselves in that scene, frozen, for their guests and friends to observe.", "One fashion writer said \"In the production of tableaux, the greatest attention must be paid to the grouping of figures and the harmony of colours. When they are animated and controlled by a fine taste, their effect is charming.\" The tableau's combination of animation and control, its carefully choreographed suspension of movement, illustrates the appeal of the Mannequin Challenge. Queen Victoria loved this entertainment. In an 1852 pencil sketch, she drew her six children in a tableau of John Milton's \"L'Allegro\" that they performed for her husband's 33rd birthday. \"Albert was delighted and could not imagine how it had been so well arranged,\" she wrote in her journal.", "Part of the joy in producing a tableau vivant was watching the audience's recognition and reaction. I believe that if Queen Victoria had owned an iPhone, she would have filmed the moment and shared it on Instagram for the world to see."], "q1": [{"s": "It is probable that the Mannequin Challenge will not last long.", "a": "T", "ev": "Like most internet fads, the Mannequin Challenge's moment will likely be brief"}, {"s": "A tableau vivant was a popular medieval game.", "a": "F", "ev": "The technique has its roots in medieval drama, but it became a fashionable Victorian-era dinner party game"}, {"s": "In the production of a tableau, colour was the only important feature.", "a": "F", "ev": "the greatest attention must be paid to the grouping of figures and the harmony of colours"}, {"s": "Queen Victoria disliked tableaux vivants.", "a": "F", "ev": "Queen Victoria loved this entertainment"}], "q2": [{"q": "What scenes did people imitate in a tableau vivant?", "m": "They chose a famous scene from history, literature or art and posed in it without moving, so that their guests could watch them."}, {"q": "What makes a tableau vivant and a mannequin challenge video similar?", "m": "In both, people stay frozen in a carefully arranged scene that combines movement and control, and part of the fun is the audience's reaction."}], "q3": {"mode": "find", "opts": ["fads", "roots", "frozen", "guests", "taste", "joy"], "items": [["motionless", "frozen"], ["delight", "joy"], ["origins", "roots"], ["trends", "fads"]]}, "q4": [{"q": "A group of Florida high schoolers…", "o": ["made a video with pop music groups.", "started a viral movement.", "jumped in their own videos.", "invented the tableau vivant."], "a": 1}, {"q": "A tableau vivant…", "o": ["is a popular Victorian game.", "is a popular Victorian party.", "is a famous Victorian sport.", "is a modern type of video."], "a": 0}, {"q": "Queen Victoria's children…", "o": ["drew L'Allegro.", "drew a pencil sketch of L'Allegro for her husband's birthday.", "performed a tableau of L'Allegro.", "sang L'Allegro at the party."], "a": 2}], "q5": {"A": "In your opinion, why are viral videos such as the Mannequin Challenge so popular?", "B": "Narrative: Write about a viral video you took part in or watched (real or imaginary)."}}, {"id": "cv2017-jul-a", "official": true, "year": 2017, "conv": "July 2017", "opt": "A", "label": "PAU July 2017 · Text A", "cat": "Society", "topic": "Brexit", "color": "#cc7da7", "title": "Young, British and Living in Europe. Brexit Has Turned Our Lives Upside Down", "source": "Adapted from an article by Rosamund Mather, The Guardian, November 2nd 2016", "text": ["After Brexit, what will it be like for British millennials, most of which voted to remain in EU, and live abroad? People aged 18 to 34 are looking beyond their homeland's borders for a future career, almost twice as much as the preceding generation. Cities such as Berlin have gained a reputation for their lively atmosphere and low cost of living (appealing prospects in comparison to UK cities, where millennials are hit hardest by the recession). Start-up companies are inherently international because of their need for funding and talent regardless of its origin -so knowledge of the local language is generally not required. It's extremely common for business to be conducted in English.", "Since the Brexit referendum, there has been a level of uncertainty, and a state of anxiety. And the young are likely to be disproportionately affected, as their world is turned upside down right at the start of their careers. They feel helpless about the escalating incidences of xenophobia and homophobia back home. We were told that our twenties are for exploration and learning -and most pertinently, for not yet having to make serious, long-term commitments. Yet this is exactly what Brexit is forcing on young Britons prematurely. For British people living in Spain, for instance, Brexit is a cloud over the sun.", "It is not just a practical difficulty, but an emotional one. Those who had planned for only a temporary residence in a foreign country are now considering EU citizenship. However, in certain member states, such as Austria, dual citizenship is either highly restricted or forbidden -causing the applicant some complicated distress."], "q1": [{"s": "Start-up companies do not consider important where the person comes from.", "a": "T", "ev": "Start-up companies are inherently international because of their need for funding and talent regardless of its origin"}, {"s": "Only young people have been affected by Brexit referendum.", "a": "F", "ev": "the young are likely to be disproportionately affected"}, {"s": "Britons living abroad want to get EU citizenship, but only temporarily.", "a": "F", "ev": "Those who had planned for only a temporary residence in a foreign country are now considering EU citizenship"}, {"s": "Business in start-ups is often done in English.", "a": "T", "ev": "It's extremely common for business to be conducted in English"}], "q2": [{"q": "Why do British millennials think of Europe for a future career?", "m": "Because cities such as Berlin offer a lively atmosphere and a low cost of living, while in the UK young people have been hit hardest by the recession."}, {"q": "Why is the world of millennials turned upside down?", "m": "Because Brexit has created uncertainty and anxiety right at the beginning of their careers and forces them to make serious long-term decisions too early."}], "q3": {"mode": "find", "opts": ["remain", "preceding", "gained", "appealing", "required", "common"], "items": [["attractive", "appealing"], ["acquired", "gained"], ["necessary", "required"], ["previous", "preceding"]]}, "q4": [{"q": "Millennials are highly affected because...", "o": ["the referendum has forced them to stay in Britain.", "the referendum has altered their careers in Europe.", "the referendum has made living in Berlin impossible.", "the referendum has lowered the cost of living in the UK."], "a": 1}, {"q": "Brexit is forcing Britons...", "o": ["to make plans in the long term.", "to learn more about exploration.", "to make plans about living in Spain.", "to stop travelling."], "a": 0}, {"q": "Some people are thinking about the possibility of becoming EU citizens...", "o": ["even though they only wanted to be in a different country for a while.", "even though this means not returning to UK.", "even though they do not want to stop speaking English.", "even though it is free in all EU countries."], "a": 0}], "q5": {"A": "What are the advantages and disadvantages of living abroad after you finish your studies?", "B": "Opinion: Would you like to work in another European country?"}}, {"id": "cv2017-jul-b", "official": true, "year": 2017, "conv": "July 2017", "opt": "B", "label": "PAU July 2017 · Text B", "cat": "Society", "topic": "Charity", "color": "#cc7da7", "title": "Jon Bon Jovi Empowers Those in Need", "source": "Adapted from an article by Ashley N. Vaughan, CNN Entertainment, February 10th 2017", "text": ["Behind the music, Grammy award-winning entertainer Jon Bon Jovi is on a mission to feed and empower those in need. His strategy is simple: \"One soul at a time.\"", "With his non-profit Jon Bon Jovi Soul Foundation, based in Philadelphia, the artist is fighting poverty with direct action. According to the nonprofit's website, the Jon Bon Jovi Soul Foundation has helped provide more than 500 affordable homes to those in need across 10 states. Bon Jovi also founded the JBJ Soul Kitchen, a community restaurant that serves everyone regardless of their ability to pay. At a glance, it looks like a trendy New Jersey restaurant. There are linen napkins, fresh flowers at each place setting and a farm-to-table menu. But each meal offers one essential ingredient: hope.", "\"The key to our success is empowering the individual,\" Bon Jovi says. \"We have created what we now call a pay it forward model.\" In-need customers volunteer their time assisting with day-to-day restaurant tasks, which pays for their own meal as well as the bill for their family. Also, paying customers are requested to buy a pay it forward card. You do not only pay for your meal, but also the one next to you, Bon Jovi says. For restaurant volunteer Moe Keane, it is this principle that makes the JBJ Soul Kitchen one of her preferred ways to give back. \"You don't know if someone is dining here because they are in need, that's what's nice about it. Everyone is treated the same.\""], "q1": [{"s": "JBJ Soul Kitchen used to be a trendy restaurant in New Jersey.", "a": "F", "ev": "At a glance, it looks like a trendy New Jersey restaurant"}, {"s": "People in need can pay for their food by working in the restaurant.", "a": "T", "ev": "In-need customers volunteer their time assisting with day-to-day restaurant tasks, which pays for their own meal"}, {"s": "Those in need and those who can pay for their food do not coincide in the restaurant.", "a": "F", "ev": "You don't know if someone is dining here because they are in need"}, {"s": "The foundation has helped provide more than 500 affordable homes.", "a": "T", "ev": "has helped provide more than 500 affordable homes to those in need across 10 states"}], "q2": [{"q": "What has the Jon Bon Jovi Soul Foundation done?", "m": "It fights poverty directly: it has helped provide more than 500 affordable homes in 10 states and has opened a community restaurant where everyone can eat."}, {"q": "What does the pay it forward model involve?", "m": "People in need pay for their meal by helping in the restaurant, and paying customers can buy a card to pay for someone else's meal as well as their own."}], "q3": {"mode": "find", "opts": ["feed", "trendy", "empowering", "assisting", "requested", "treated"], "items": [["fashionable", "trendy"], ["commissioning", "requested"], ["provide meals", "feed"], ["considered", "treated"]]}, "q4": [{"q": "Jon Bon Jovi's mission is…", "o": ["to help people in need by feeding them.", "to give power to people.", "to play rock music to people in need.", "to open restaurants all over the world."], "a": 0}, {"q": "All place settings in the restaurant…", "o": ["are decorated with farm menus.", "are decorated with fresh daffodils.", "are decorated in a similar way.", "are decorated with photos of the singer."], "a": 2}, {"q": "In the restaurant…", "o": ["there is an area for those in need and an area for those who pay for their food.", "you cannot see any difference between those in need and those helping others.", "it is nice to see people in need paying for their own food.", "only famous people can eat."], "a": 1}], "q5": {"A": "If you were rich and famous, what would you do to help others?", "B": "Opinion: Should famous people use their money to help others?"}}, {"id": "cv2018-jun-a", "official": true, "year": 2018, "conv": "June 2018", "opt": "A", "label": "PAU June 2018 · Text A", "cat": "Health", "topic": "Touch", "color": "#ef908a", "title": "No Hugging: Are We Living Through a Crisis of Touch?", "source": "Excerpt from an article by Paula Cocozza, The Guardian, March 7th 2018", "text": ["When did you last touch someone outside your family or intimate relationship? Touch is the first sense humans develop. But somewhere in adulthood what was instinctive to us as children has come to feel awkward. In countless ways social touch is being eliminated from our lives.", "In the UK, doctors were warned last month to avoid comforting patients with hugs to avoid legal action. Teachers hesitate to touch pupils. And in the UK, in a loneliness epidemic, half a million older people go at least five days a week without touching a person.", "What do humans risk losing, when we lose touch? Francis McGlone, a leader in affective touch, is worried: \"We have demonised touch to a level at which it provokes hysterical responses, and this lack of touch is not good for mental health\", he says.", "McGlone says: \"The pleasantness of touch encourages us to keep touching, pleasing babies and connecting adults. Last year, researchers from London showed that slow, gentle stroking by a stranger reduced feelings of social exclusion. As a society, we instinctively understand the power of touch. Caressing slows down heart beats and blood pressure, gives people better control over their stress hormones. Being touched also increases the number of natural killer cells\".", "\"You just don't see people touching each other these days,\" Tiffany Field, founder of the Touch Research Institute, complains. There is still no scientific data to connect declining touch to mobile technology or social media, but Field's descriptions of people wrapped in their own worlds rather than each other, sitting in isolation, are evocative and familiar."], "q1": [{"s": "We start touching people as soon as we become adults.", "a": "F", "ev": "Touch is the first sense humans develop"}, {"s": "People who are touched feel less isolated.", "a": "T", "ev": "slow, gentle stroking by a stranger reduced feelings of social exclusion"}, {"s": "Humans intuitively feel the benefits of touching.", "a": "T", "ev": "As a society, we instinctively understand the power of touch"}, {"s": "Scientists have proved that social media cause the decline of touch.", "a": "F", "ev": "There is still no scientific data to connect declining touch to mobile technology or social media"}], "q2": [{"q": "Why is McGlone worried about humans losing touch?", "m": "Because touch has been demonised and is disappearing from our lives, and this is bad for mental health: touch reduces stress and heart rate and strengthens the immune system."}, {"q": "Why may mobile technology be related to less touching among people?", "m": "Because people seem absorbed in their own worlds and sit in isolation looking at their screens instead of interacting, although there is no scientific proof yet."}], "q3": {"mode": "find", "opts": ["awkward", "eliminated", "hesitate", "provokes", "gives", "connect"], "items": [["provides", "gives"], ["strange", "awkward"], ["link", "connect"], ["triggers", "provokes"]]}, "q4": [{"q": "In the UK loneliness epidemic...", "o": ["older people only touch other people at weekends.", "older people do not touch other people five days a week or more.", "older people do not touch other old people at least five days a week.", "never feel lonely."], "a": 1}, {"q": "The feelings associated with touch...", "o": ["are negative and generate negative reactions.", "are positive and can lead to long-term relationships.", "are positive and can lead to more touching.", "have no effect on health."], "a": 2}, {"q": "A gentle stroking by a stranger...", "o": ["can lead to a strong relationship with that person.", "can make you feel like you are not so isolated.", "can make you be willing to caress that stranger as well.", "is always dangerous."], "a": 1}], "q5": {"A": "Why do we touch each other less nowadays?", "B": "Opinion: Have mobile phones made us lonelier?"}}, {"id": "cv2018-jun-b", "official": true, "year": 2018, "conv": "June 2018", "opt": "B", "label": "PAU June 2018 · Text B", "cat": "Technology", "topic": "Robots", "color": "#7ec9e6", "title": "Shop Hires Robot Assistant... Then Fires It After Just a Week", "source": "Adapted from an article by Fiona Parker, The Daily Mail, January 2nd 2018", "text": ["Fabio was the first robotic retail assistant employed at upmarket store Margiotta (Edinburgh), but was let go after one week.", "At first it got off to a good start, charming customers with hugs and greetings of \"hello gorgeous\". But it wasn't long before Fabio began irritating and confusing shoppers at the store. When one asked which aisle the beer could be found, Fabio gave a vague answer: \"It's in the alcohol section\". And despite its efforts, the background noise in the busy supermarket made it difficult for the robot to understand customers.", "Aware that the first day at a new job can be stressful, its understanding bosses moved Fabio from the aisles to a sampling role. But the robot became too enthusiastic when asked to hand out portions of pulled pork. \"We thought a robot could show the customers that we are always wanting to do something new and exciting\", said Elena Margiotta, who runs the chain of shops. But it wasn't long before Fabio was noticeably outperformed by its human colleagues. While it managed to persuade two people to try a pork snack, its colleagues scored a total of twelve. People seemed to actually avoid it.", "Sadly Elena was left with no other choice than to let it go. And when she told Fabio that she would not renew its contract, the robot asked: \"Are you angry?\" It was an emotional moment for the staff and some were reduced to tears when Fabio was packed away. In its short time at the store, Fabio had clearly become a well-liked member of the team."], "q1": [{"s": "At the beginning Fabio did well in its job.", "a": "T", "ev": "At first it got off to a good start"}, {"s": "Fabio could understand the customers despite the noise in the supermarket.", "a": "F", "ev": "the background noise in the busy supermarket made it difficult for the robot to understand customers"}, {"s": "The staff was sad when Fabio was fired.", "a": "T", "ev": "some were reduced to tears when Fabio was packed away"}, {"s": "Fabio persuaded more customers to try the pork than its human colleagues.", "a": "F", "ev": "While it managed to persuade two people to try a pork snack, its colleagues scored a total of twelve"}], "q2": [{"q": "What went wrong soon after Fabio started working in the aisles of the store?", "m": "It started to annoy and confuse shoppers: it gave vague answers, such as saying the beer was in the alcohol section, and it could not understand customers because of the noise."}, {"q": "Why did Ms Margiotta hire the robot?", "m": "She wanted to show customers that her shops are always trying to do new and exciting things."}], "q3": {"mode": "find", "opts": ["despite", "aware", "stressful", "understanding", "noticeably", "actually"], "items": [["in fact", "actually"], ["conscious", "aware"], ["full of tension", "stressful"], ["sympathetic", "understanding"]]}, "q4": [{"q": "At the sampling section...", "o": ["Fabio performed its task as expected.", "Fabio performed its task better than expected.", "Fabio performed its task worse than the other employees.", "Fabio sold all the beer."], "a": 2}, {"q": "When Fabio was fired, …", "o": ["it was sad.", "the staff was sad.", "Elena was angry.", "the customers celebrated."], "a": 1}, {"q": "The staff...", "o": ["had become attached to Fabio.", "felt Fabio was competing for their job.", "were packed away.", "asked for a robot of their own."], "a": 0}], "q5": {"A": "Do you think that robots will perform human roles better than us in the future?", "B": "Narrative: Write about your first day at a new job or school."}}, {"id": "cv2018-jul-a", "official": true, "year": 2018, "conv": "July 2018", "opt": "A", "label": "PAU July 2018 · Text A", "cat": "Health", "topic": "Life expectancy", "color": "#ef908a", "title": "Women Really Are the Stronger Sex", "source": "Excerpt from an article by Tomasz Frymorgen, BBC.co.uk, January 10th 2018", "text": ["A recent academic study has shown that under extreme conditions such as famines, epidemics and enslavement, women are able to survive for longer than men. Across modern populations, women outlive men in almost all instances, with life expectancy for English women being 83.1 years, compared to 79.5 years for men.", "Now, academics from the Southern University of Denmark have looked at data from seven historic cases when populations were exposed to extreme hardship, in order to gain new insights into the gender mortality gap. Case studies included the Irish famine of 1845-1849, the Iceland measles epidemics of 1846 and 1882, and the experiences of freed Liberian slaves returning to Africa from the US in the early 19th century. During the 1882 Iceland measles epidemic, for example, life expectancy dropped from 43.99 to 18.83 years for females and from 37.62 to just 16.76 years for males. The researchers found that women had lower mortality across almost all ages, and women lived longer on average than men. Based on these findings, the academics concluded, \"the hypothesis that the survival advantage of women has fundamental biological underpinnings is supported by the fact that under very harsh conditions females survive better than males even at infant ages when behavioral and social differences may be minimal or favor males\". The academics referred to research that suggests hormonal differences might explain the gender mortality gap. For example, estrogens, found in larger quantities in women, have anti-inflammatory effects, whereas testosterone, found in larger amounts in men, may actually suppress the immune system."], "q1": [{"s": "Women outlive men only under extreme conditions.", "a": "F", "ev": "Across modern populations, women outlive men in almost all instances"}, {"s": "Women have always lived longer than men except during the 1882 Iceland measles epidemic.", "a": "F", "ev": "life expectancy dropped from 43.99 to 18.83 years for females and from 37.62 to just 16.76 years for males"}, {"s": "Hormones do not explain differences in life expectancy.", "a": "F", "ev": "research that suggests hormonal differences might explain the gender mortality gap"}, {"s": "English women live longer than English men.", "a": "T", "ev": "life expectancy for English women being 83.1 years, compared to 79.5 years for men"}], "q2": [{"q": "Under what severe circumstances do females live longer than males?", "m": "They live longer in very difficult situations such as famines, epidemics and slavery."}, {"q": "Why do women live, biologically, longer than men?", "m": "Because of hormonal differences: women have more estrogens, which reduce inflammation, while men have more testosterone, which may weaken the immune system."}], "q3": {"mode": "find", "opts": ["outlive", "hardship", "measles", "survival", "underpinnings", "harsh"], "items": [["severe", "harsh"], ["difficulty", "hardship"], ["foundations", "underpinnings"], ["survive", "outlive"]]}, "q4": [{"q": "Danish researchers have found relevant data about life expectancy using...", "o": ["data from Southern Denmark.", "19th century data.", "large amounts of hormones at infant ages.", "data from modern hospitals only."], "a": 1}, {"q": "Research from 1845 until 1882 took into account…", "o": ["three different samples.", "four different samples.", "five different samples.", "seven different samples."], "a": 0}, {"q": "Males do not live longer than females…", "o": ["but they did in the past.", "but they outlived females in Iceland.", "even if social conditions are better for males rather than for females.", "because they have more testosterone."], "a": 2}], "q5": {"A": "What would you do to live longer?", "B": "For and against: Would you like to live to be 120 years old?"}}, {"id": "cv2018-jul-b", "official": true, "year": 2018, "conv": "July 2018", "opt": "B", "label": "PAU July 2018 · Text B", "cat": "Environment", "topic": "Microplastics", "color": "#7eb991", "title": "Major Brands of Bottled Water Contain Tiny Particles of Plastic", "source": "Adapted from an article by David Shukman, BBC News Science, March 15th 2018", "text": ["In the largest investigation of its kind, 250 bottles bought in nine different countries were examined. Research led by journalism organisation Orb Media discovered an average of 10 plastic particles per litre, each larger than the width of a human hair.", "Companies whose brands were tested told the BBC that their bottling plants were operated to the highest standards. The tests were conducted at the State University of New York in Fredonia. Sherri Mason, a professor of chemistry at the university, conducted the analysis and told BBC News: \"We found plastic in bottle after bottle and brand after brand. It's not about pointing fingers at particular brands; it's really showing that this is everywhere, that plastic has become such a pervasive material in our society, and it's pervading water -all of these products that we consume at a very basic level\".", "Currently, there is no evidence that ingesting very small pieces of plastic can cause harm, but understanding the potential implications is an active area of science. Commenting on the results, Prof Mason said: \"It's not catastrophic, the numbers that we're seeing, but it is concerning\".", "Experts have told the BBC that people in developing countries where tap water may be polluted should continue to drink water from plastic bottles. Furthermore, the companies behind the brands have insisted that their products meet the highest standards for safety and quality. They also point to the absence of any regulations on microplastics and of the lack of standardised methods of testing for them."], "q1": [{"s": "Researchers examined bottles of water from an average of 10 countries.", "a": "F", "ev": "250 bottles bought in nine different countries were examined"}, {"s": "The presence of plastic particles in bottles is rare.", "a": "F", "ev": "We found plastic in bottle after bottle and brand after brand"}, {"s": "People in developing countries should only drink tap water.", "a": "F", "ev": "people in developing countries where tap water may be polluted should continue to drink water from plastic bottles"}, {"s": "Professor Mason thinks the results are worrying but not catastrophic.", "a": "T", "ev": "It's not catastrophic, the numbers that we're seeing, but it is concerning"}], "q2": [{"q": "What did companies say when the BBC told them about the findings from this study?", "m": "They said that their bottling plants work according to the highest standards and that their products meet the highest standards of safety and quality."}, {"q": "Have researchers shown that these plastic particles are bad for people's health?", "m": "No. There is still no evidence that swallowing very small pieces of plastic is harmful, although scientists are investigating the possible effects."}], "q3": {"mode": "find", "opts": ["investigation", "pervasive", "concerning", "meet", "point", "testing"], "items": [["worrying", "concerning"], ["research", "investigation"], ["fulfill", "meet"], ["omnipresent", "pervasive"]]}, "q4": [{"q": "Research led by Orb Media found out that microplastics in bottles of water were…", "o": ["wider than a human hair.", "as wide as a human hair.", "also contained human hair.", "made of glass."], "a": 0}, {"q": "The analysis of water bottles was conducted by…", "o": ["a university professor working for BBC News.", "a professor from a university in the state of New York.", "a university professor of chemistry working for the BBC.", "the companies themselves."], "a": 1}, {"q": "Water companies highlight…", "o": ["the lack of standards in the plastic industry.", "the lack of clear regulations on the presence of particles of plastic.", "the lack of standardised tests for plastic industries.", "the high price of glass bottles."], "a": 1}], "q5": {"A": "Plastic is polluting our world. What can we do to stop it?", "B": "For and against: Should plastic bottles be banned?"}}, {"id": "cv2019-jun-a", "official": true, "year": 2019, "conv": "June 2019", "opt": "A", "label": "PAU June 2019 · Text A", "cat": "Science", "topic": "Space junk", "color": "#8c92cb", "title": "Garbage Collection in Space", "source": "Adapted from an article by Katyanna Quach, The Register, 19-09-2018", "text": ["Space junk circling our planet is a growing problem as more spacecrafts are sent up into orbit, increasing the dangers of a collision. Some of the debris is natural, such as small portions of meteoroid, and some of it is artificial, such as the pieces of material leftover from old probes and rockets. It is estimated that there are more than 20,000 pieces of artificial debris each larger than a baseball floating around Earth, all traveling at tremendous speeds.", "They travel up to 17,500 miles per hour, in fact, fast enough that a small nugget could wreck sensitive structures. Luckily, there haven't been many catastrophic crashes with cosmic garbage, but a few windows on space shuttles have had to be replaced due to damage caused by debris as small as bits of paint. The European Commission has funded a number of projects promising to clean up space junk. The RemoveDEBRIS apparatus developed by researchers from Airbus and the University of Surrey in England is just one of them.", "RemoveDEBRIS successfully caught a lump of space trash - specifically, a no longer needed small human made satellite - using a net. This mechanism is hoped to form the basis of future nets that will sweep up space litter around Earth, clearing the way for safer launches.", "The next phase is to catch another human made satellite, but this time using cameras and LiDAR technology to target objects with better precision, and a special harpoon to capture them. A drag-sail will also bring the debris back into Earth's atmosphere to be destroyed."], "q1": [{"s": "Only the largest pieces of debris can cause damage.", "a": "F", "ev": "debris as small as bits of paint"}, {"s": "Space debris has never crashed with space shuttles.", "a": "F", "ev": "a few windows on space shuttles have had to be replaced due to damage caused by debris"}, {"s": "RemoveDEBRIS is the result of research carried out by two partners.", "a": "T", "ev": "developed by researchers from Airbus and the University of Surrey"}, {"s": "Space debris moves very slowly.", "a": "F", "ev": "They travel up to 17,500 miles per hour"}], "q2": [{"q": "Why is space garbage steadily increasing?", "m": "Because more and more spacecraft are sent into orbit, and old rockets and probes leave pieces of material that keep circling the Earth."}, {"q": "What was RemoveDEBRIS able to do?", "m": "It managed to catch a piece of space junk, an old small satellite that was no longer needed, using a net."}], "q3": {"mode": "find", "opts": ["dangers", "debris", "wreck", "sensitive", "sweep", "launches"], "items": [["risks", "dangers"], ["delicate", "sensitive"], ["clean", "sweep"], ["damage", "wreck"]]}, "q4": [{"q": "Meteoroids...", "o": ["leave natural debris.", "leave artificial debris.", "are usually larger than baseballs.", "never reach the Earth's orbit."], "a": 0}, {"q": "Debris runs so fast that very small pieces...", "o": ["cannot cause damage.", "can cause damage.", "are sensitive structures.", "always burn in the atmosphere."], "a": 1}, {"q": "RemoveDEBRIS...", "o": ["was based on a human made satellite.", "was based on net technology.", "used a net and a harpoon to capture space trash.", "has already been used to destroy meteoroids."], "a": 1}], "q5": {"A": "What can we do to reduce electronic waste?", "B": "Opinion: Is space exploration worth the money?"}}, {"id": "cv2019-jun-b", "official": true, "year": 2019, "conv": "June 2019", "opt": "B", "label": "PAU June 2019 · Text B", "cat": "Health", "topic": "Sleep", "color": "#ef908a", "title": "Hard Day's Night: Causes of Sleep Deprivation", "source": "Adapted from an article by Henry Nicholls, The Guardian, 10-02-2019", "text": ["Sleep deprivation can be torture, quite literally. After a week of being kept awake, a 19th-century Chinese merchant who had been sentenced to death by sleep deprivation was begging for \"the opportunity of being strangled, guillotined, burned to death or drowned.\" If you want to know what it's like to suffer the horrors of sleep deprivation, try reducing the number of hours you sleep. But there is another way, much harder to detect and more common than we realise: sleep deprivation is not just about quantity, it is about quality, too. There is no better illustration of the importance of sleep quality than narcolepsy, a sleep disorder I have lived with for half my life. When I was diagnosed in the 1990s, if I explained to someone I had narcolepsy I was met by an astonished stare. Nowadays, most people know it is a disabling neurological condition in which sleep strikes with little or no warning repeatedly through the day. The sleep of narcolepsy is not healthy, restorative sleep, but is seriously disturbed, shot through by hallucination-like dreams. Just as sleep repeatedly interferes with my ability to stay awake during the day, wakefulness very often intrudes on my sleep at night. Narcolepsy is about being simultaneously overslept and sleep-deprived. A recent study showed that one of the strongest predictors of how rested you feel in the morning is sleep continuity. Anyone who's had children can testify to the psychological suffering that results from fractured sleep. It is pretty clear that the brain would rather not be disturbed."], "q1": [{"s": "The Chinese merchant preferred fire to sleep deprivation.", "a": "T", "ev": "the opportunity of being strangled, guillotined, burned to death or drowned"}, {"s": "In the 1990s, people understood what narcolepsy was about.", "a": "F", "ev": "if I explained to someone I had narcolepsy I was met by an astonished stare"}, {"s": "You feel full of energy if you have non-stop sleep through the night.", "a": "T", "ev": "one of the strongest predictors of how rested you feel in the morning is sleep continuity"}, {"s": "The author has only recently been diagnosed with narcolepsy.", "a": "F", "ev": "When I was diagnosed in the 1990s"}], "q2": [{"q": "What does the author mean by sleep quantity and quality?", "m": "Quantity is the number of hours we sleep, while quality is how good and continuous that sleep is; poor-quality sleep can also leave us sleep-deprived."}, {"q": "When can you say that you are rested in the morning?", "m": "When you have slept continuously, without interruptions during the night."}], "q3": {"mode": "find", "opts": ["begging", "illustration", "stare", "disabling", "wakefulness", "rested"], "items": [["fixed look", "stare"], ["refreshed", "rested"], ["example", "illustration"], ["incapacitating", "disabling"]]}, "q4": [{"q": "In order to check how lack of sleep affects people…", "o": ["we need to know more about dreams.", "both quantity and quality of sleep have to be measured.", "we should ask parents.", "we should only count the hours."], "a": 1}, {"q": "Narcolepsy…", "o": ["takes place during the day.", "allows you to have good sleep.", "was a well-known disorder 3 decades ago.", "only affects children."], "a": 0}, {"q": "The sleep of narcoleptics…", "o": ["is good because they can also sleep in daytime.", "is not reparative sleep.", "doesn't allow them to dream.", "is always very relaxing."], "a": 1}], "q5": {"A": "Do you get enough sleep every day?", "B": "Opinion: Should young people use their phones before going to sleep?"}}, {"id": "cv2019-jul-a", "official": true, "year": 2019, "conv": "July 2019", "opt": "A", "label": "PAU July 2019 · Text A", "cat": "Work", "topic": "Domestic workers", "color": "#c3a48e", "title": "She Worked in Homes for Decades, Like the Main Character in the Film 'Roma'", "source": "Adapted from an article by Kate Linthicum, Los Angeles Times, 21-02-2019", "text": ["Marcelina Bautista wept the first time she watched 'Roma', the Oscar-winning drama about a domestic worker's complicated relationship with the family that employs her. Like Cleo, the film's protagonist, Bautista had spent years living in other people's homes, cooking their meals, cleaning up their messes and caring for their kids. Like Cleo, she often felt isolated and had at times suffered discrimination and abuse.", "But unlike Cleo, Bautista fought back. Three decades ago, she began quietly organizing workers and created Mexico's first-ever trade union for domestic workers. The union's demands were simple, that the 2.4 million Mexicans who work in private homes be treated as formal employees, protected from abuse and given contracts that ensure fair wages, limited working hours and paid vacations.", "The movement has won major gains and last December, Mexico's Supreme Court ruled that domestic workers have a right to receive social security benefits. Then, the film's writer and director, Alfonso Cuaron, asked Bautista to introduce the movie at its premiere, and this month both explained another Supreme Court decision, which eventually will require people who employ domestic workers to pay into the country's social security system. They said conditions for domestic workers today are similar to those portrayed in the film, which is set in the 1970s, and that the jobs are typically so low-paid that even middle-class families can afford hired help. Cuaron, whose film is based loosely on his own childhood, has given the union the rights to use the movie to help its cause."], "q1": [{"s": "Bautista used to work in an old people's home.", "a": "F", "ev": "had spent years living in other people's homes, cooking their meals, cleaning up their messes and caring for their kids"}, {"s": "The conditions of domestic workers in the 70s were similar to those of today.", "a": "T", "ev": "conditions for domestic workers today are similar to those portrayed in the film, which is set in the 1970s"}, {"s": "The film is inspired by the director´s younger years.", "a": "T", "ev": "Cuaron, whose film is based loosely on his own childhood"}, {"s": "Mexico's Supreme Court has denied social security benefits to domestic workers.", "a": "F", "ev": "Mexico's Supreme Court ruled that domestic workers have a right to receive social security benefits"}], "q2": [{"q": "What is the main difference between Bautista and Cleo after comparing their lives?", "m": "Both worked as domestic workers and suffered isolation and abuse, but unlike Cleo, Bautista fought back and organised other workers."}, {"q": "What are the main achievements of Bautista´s movement?", "m": "Her union has fought for contracts, fair salaries and limited working hours, and the Supreme Court has recognised domestic workers' right to social security."}], "q3": {"mode": "find", "opts": ["messes", "isolated", "wages", "premiere", "portrayed", "hired"], "items": [["described", "portrayed"], ["first showing", "premiere"], ["earnings", "wages"], ["contracted", "hired"]]}, "q4": [{"q": "Marcelina Bautista was…", "o": ["Roma´s main actress.", "a worker in a nursing home.", "a domestic employee.", "the director of Roma."], "a": 2}, {"q": "The first Mexican trade union for domestic workers was founded…", "o": ["30 years ago.", "by Cleo under Bautista´s supervision.", "to have major gains.", "by the Supreme Court."], "a": 0}, {"q": "The conditions of workers in today's real world and those of the film…", "o": ["have no possible comparison.", "are comparable.", "are quite similar because families have never been able to afford their help.", "are better today than in the 1970s."], "a": 1}], "q5": {"A": "Do you think it's easy to find a job today? Give reasons.", "B": "Narrative: Write about a film that made you think about a social problem."}}, {"id": "cv2019-jul-b", "official": true, "year": 2019, "conv": "July 2019", "opt": "B", "label": "PAU July 2019 · Text B", "cat": "Technology", "topic": "Facebook", "color": "#7ec9e6", "title": "Facebook Threatens the Economy, Health and Democracy", "source": "Adapted from an article by Ganesh Sitaraman, The Guardian, 24-02-2019", "text": ["Facebook recently reminded me that I've been on the social network for 15 years. I normally pay little attention to those anniversary notices, but this time I paused to think about how much had changed since Facebook was founded. Excitement about its promise, gratitude for the ease of staying in touch with old friends, frustration at its approach to privacy, apprehension over its addictiveness.", "Around the same time as I got that notification, I was reading Roger McNamee's well-written new book, Zucked: Waking up to the Facebook Catastrophe. His central argument is that Facebook is a threat to the economy, public health, and democracy. The economic critique rests on the problems of monopoly capitalism, for example Facebook's ability to buy up rivals like Instagram and WhatsApp. The public health critique focuses on tactics to get people to use Facebook more, even to the point of addiction. The democracy critique is that democracy cannot survive without debate on shared truths. But we increasingly are denied access to different opinions.", "Today, even tech companies have acknowledged that their industry requires regulation. The question for them is what those regulations should look like. Transparency and other changes will not be a sufficient response to the scope of the challenge. The question is whether reformers, regulators, and citizens will have the courage to fight for broader, deeper changes. Because at the end of the day, what's at stake is far more important than a few Likes. It is the future of our economy, our society, and our democracy."], "q1": [{"s": "Getting people to use Facebook more is only a problem if users get addicted.", "a": "F", "ev": "tactics to get people to use Facebook more, even to the point of addiction"}, {"s": "Users engage in fewer political debates if they use Facebook consistently.", "a": "T", "ev": "we increasingly are denied access to different opinions"}, {"s": "Facebook does not need important and substantial changes.", "a": "F", "ev": "Transparency and other changes will not be a sufficient response to the scope of the challenge"}, {"s": "The author has been a Facebook user for fifteen years.", "a": "T", "ev": "I've been on the social network for 15 years"}], "q2": [{"q": "Why is Facebook a threat?", "m": "According to McNamee, it threatens the economy because it buys its rivals, public health because it encourages addiction, and democracy because people are denied access to different opinions."}, {"q": "Why will transparency and other changes not be enough?", "m": "Because the problem is too big: real solutions require broader and deeper changes, which reformers, regulators and citizens must have the courage to fight for."}], "q3": {"mode": "find", "opts": ["founded", "gratitude", "apprehension", "central", "acknowledged", "courage"], "items": [["admitted", "acknowledged"], ["created", "founded"], ["determination", "courage"], ["main", "central"]]}, "q4": [{"q": "Facebook wants users...", "o": ["to get addicted to Facebook.", "to use Facebook more and more.", "to use Facebook until you have health problems.", "to stop using Instagram."], "a": 1}, {"q": "Deeper changes should come from...", "o": ["Facebook, Instagram and WhatsApp.", "reformers, regulators and citizens.", "tech companies.", "Roger McNamee only."], "a": 1}, {"q": "According to the author, tech companies...", "o": ["need to undertake a lot of important regulations in their products.", "need to be asked about which regulations they want for their products.", "need to be banned until they regulate their products.", "do not need any regulation."], "a": 0}], "q5": {"A": "Do you think that people your age are addicted to social networking sites such as Facebook and Instagram? Give reasons.", "B": "For and against: Should social networks be regulated by governments?"}}, {"id": "cv2020-jul-a", "official": true, "year": 2020, "conv": "July 2020", "opt": "A", "label": "PAU July 2020 · Text A", "cat": "Society", "topic": "Happiness", "color": "#cc7da7", "title": "How to Make the World Happier", "source": "Adapted from an article by Richard Layard, The Observer, 19-01-2020", "text": ["There is a wind of change in our society. People are talking about feelings. Even men are doing it. All around there is a new concern with our own inner life and with how other people feel. A new, gentler culture is emerging.", "By contrast, the older culture, which still dominates, encourages people to aim at personal success: good grades, a good job, a good income and a desirable partner. This culture involves a lot of stress, and people wonder why we are not happier.", "The answer is surely the ultra-competitive nature of the dominant culture. Its objective is success. But, if I succeed, someone else has to fail. An alternative culture offers a different aim: that we should of course take care of ourselves, but we should get as much happiness as possible from contributing to the happiness of others. Competition, it argues, is valuable in the right context but what we need between individuals is cooperation, not competition.", "In recent years, the rise in competitiveness has been made worse by the advent of social media, which have encouraged self-advertisement and made more young people feel inadequate, anxious, depressed and \"left out\". In addition, it has encouraged populism, which is a challenge to a cohesive and loving society.", "A shift of perspective is central to the happiness movement, which is about the importance of our feelings -our quality of life as we actually experience it. We can become more effective as creators of happiness, both as citizens and workers."], "q1": [{"s": "The alternative culture underlines the importance of everybody's happiness.", "a": "T", "ev": "we should get as much happiness as possible from contributing to the happiness of others"}, {"s": "The alternative culture explicitly rejects all kinds of competition among humans.", "a": "F", "ev": "Competition, it argues, is valuable in the right context"}, {"s": "The alternative culture focuses on personal experiences.", "a": "T", "ev": "about the importance of our feelings"}, {"s": "Social media have made young people feel more confident.", "a": "F", "ev": "made more young people feel inadequate, anxious, depressed"}], "q2": [{"q": "What does the dominant culture aim at?", "m": "It encourages people to look for personal success: good marks, a good job, a high income and a desirable partner."}, {"q": "Why are social media bad for happiness?", "m": "They increase competitiveness and self-promotion, which make many young people feel inadequate, anxious, depressed or left out."}], "q3": {"mode": "find", "opts": ["concern", "stress", "aim", "valuable", "rise", "shift"], "items": [["objective", "aim"], ["increase", "rise"], ["preoccupation", "concern"], ["beneficial", "valuable"]]}, "q4": [{"q": "The old culture values competition...", "o": ["so that everybody gets successful.", "to get personal success while others do not get it.", "in order to be happy.", "because it is fun."], "a": 1}, {"q": "Social media have...", "o": ["increased competitiveness.", "challenged society.", "made society cohesive.", "made people more relaxed."], "a": 0}, {"q": "For the new culture feelings are…", "o": ["basic for our occupations.", "basic in the generation of happiness.", "an antidote to competitiveness.", "not important at all."], "a": 1}], "q5": {"A": "Do social media contribute to people's happiness? Give reasons.", "B": "Narrative: Write about a day when helping someone made you happy."}}, {"id": "cv2020-jul-b", "official": true, "year": 2020, "conv": "July 2020", "opt": "B", "label": "PAU July 2020 · Text B", "cat": "Society", "topic": "Relationships", "color": "#cc7da7", "title": "Why It Is Good to Know Your \"Love Language\"", "source": "Adapted from an article by Emine Saner, The Guardian, 25-02-2020", "text": ["According to Five Love Languages, written by Gary Chapman, we each have a \"language\" in the way we express and would like to receive love and affection. \"Talking about love languages is a really good way for people to talk about how they need to be loved,\" says Simone Bose, a relationship therapist.", "According to Chapman, there are five basic love languages: words of affirmation (such as saying to your partner \"I love you\", or paying them compliments); quality time (phones away, television off, undivided attention); receiving gifts; acts of service (such as taking on the household jobs you know your partner dislikes); and physical touch. In his experience, couples seldom share the same languages.", "Kate Moyle, a sex and relationship therapist, says this idea can be helpful. \"Understanding your love language and your partner's can break through communication barriers, the biggest, most common issue in any relationship in terms of misunderstanding.\"", "One person might feel they are showing their partner love in the best way they know how but the other person might not appreciate it, or even notice. That's when conversation is really good. It could be as simple as telling your partner what is most meaningful to you. People feel quite vulnerable about saying these things. However, it's not necessarily huge statements. A lot of the time it's about the little things. Saying thank you, showing someone you appreciate them. We are busy and often preoccupied, so these are things that tend to fall out of sight."], "q1": [{"s": "People normally know their partners' idea of how love should be expressed.", "a": "F", "ev": "In his experience, couples seldom share the same languages"}, {"s": "Mastering love languages can prevent misunderstandings.", "a": "T", "ev": "Understanding your love language and your partner's can break through communication barriers"}, {"s": "We often don't use love languages because we have many things to do and to worry about.", "a": "T", "ev": "We are busy and often preoccupied, so these are things that tend to fall out of sight"}, {"s": "Gary Chapman identified seven love languages.", "a": "F", "ev": "there are five basic love languages"}], "q2": [{"q": "Why is the understanding of your partner's love language good for your relationship?", "m": "Because it helps you overcome communication barriers and avoid misunderstandings, which are the most common problem in relationships."}, {"q": "How can you show your partner that he/she matters to you?", "m": "With small things, such as saying thank you, paying compliments, spending quality time together or doing things that the other person appreciates."}], "q3": {"mode": "find", "opts": ["undivided", "seldom", "common", "issue", "appreciate", "huge"], "items": [["rarely", "seldom"], ["very big", "huge"], ["complete", "undivided"], ["typical", "common"]]}, "q4": [{"q": "Having a \"love language\" means that we have an idea of...", "o": ["how to express love to a person who speaks the same language.", "how we want love to be expressed to others and from others.", "the language that other people \"speak\" to us.", "the number of languages we speak."], "a": 1}, {"q": "It is very unlikely that...", "o": ["our partner speaks the five love languages.", "both partners speak the same love languages on the same day.", "both partners speak the same love languages in the same way.", "both partners like receiving gifts."], "a": 2}, {"q": "Very often the partner...", "o": ["understands the person's love language but forgets to also express it.", "does not value the other person's effort to express his/her love.", "speaks only one of the five languages and there is a misunderstanding.", "always understands everything."], "a": 1}], "q5": {"A": "Have you ever been in love? How important do you think love is in people's lives?", "B": "Opinion: Is it important to tell people how much you care about them?"}}, {"id": "cv2020-sep-a", "official": true, "year": 2020, "conv": "September 2020", "opt": "A", "label": "PAU September 2020 · Text A", "cat": "Environment", "topic": "Climate activism", "color": "#7eb991", "title": "Greta Thunberg: a Teenager on a Global Mission", "source": "Adapted from an article by Martin Belam and Guardian staff, The Guardian, 04-10-2019", "text": ["The Swedish climate activist Greta Thunberg has become known globally for her environmental campaign. In August 2018, Thunberg began a solo climate protest by striking from school. She has since been joined by thousands of students in over a dozen countries, in climate strikes that have become regular events. Her protests were inspired by US students who staged walkouts to demand better gun controls in response to multiple school shootings.", "Speaking at the United Nations climate conference in December 2018, she scolded world leaders for behaving like irresponsible children. In January 2019, she attacked the global business elite in Davos: \"Some people, some companies, some decision-makers in particular, have known exactly what priceless values they have been sacrificing to continue making unimaginable amounts of money. And I think many of you here today belong to that group of people.\"", "She has attracted criticism, particularly from right-wing commentators, who claim she is too young or naive to know what she is talking about and is being manipulated by her parents. One commentator on Fox News referred to her as a \"mentally ill Swedish child\", for which the network was forced to apologise.", "Thunberg has insisted she is just relying on science. Rather than submitting prepared remarks at the US Congress, she submitted an intergovernmental report on climate change that warned of the rapidly approaching catastrophe of global heating, asking them to read it. In September 2019, she told world leaders: \"You have stolen my dreams and my childhood with your empty words.\""], "q1": [{"s": "Greta's protests have always been followed by students.", "a": "F", "ev": "Thunberg began a solo climate protest"}, {"s": "Like US students, Greta staged strikes demanding gun controls.", "a": "F", "ev": "Her protests were inspired by US students who staged walkouts to demand better gun controls"}, {"s": "According to Greta, some people have been aware of what they have been sacrificing in order to make money.", "a": "T", "ev": "have known exactly what priceless values they have been sacrificing to continue making unimaginable amounts of money"}, {"s": "Greta says that she relies on science.", "a": "T", "ev": "Thunberg has insisted she is just relying on science"}], "q2": [{"q": "Why is Greta criticised?", "m": "Some critics, especially right-wing commentators, say that she is too young and naive to understand the issue and that her parents manipulate her."}, {"q": "Why is she so worried about climate?", "m": "Because, according to scientific reports, global heating is a catastrophe that is approaching rapidly and world leaders are not acting."}], "q3": {"mode": "find", "opts": ["strikes", "events", "shootings", "elite", "right-wing", "submitting"], "items": [["happenings", "events"], ["walkouts", "strikes"], ["conservative", "right-wing"], ["ruling class", "elite"]]}, "q4": [{"q": "Fox News had to apologise for…", "o": ["its right-wing commentators.", "saying that Greta was naive.", "referring to Greta as a \"mentally ill child.\"", "criticising the US Congress."], "a": 2}, {"q": "At the US congress, Greta presented…", "o": ["her own remarks about climate change.", "an intergovernmental report on climate change.", "an intergovernmental report on climate change and her own remarks.", "a film about her life."], "a": 1}, {"q": "Greta accused world leaders of…", "o": ["stealing money.", "giving messages that convey no meaning.", "not reading the report on climate change.", "not going to school."], "a": 1}], "q5": {"A": "Global warming is a myth. Do you agree? Why/Why not?", "B": "Opinion: Can young people change the world?"}}, {"id": "cv2020-sep-b", "official": true, "year": 2020, "conv": "September 2020", "opt": "B", "label": "PAU September 2020 · Text B", "cat": "Environment", "topic": "Water", "color": "#7eb991", "title": "Will Clean Water Be Our Biggest Source of Conflict in the Future?", "source": "Adapted from an article by Hope Corrigan, Quartz, 18-12-2019", "text": ["If you had to imagine what we will be obsessing over in 50 years, what would top your list? We put versions of that question to dozens of entrepreneurs, scientists, academics, and artists and, from their 550 answers, some clear themes emerged. One such theme: our most valuable resource will be water.", "Polluted rivers and destructive floods are contributing to a global water crisis. A scarcity of clean, fresh water is challenging populations in South America, the Middle East, and Africa. Companies that require water to make clothes or grow food cut into the amount of water available for people to drink. The World Wildlife Fund has a team of 500 people dedicated to studying business' effect on water supply and, though organizations are beginning to confront the issue, many experts we spoke with agree that, in 50 years, water scarcity has the potential to be at the heart of our biggest conflicts.", "So, what kinds of companies will be the most important? Food and water providers will be key as water becomes a scarce resource, companies producing it from a variety of sources will become critical for survival. People who are also trying to figure out how to live on and under water, and people who negotiate with green energies, especially solar and wind, will also be important. And what will cause the biggest conflicts? First, access to clean water as salt-water will come up and drinking water will be less; then, climate change and, finally, displaced populations."], "q1": [{"s": "People need more clean water all over the world except in Europe.", "a": "F", "ev": "Polluted rivers and destructive floods are contributing to a global water crisis"}, {"s": "Textile and food industries help people find drinking water.", "a": "F", "ev": "Companies that require water to make clothes or grow food cut into the amount of water available for people to drink"}, {"s": "There are three challenges for the future: water, weather and migration.", "a": "T", "ev": "access to clean water as salt-water will come up and drinking water will be less; then, climate change and, finally, displaced populations"}, {"s": "More than 500 people answered the question.", "a": "F", "ev": "We put versions of that question to dozens of entrepreneurs, scientists, academics, and artists"}], "q2": [{"q": "What are the Word Wildlife Fund and other experts concerned with?", "m": "They are worried about the effect of businesses on water supply, because in the future the lack of clean water could cause the biggest conflicts."}, {"q": "What will the most important industries be in the future?", "m": "Companies that provide food and water, those finding ways to live on and under water, and those working with green energies like solar and wind."}], "q3": {"mode": "find", "opts": ["resource", "scarcity", "supply", "issue", "survival", "figure out"], "items": [["shortage", "scarcity"], ["calculate", "figure out"], ["topic", "issue"], ["continuity", "survival"]]}, "q4": [{"q": "Polluted rivers bring as a consequence…", "o": ["the use of green energies.", "destructive floods.", "a shortage of water worldwide.", "more rain in Africa."], "a": 2}, {"q": "In the future, water will be obtained from…", "o": ["green energies.", "many different origins.", "food and water providers.", "only from rivers."], "a": 1}, {"q": "Green energies include …", "o": ["sun and wind.", "solar power but not wind.", "underwater, solar and wind power.", "nuclear power."], "a": 0}], "q5": {"A": "What important challenge(s) will we have to face in the future regarding climate change? Give reasons.", "B": "Narrative: Imagine a day in 2075 when clean water is scarce. Describe it."}}, {"id": "cv2021-jun-a", "official": true, "year": 2021, "conv": "June 2021", "opt": "A", "label": "PAU June 2021 · Text A", "cat": "Environment", "topic": "Bottled water", "color": "#7eb991", "title": "Do You Drink Bottled Water?", "source": "Adapted from an article by Adrienne Matei, The Guardian, 28-1-2021", "text": ["Although water bottles are recyclable, Americans throw away about 80% of the bottles they use - and Americans use 1,500 plastic bottles of water every second. Plastic bottles contribute to global environmental crises, in part due to the fact that they disintegrate into microplastics, the presence of which are so ubiquitous that researchers recently discovered them in the placentas of unborn babies. The extraction and manufacturing processes used by bottled water corporations also have negative environmental and economic effects, and amount to the privatisation and commercialisation of a limited and invaluable resource to which all should have a universal right.", "When clean, safe water is unavailable, drinking bottled water becomes a necessity. The average consumer, however, does not purchase bottled water out of need, but because it is often marketed as purer or tastier than tap water - despite the fact that it does not necessarily come from the appealing sources consumers think it does.", "When it comes to the health qualities of bottled versus tap water, differences are negligible. Both tap and bottled water are required to meet quality requirements. Contamination is always possible in either but by prevailing standards both are generally fine to drink.", "Prevailing standards, however, have not quite caught up to the threat of PFAS - a group of industrial chemicals used in a variety of consumer products. PFAS have been found in both tap and bottled water. There is currently no federal guidance on PFAS regulation, though there is evidence that most PFAS are carcinogenic."], "q1": [{"s": "Americans recycle most of the plastic bottles they use.", "a": "F", "ev": "Americans throw away about 80% of the bottles they use"}, {"s": "Drinking bottled water is healthier than drinking tap water.", "a": "F", "ev": "When it comes to the health qualities of bottled versus tap water, differences are negligible"}, {"s": "Carcinogenic PFAS are more often found in bottled water than in tap water.", "a": "F", "ev": "PFAS have been found in both tap and bottled water"}, {"s": "Microplastics have even been found in the placentas of unborn babies.", "a": "T", "ev": "researchers recently discovered them in the placentas of unborn babies"}], "q2": [{"q": "What are the effects of bottled water manufacturing?", "m": "The extraction and manufacturing of bottled water harm the environment and the economy, and they turn water, a limited resource that should belong to everyone, into a private business."}, {"q": "Why do people consume bottled water?", "m": "Most people buy it not because they need it, but because advertising presents it as purer or tastier than tap water."}], "q3": {"mode": "find", "opts": ["invaluable", "unavailable", "average", "appealing", "prevailing", "evidence"], "items": [["common", "prevailing"], ["priceless", "invaluable"], ["proof", "evidence"], ["attractive", "appealing"]]}, "q4": [{"q": "Water should be…", "o": ["privatised.", "a right for everybody.", "bottled conveniently.", "sold only in glass bottles."], "a": 1}, {"q": "Contaminants can be found in…", "o": ["bottled water.", "tap water.", "both bottled and tap water.", "neither of them."], "a": 2}, {"q": "FPAS regulation…", "o": ["already exists.", "does not exist yet.", "is applied to a variety of consumer products.", "has been banned."], "a": 1}], "q5": {"A": "What are the advantages and disadvantages of drinking tap water?", "B": "For and against: Bottled water or tap water?"}}, {"id": "cv2021-jun-b", "official": true, "year": 2021, "conv": "June 2021", "opt": "B", "label": "PAU June 2021 · Text B", "cat": "Leisure & culture", "topic": "Streaming", "color": "#f6bb83", "title": "How Fast Do You Cancel Streaming Services?", "source": "Adapted from an article by Ryan Faughnderstaff, Los Angeles Times, 18-1-2021", "text": ["That is the issue facing media and entertainment companies as the battle for streaming audiences settles into a new phase. During 2019 and 2020, studios launched Disney+, HBO Max, Peacock with both paid and free tiers, Apple TV+, Discovery+ and others, all betting on original, exclusive programming to draw users. The coronavirus crisis has been very positive for the streaming industry while movie theaters, concert venues and sports arenas continue to suffer.", "The problem is that, because they are so easy to cancel, those services are seeing a lot of people leave after they finish watching the shows that convinced them to sign up in the first place. That phenomenon, known in the industry as \"churn,\" is a growing headache in the streaming wars, according to a new report released by professional services giant Deloitte. According to Deloitte's survey of 1,100 people in October, 46% of respondents canceled at least one streaming service in the last six months. That is a dramatic increase from the 20% who said in a similar January survey that they had canceled a service in the previous year. Of the people surveyed who canceled a streaming subscription, 62% did so because they finished the show or movie that they had signed up to see, Deloitte said.", "The data suggests it is becoming harder for media and entertainment companies to retain subscribers as competition increases, said Kevin Westcott, Deloitte's leader. With so many services available, having exclusive content alone isn't enough to keep people on board."], "q1": [{"s": "Coronavirus has had no effect on streaming services.", "a": "F", "ev": "The coronavirus crisis has been very positive for the streaming industry"}, {"s": "More than 50% of people unsubscribed a streaming service when their favourite programs had just started.", "a": "F", "ev": "62% did so because they finished the show or movie that they had signed up to see"}, {"s": "Companies need now much more than unshared products to keep users.", "a": "T", "ev": "having exclusive content alone isn't enough to keep people on board"}, {"s": "Almost half of the people surveyed cancelled a service in the previous six months.", "a": "T", "ev": "46% of respondents canceled at least one streaming service in the last six months"}], "q2": [{"q": "What is \"churn\" for the streaming industry?", "m": "It is the name given to users who cancel their subscription, often as soon as they finish the show they signed up for."}, {"q": "Why is it becoming more and more difficult for entertainment companies to keep users?", "m": "Because there are so many services and it is so easy to cancel them that exclusive content is no longer enough to keep subscribers."}], "q3": {"mode": "find", "opts": ["settles", "draw", "venues", "sign up", "suggests", "increases"], "items": [["grows", "increases"], ["attract", "draw"], ["subscribe", "sign up"], ["halls", "venues"]]}, "q4": [{"q": "Exclusive contents…", "o": ["help to increase the number of users.", "do not help to increase the number of users.", "help to increase the number of free tiers.", "are no longer produced."], "a": 0}, {"q": "When compared to last year, this year the number of cancellations…", "o": ["has increased a little.", "has clearly decreased.", "has increased significantly.", "has stayed the same."], "a": 2}, {"q": "A study confirmed that the majority of subscribers did not continue the service after…", "o": ["January.", "six months.", "the show they were interested in was over.", "they paid for the first month."], "a": 2}], "q5": {"A": "Do you often use streaming services like Netflix, HBO…? What do you like about them?", "B": "Opinion: Are streaming platforms killing cinemas?"}}, {"id": "cv2021-jul-a", "official": true, "year": 2021, "conv": "July 2021", "opt": "A", "label": "PAU July 2021 · Text A", "cat": "Environment", "topic": "Microfibres", "color": "#7eb991", "title": "Clothes Washing Linked to Plastic Pollution in the Arctic", "source": "Adapted from an article by Damian Carrington, The Guardian, 12-1-2021", "text": ["The Arctic is polluted by microplastic fibres that most likely come from the washing of synthetic clothes by people in Europe and North America. The most comprehensive study to date found the microplastics in 96 of 97 sea water samples taken from across the polar region. More than 92% of the microplastics were fibres, and 73% of these were made of polyester and were the same width and colours as those used in clothes. Most of the samples were taken from 3-8 metres below the surface, where much marine life feeds.", "The researchers also found plastic fibres at the North Pole. With plastic recently discovered at the deepest point on Earth, the Mariana Trench, and the peak of Mount Everest, it is clear humanity's litter has polluted the entire planet. It is known to injure wildlife that mistake it for food. People also consume microplastics via food and water, and breathe them in, although the health impact is not yet known.", "Much more water flows into the Arctic from the Atlantic than the Pacific, and the new research found higher concentrations of the microplastic fibres nearer the Atlantic, as well as longer and less degraded fibres. \"We're looking at a dominance of Atlantic inputs, which means sources of textile fibres in the North Atlantic from Europe and North America are likely to be driving the contamination in the Arctic Ocean,\" said Peter Ross, who led the study. \"With these polyester fibres, we've essentially created a cloud throughout the world's oceans.\""], "q1": [{"s": "Plastic debris can be found in the deepest and the highest places on the globe.", "a": "T", "ev": "With plastic recently discovered at the deepest point on Earth, the Mariana Trench, and the peak of Mount Everest"}, {"s": "The Atlantic contains fewer amounts of plastic fibres than the Pacific, although they are longer.", "a": "F", "ev": "the new research found higher concentrations of the microplastic fibres nearer the Atlantic"}, {"s": "North America is solely responsible for Arctic plastic fibre pollution.", "a": "F", "ev": "sources of textile fibres in the North Atlantic from Europe and North America are likely to be driving the contamination"}, {"s": "Microplastics were found in almost all the sea water samples.", "a": "T", "ev": "found the microplastics in 96 of 97 sea water samples"}], "q2": [{"q": "Why do researchers think most microplastics come from clothes?", "m": "Because most of them are polyester fibres with the same width and colours as those used in clothes, so they probably come from washing synthetic clothes."}, {"q": "Do microplastics affect people's health?", "m": "People eat, drink and breathe in microplastics, but scientists do not know yet what effect they have on our health."}], "q3": {"mode": "find", "opts": ["comprehensive", "width", "litter", "injure", "dominance", "throughout"], "items": [["damage", "injure"], ["complete", "comprehensive"], ["waste", "litter"], ["thickness", "width"]]}, "q4": [{"q": "In the polar region, most microplastics in sea water…", "o": ["are found in marine life.", "have the same width and colour.", "are made of polyester.", "are found at the North Pole only."], "a": 2}, {"q": "Our health might be in danger because…", "o": ["we have polluted the whole Earth.", "of the samples taken below the surface.", "of the width of fibres.", "the Arctic is very cold."], "a": 0}, {"q": "According to the new study, important amounts of microplastic fibres are driven towards…", "o": ["Europe and North America.", "the Arctic.", "Europe, North America and the Arctic.", "the Pacific Ocean."], "a": 1}], "q5": {"A": "How can we reduce microplastic pollution?", "B": "Opinion: Should we change the way we buy and wash clothes?"}}, {"id": "cv2021-jul-b", "official": true, "year": 2021, "conv": "July 2021", "opt": "B", "label": "PAU July 2021 · Text B", "cat": "Health", "topic": "Ageing", "color": "#ef908a", "title": "Do We Have to Age?", "source": "Adapted from an article by Alex Moshakis, The Observer, 3-1-2021", "text": ["When the biologist Andrew Steele tells people that we might one day cure ageing as if it were any other disease, they are often skeptical. He understands the reaction: ageing is an inescapable fact of life - we're born and we grow old. However, \"anti-ageing medicine would identify the causes of dysfunction as we get older, then slow their progression or reverse them entirely,\" Steele reports. The hope isn't that we live longer for the sake of it, it is that we live longer in good health. Humans have searched for a cure for ageing for thousands of years. In the past, countless people made lengthy, futile quests for life-extending elixirs. Lately, research has accelerated. A 2018 study extended the life expectancy of mice by 10%, though it comes with side-effects, including the loss of hair. Last year, scientists transplanted cells from young mice into elderly ones, adding three months to their lives, which in equivalent human terms could be worth more than a decade.", "To Steele this is all thrilling, although it is the fact that human trials have begun that excites him most. A recent study found that a combination of hormones and drugs helps rejuvenate some organs, which degenerate rapidly with age. \"Research foreshadows a future where ageing will be treated,\" Steele says, \"We are likely to have a drug that treats ageing in the next 10 years.\" Steele isn't talking about immortality, but science which will make lifespans longer than what we currently consider normal."], "q1": [{"s": "Steele accepts people's opinion that ageing is unavoidable.", "a": "F", "ev": "we might one day cure ageing as if it were any other disease"}, {"s": "Young mice had their lives extended in a study last year.", "a": "F", "ev": "scientists transplanted cells from young mice into elderly ones"}, {"s": "Treating ageing will probably be a fact in the next 10 years.", "a": "T", "ev": "We are likely to have a drug that treats ageing in the next 10 years"}, {"s": "Steele believes that science will make humans immortal.", "a": "F", "ev": "Steele isn't talking about immortality"}], "q2": [{"q": "What would the benefits of medicine against age be?", "m": "It would identify the causes of the problems of getting older and slow them down or reverse them, so people could live longer and in good health."}, {"q": "Have there been efforts to stop getting old in history?", "m": "Yes. For thousands of years people have looked for a cure for ageing, and many went on long, useless searches for elixirs to extend life."}], "q3": {"mode": "find", "opts": ["disease", "skeptical", "countless", "lengthy", "thrilling", "currently"], "items": [["innumerable", "countless"], ["incredulous", "skeptical"], ["nowadays", "currently"], ["extensive", "lengthy"]]}, "q4": [{"q": "Anti-ageing medicine may make people live…", "o": ["longer without losing hair.", "longer and healthy.", "for thousands of years.", "younger than their parents."], "a": 1}, {"q": "A study prolonged the life of mice…", "o": ["but their hair fell out.", "with no side-effects.", "only in 10% of them.", "without any effect."], "a": 0}, {"q": "What Steele finds most exciting is the…", "o": ["rejuvenation of some organs.", "beginning of trials with humans.", "chance of immortality.", "discovery of a magic elixir."], "a": 1}], "q5": {"A": "Do you think that today's diseases, for example cancer, will disappear in the near future?", "B": "For and against: Would you like to live much longer than people do today?"}}, {"id": "cv2022-jun-a", "official": true, "year": 2022, "conv": "June 2022", "opt": "A", "label": "PAU June 2022 · Text A", "cat": "Technology", "topic": "Voice assistants", "color": "#7ec9e6", "title": "\"Alexa, Take Me to the Moon\"", "source": "Adapted from an article by Christian Davenport, The Guardian, 5-1-2022", "text": ["Lockheed Martin, which is building the Orion spacecraft that NASA hopes will fly astronauts to the moon within a couple of years, is partnering with Amazon to put an Alexa on the capsule. The device would give astronauts real-time information on telemetry, the health of the spacecraft and its speed. It would be possible \"for astronauts to ask about the spacecraft, the mission, the subsystems,\" Aaron Rubenson, Amazon's vice president, said. \"More importantly, from the crew perspective: What's that alarm that just went off? Remind me what that is.\"", "In addition to Alexa, the Orion spacecraft will be outfitted with screens that, like Zoom, allow users to see each other and share critical information. Taken together, the package, known as Callisto, would help translate different languages so astronauts from all over the world could communicate. It would also help controllers on the ground share information over a screen. The platform would also help in overcoming isolation by allowing astronauts to stay and feel connected to their home, family members and friends.", "The onboard space Alexa would not be connected to the Internet but instead connect directly to Orion's computer and its own onboard cloud. Still, it could send queries back to Earth and connect with the cloud to retrieve all sorts of information, such as news, that would help astronauts to feel less lonely. There would be a lag in those queries since data would have to travel from the spacecraft to Earth and then from Earth to the spacecraft."], "q1": [{"s": "Lockheed Martin is working with Amazon to put Alexa on the Orion capsule.", "a": "T", "ev": "is partnering with Amazon to put an Alexa on the capsule"}, {"s": "Alexa will allow the crew to do videoconferencing.", "a": "F", "ev": "In addition to Alexa, the Orion spacecraft will be outfitted with screens that, like Zoom, allow users to see each other"}, {"s": "There would be real-time communication between Orion and the Earth.", "a": "F", "ev": "There would be a lag in those queries"}, {"s": "The onboard Alexa would be directly connected to the Internet.", "a": "F", "ev": "The onboard space Alexa would not be connected to the Internet"}], "q2": [{"q": "What are the advantages of installing Alexa on the Orion spacecraft?", "m": "It would give astronauts real-time information about the spacecraft, its speed and the mission, and it could explain alarms; it would also help them feel less lonely."}, {"q": "How could Alexa help the astronauts stay in contact with the Earth?", "m": "It could send questions to Earth and receive information such as news, and the Callisto system would help astronauts feel connected with their families and friends."}], "q3": {"mode": "find", "opts": ["partnering", "device", "crew", "overcoming", "retrieve", "lag"], "items": [["machine", "device"], ["in association", "partnering"], ["delay", "lag"], ["collect", "retrieve"]]}, "q4": [{"q": "Callisto is the name given to…", "o": ["an onboard translator.", "an onboard platform similar to Zoom.", "a combination of Alexa and some screens.", "a new spacecraft."], "a": 2}, {"q": "Callisto would…", "o": ["help astronauts connect with their families.", "share critical information with the astronauts.", "control the astronauts' communications.", "replace the astronauts."], "a": 0}, {"q": "Alexa would connect…", "o": ["only to the spacecraft's cloud and computer.", "only to the spacecraft's cloud and the Internet.", "to the spacecraft's computer, the onboard cloud and the Internet.", "only to the astronauts' phones."], "a": 0}], "q5": {"A": "What are the advantages and disadvantages of using digital voice assistants? Do you usually use them?", "B": "Opinion: Would you like to travel to the Moon? Why or why not?"}}, {"id": "cv2022-jun-b", "official": true, "year": 2022, "conv": "June 2022", "opt": "B", "label": "PAU June 2022 · Text B", "cat": "Society", "topic": "European youth", "color": "#cc7da7", "title": "2022: European Year of Youth to Empower Young People", "source": "Adapted from an article in EU Monitor, 15-12-2021", "text": ["The 2022 European Year of Youth (EYY) will focus on re-establishing a positive outlook for European young people negatively affected by the impact of the COVID-19 pandemic. Designating 2022 as a year focused on young people means increased efforts will be made to include youth priorities in relevant EU policy areas and at every level of the EU's decision-making process. The EYY will aim to engage young people in key consultation processes, such as the Conference on the Future of Europe, and in other public policies at EU, national and local levels. There will be a special focus on young people with fewer opportunities and on mental health issues. The EYY will include conferences, initiatives promoting youth participation in policy making, awareness-raising campaigns on a more inclusive, green, and digital EU, as well as studies and research on the situation in which young people in the EU find themselves.", "\"The COVID-19 pandemic continues to disproportionately affect young people\", said Sabine Verheyen. \"They face the challenges of trying to continue their education and enter the job market (...) make new acquaintances and discover other countries. Young people have accepted and supported the ongoing restrictions out of solidarity. Now it is time to let them flourish\", she said. \"This year will lay the foundation for giving young people a stronger platform to make their voices heard\", she stressed, adding that we need \"all young people to be involved and participate in creating a better, greener, more digital and inclusive future in Europe.\""], "q1": [{"s": "The objective of the EYY is to consider what politicians think of young people.", "a": "F", "ev": "efforts will be made to include youth priorities in relevant EU policy areas"}, {"s": "The EYY will include scientific studies on the current situation of Europe's youth.", "a": "T", "ev": "studies and research on the situation in which young people in the EU find themselves"}, {"s": "The EYY aims to promote a less inclusive and more digital Europe.", "a": "F", "ev": "awareness-raising campaigns on a more inclusive, green, and digital EU"}, {"s": "Young people supported the COVID restrictions out of solidarity.", "a": "T", "ev": "Young people have accepted and supported the ongoing restrictions out of solidarity"}], "q2": [{"q": "What will the European Year of Youth focus on?", "m": "It will try to give young people a positive outlook after the pandemic by including their priorities in EU policies, with special attention to those with fewer opportunities and to mental health."}, {"q": "What difficulties do young people face after the pandemic?", "m": "They find it hard to continue their education, enter the job market, meet new people and travel to other countries."}], "q3": {"mode": "find", "opts": ["outlook", "priorities", "engage", "challenges", "acquaintances", "flourish"], "items": [["involve", "engage"], ["relationships", "acquaintances"], ["develop", "flourish"], ["prospect", "outlook"]]}, "q4": [{"q": "The EYY aims to involve young people in…", "o": ["promoting solidarity and consultation processes.", "national and local policies prioritizing COVID-19 studies.", "local, national, and European public policies.", "organising sports events."], "a": 2}, {"q": "Some of the EYY issues are…", "o": ["conferences on the effect of COVID-19 on young people.", "the promotion of solidarity.", "inclusion and ecology.", "the end of all restrictions."], "a": 2}, {"q": "The EYY will be the starting point to give young people…", "o": ["opportunities to convey their views.", "more possibilities to make more money.", "precise ideas on how to get a better job.", "free university places."], "a": 0}], "q5": {"A": "What suggestions would you make to empower young people and get their ideas considered?", "B": "Opinion: Do politicians listen to young people?"}}, {"id": "cv2022-jul-a", "official": true, "year": 2022, "conv": "July 2022", "opt": "A", "label": "PAU July 2022 · Text A", "cat": "Technology", "topic": "Beauty filters", "color": "#7ec9e6", "title": "Is That Really Me? the Ugly Truth About Beauty Filters", "source": "Adapted from an article by Matilda Boseley, The Guardian, 1-6-2022", "text": ["Mia started using filters when one of her TikTok videos unexpectedly went viral and her audience suddenly skyrocketed. \"At that point, I was around 100kg, so it was really scary for me to have people looking at me,\" she says. As her video clocked up more than 1m views, abusive comments started pouring in. \"I was getting a lot of hate,\" she says, adding: \"The filters on TikTok are so smooth and flawless - they don't look like a filter. So it felt so easy to use them, just to make me feel a little better… but honestly, it doesn't even look like me.\"", "\"Social media is promoting a beauty ideal that's not attainable because nobody looks like that … and that's where the harm can come from,\" Dr Jasmine Fardouly, a body image expert, says. \"Body dissatisfaction is an important predictor for eating disorders, and for depression and low self-esteem… There is also a link to increased interest in cosmetic surgery.\"", "Fardouly says social media companies should not be held solely responsible for the harm caused by unattainable beauty standards. \"It's kind of human nature… A lot of the problems with the platforms come from people's desires and motivations offline as well. People have always wanted to present themselves positively to others; that's not new. It's just that social media really gives us the tools to control how we appear, and to spend a lot of time investing in our self-presentation - and that's where the harm can come from.\""], "q1": [{"s": "Mia began to use filters when the audience of her TikTok videos decreased.", "a": "F", "ev": "her audience suddenly skyrocketed"}, {"s": "Having eating disorders makes people feel depressed.", "a": "F", "ev": "Body dissatisfaction is an important predictor for eating disorders, and for depression and low self-esteem"}, {"s": "It's not only because of social media that people want to show a good image of themselves.", "a": "T", "ev": "People have always wanted to present themselves positively to others; that's not new"}, {"s": "Mia received many abusive comments after her video went viral.", "a": "T", "ev": "abusive comments started pouring in"}], "q2": [{"q": "Why did Mia start using filters on her TikToK videos?", "m": "Because her video went viral and she started receiving hateful comments about her body, so filters made her feel a little better."}, {"q": "Why is the ideal of beauty promoted by social media damaging?", "m": "Because it shows an ideal of beauty that nobody can reach, which can lead to body dissatisfaction, eating disorders, depression, low self-esteem and interest in cosmetic surgery."}], "q3": {"mode": "find", "opts": ["unexpectedly", "abusive", "flawless", "link", "harm", "solely"], "items": [["exclusively", "solely"], ["perfect", "flawless"], ["without warning", "unexpectedly"], ["insulting", "abusive"]]}, "q4": [{"q": "The filters on TikTok…", "o": ["are easy to discover.", "are user-friendly.", "help a video go viral.", "are only for famous people."], "a": 1}, {"q": "People…", "o": ["want to show a good image of themselves.", "spend much time on their self-presentations.", "do not have offline tools to invest in their image.", "never use social media."], "a": 0}, {"q": "Harm can result because…", "o": ["beauty standards cannot be attained.", "social media platforms cause many problems.", "there are both online and offline difficulties.", "filters are expensive."], "a": 0}], "q5": {"A": "Do you use filters on social media? Why?", "B": "Narrative: Write about a time when social media made you feel good or bad about yourself."}}, {"id": "cv2022-jul-b", "official": true, "year": 2022, "conv": "July 2022", "opt": "B", "label": "PAU July 2022 · Text B", "cat": "Environment", "topic": "Plastic pollution", "color": "#7eb991", "title": "Plastic Disaster", "source": "Adapted from an article by Melissa Petruzzello, Britannica, 31-1-2022", "text": ["Plastic is cheap and durable and has revolutionized human activity. Modern life is addicted to and dependent on this versatile substance, which is found in everything from computers to medical equipment to food packaging. Unfortunately, an estimated 19 billion pounds of plastic waste ends up in our oceans every year. Much of this plastic comes from single-use packaging, such as soda bottles, and from other single-use products such as disposable diapers. One study suggested that by the year 2050 there will be more plastic by weight in the oceans than fish!", "Plastic pollution is more than unsightly. It has a deadly and direct effect on wildlife. Many marine organisms get physically entangled in plastic trash. Others eat the plastics, mistaking the ubiquitous materials for food. Sea turtles often confuse plastic bags for their jellyfish prey and asphyxiate. Seabirds, especially albatrosses, and other birds that scoop food from the sea have been found dead on their nests, their bellies too full of plastics to survive. A recent study found plastic trash in 90 percent of seabirds, with pieces ranging from bottle caps to rice-sized fragments that look like seeds.", "Perhaps even more worrisome is microplastic pollution. The vast majority of plastics are not biodegradable, meaning they break down into smaller and smaller particles but never leave the environment entirely. Pieces smaller than 5 mm are classified as microplastics. These particles are too small for waste management systems to filter and are directly discharged into the oceans."], "q1": [{"s": "According to a study, the oceans will likely contain more plastic than fish in the next decades.", "a": "T", "ev": "by the year 2050 there will be more plastic by weight in the oceans than fish"}, {"s": "Marine organisms are trapped in plastic waste.", "a": "T", "ev": "Many marine organisms get physically entangled in plastic trash"}, {"s": "Plastic pollution is more dangerous than microplastic pollution.", "a": "F", "ev": "Perhaps even more worrisome is microplastic pollution"}, {"s": "Most plastics are biodegradable.", "a": "F", "ev": "The vast majority of plastics are not biodegradable"}], "q2": [{"q": "Why is modern life so dependent on plastic?", "m": "Because plastic is cheap, durable and versatile, so it is used in almost everything, from computers and medical equipment to food packaging."}, {"q": "What are microplastics?", "m": "They are tiny pieces of plastic smaller than 5 mm that come from bigger plastics breaking down; they are too small to be filtered and end up in the oceans."}], "q3": {"mode": "find", "opts": ["durable", "versatile", "disposable", "unsightly", "ubiquitous", "worrisome"], "items": [["single-use", "disposable"], ["flexible", "versatile"], ["omnipresent", "ubiquitous"], ["resistant", "durable"]]}, "q4": [{"q": "Sea turtles…", "o": ["like eating plastics.", "confuse bags for albatrosses.", "like jellyfish.", "never go near the coast."], "a": 2}, {"q": "Seabirds have been found dead because…", "o": ["their nests were full of plastic waste.", "there was plastic trash in their stomachs.", "their bellies were full of diapers.", "there was no fish left."], "a": 1}, {"q": "Microplastics are…", "o": ["durable particles.", "easy to filter.", "five millimetres thick.", "bigger than 5 mm."], "a": 0}], "q5": {"A": "Is it possible to reduce the use of plastics? Give reasons.", "B": "For and against: Should supermarkets stop selling products in plastic packaging?"}}, {"id": "cv2023-jun-a", "official": true, "year": 2023, "conv": "June 2023", "opt": "A", "label": "PAU June 2023 · Text A", "cat": "Health", "topic": "Mental health", "color": "#ef908a", "title": "Young People to Be Prescribed Surfing and Dancing to Help Anxiety", "source": "Adapted from an article by Denis Campbell, The Guardian, 25-10-2022", "text": ["Young people will take part in surfing, roller-skating and gardening to see whether sport, the arts and outdoor activities can make them less anxious and depressed.", "National Health Service (NHS) mental health trusts will use the activities to help 600 young people on their waiting lists for care as part of a study into whether \"social prescribing\" helps improve mental wellbeing. People aged 11 to 18 in 10 parts of England will also be able to take part in dance, music, sport and exercise and attend youth clubs during the trial, which is being run by academics from University College London (UCL). If participation proves successful the NHS may seek to make such activities available across England as a way of helping the many thousands of young people who face what can be months-long delays in accessing formal treatment, during which time their condition often worsens. \"Young people's mental health is one of the greatest challenges facing the NHS,\" said Dr. Daisy Fancourt, the UCL mental health expert running the trial: \"Social prescribing has the potential to support young people while they wait, by providing access to a range of creative and social activities that could enhance their confidence, self-esteem and social support networks.\"", "Fancourt and her team will assess how much young people participate, the feasibility of making such activities available and the costs involved. Participants will be able to choose which pursuits they want to try, aided by a link worker or \"buddy,\" in conjunction with 10 NHS mental health trusts."], "q1": [{"s": "The mental condition of young people in waiting lists often aggravates.", "a": "T", "ev": "during which time their condition often worsens"}, {"s": "Teenagers from UCL will also participate in the study.", "a": "F", "ev": "which is being run by academics from University College London"}, {"s": "Participants in Dr. Fancourt's study will choose their preferred activity with their buddies.", "a": "T", "ev": "Participants will be able to choose which pursuits they want to try"}, {"s": "The study will include 600 young people on waiting lists.", "a": "T", "ev": "to help 600 young people on their waiting lists for care"}], "q2": [{"q": "Why are young people prescribed these activities?", "m": "To find out if sport, arts and outdoor activities can reduce their anxiety and depression while they wait for formal treatment."}, {"q": "Which are the potential benefits of these practices according to Dr. Fancourt?", "m": "They could improve young people's confidence and self-esteem and give them social support networks while they wait for treatment."}], "q3": {"mode": "find", "opts": ["prescribing", "successful", "seek", "available", "running", "assess"], "items": [["try", "seek"], ["fruitful", "successful"], ["leading", "running"], ["evaluate", "assess"]]}, "q4": [{"q": "The purpose of the study is to find out whether these social activities…", "o": ["improve the mental health of youngsters.", "need further promotion among youngsters from UCL.", "should be included in UCL.", "replace all medical treatments."], "a": 0}, {"q": "People aged 11 to 18 who take part in the study may…", "o": ["travel across 10 parts of England to get to UCL.", "participate in youth clubs, music or sports.", "attend the academies at the UCL Campus.", "work at the NHS."], "a": 1}, {"q": "Dr. Fancourt and colleagues will estimate…", "o": ["the costs of attending youth clubs.", "the costs of the trial.", "the expenses of running the NHS.", "the salaries of doctors."], "a": 1}], "q5": {"A": "Do you think that social activities and sport are important for mental health? Give reasons.", "B": "Narrative: Write about an activity that helps you relax."}}, {"id": "cv2023-jun-b", "official": true, "year": 2023, "conv": "June 2023", "opt": "B", "label": "PAU June 2023 · Text B", "cat": "Society", "topic": "Generation Z", "color": "#cc7da7", "title": "Top Gen Z Trends of 2023 to Look Forward to in the New Year", "source": "Adapted from an article by Trinetra Pau, Lifestyle Asia Hong Kong, 4-1-2023", "text": ["Gen Zor Generation Z (those born between 1997 and 2012) is heavily influenced by technology and easy access to information on the Internet. More than any other generation, Gen Zers have easy reach to a cell phone and even the oldest members of this age group are aware of the top trends on social media and are concerned about their digital image.", "A survey conducted by Instagram called it one of the most ethically conscious generations ever. Gen Zconsumers are particular about opting for ethical and sustainable brands and two out of three respondents prefer buying beauty products that incorporate sun protection to protect themselves from damaging rays and invest in skincare routines that help during hotter temperatures. This generation also cares deeply about social justice and disability rights and is likely to follow influencers with any kind of intellectual or physical disability. Another top Gen Ztrend is to advocate for inclusivity and speak openly about the LGBTQ+ community. Rising mental health concerns seem to be another Gen Ztrend. They often complain of mental health and consider it to be a major factor in disrupting the work environment and efficiency and it also reflects on their physical health.", "When it comes to dating, many feel more comfortable talking via text than in person and wondering what their first message would be. Memes get a mixed review. Gen Zers are more likely to use social media platforms like Instagram for online dating instead of swiping on dating apps."], "q1": [{"s": "Very few Gen Zconsumers use sunscreen.", "a": "F", "ev": "two out of three respondents prefer buying beauty products that incorporate sun protection"}, {"s": "This generation will probably follow disabled influencers.", "a": "T", "ev": "is likely to follow influencers with any kind of intellectual or physical disability"}, {"s": "Gen Zprefers to establish first contact face-to-face rather than virtually.", "a": "F", "ev": "many feel more comfortable talking via text than in person"}, {"s": "Gen Z has been described as one of the most ethically conscious generations.", "a": "T", "ev": "called it one of the most ethically conscious generations ever"}], "q2": [{"q": "Which beauty products does Gen Zprefer?", "m": "They prefer ethical and sustainable brands, especially beauty products with sun protection and skincare routines that help in hot weather."}, {"q": "Why is Gen Zso concerned about mental health?", "m": "Because they consider it a major factor that affects their work and efficiency, and it also has an impact on their physical health."}], "q3": {"mode": "find", "opts": ["trends", "brands", "routines", "cares", "rights", "reflects"], "items": [["shows", "reflects"], ["tendencies", "trends"], ["minds", "cares"], ["trademarks", "brands"]]}, "q4": [{"q": "One of the main Gen Ztrends is…", "o": ["inclusivity.", "efficiency.", "dating.", "watching television."], "a": 0}, {"q": "Mental health…", "o": ["has an impact on physical health.", "interferes when dating.", "is a major factor when finding a job.", "only affects older people."], "a": 0}, {"q": "Gen Zers…", "o": ["love dating apps.", "prefer platforms.", "use dating apps more than platforms.", "never use social media for dating."], "a": 1}], "q5": {"A": "Are you a typical Gen Zperson? Give reasons.", "B": "Opinion: What are the main differences between your generation and your parents' generation?"}}, {"id": "cv2023-jul-a", "official": true, "year": 2023, "conv": "July 2023", "opt": "A", "label": "PAU July 2023 · Text A", "cat": "Environment", "topic": "Fukushima", "color": "#7eb991", "title": "Fukushima Water", "source": "Adapted from an article by Justin McCurry, The Guardian, 13-1-2023", "text": ["Japan has decided to begin the release of a million tonnes of water from stricken Fukushima nuclear plant almost 12 years after a magnitude-9 earthquake triggered a huge tsunami that killed more than 18,000 people along Japan's north-east coast.", "The water will be gradually discharged into the Pacific Ocean via a tunnel after being treated and diluted. The plan's operator, Tokyo Electric Power (Tepco), has said its water treatment technology can remove all radioactive materials from water except tritium, which it says is harmless in small amounts. The International Atomic Energy Agency has also pointed out that nuclear plants around the world use a similar process to dispose of wastewater containing low-level concentrations of tritium and other radionuclides.", "South Korea and China have voiced concern about the discharge, while the Pacific Islands Forum has said recently that Japan \"should hold off on any such release until we are certain about the implications of this proposal on the environment and on human health, especially recognising that the majority of our Pacific peoples are coastal peoples, and that the ocean continues to be an integral part of their subsistence living.\"", "The South Korean government, which has yet to lift its ban on Fukushima seafood, has said that releasing the water would pose a \"grave threat\" to marine life. Fishing unions in the area oppose the release, warning it would cause alarm among consumers and derail more than a decade of efforts to reassure the public that Fukushima seafood is safe to eat."], "q1": [{"s": "The 2011 tsunami killed more than 18,000 people.", "a": "T", "ev": "triggered a huge tsunami that killed more than 18,000 people"}, {"s": "Fukushima nuclear plant is the only one that processes wastewater containing tritium.", "a": "F", "ev": "nuclear plants around the world use a similar process to dispose of wastewater containing low-level concentrations of tritium"}, {"s": "Most Pacific peoples live on what they get from the ocean.", "a": "T", "ev": "the majority of our Pacific peoples are coastal peoples, and that the ocean continues to be an integral part of their subsistence living"}, {"s": "Local fishing unions support the release of the water.", "a": "F", "ev": "Fishing unions in the area oppose the release"}], "q2": [{"q": "How will the release be done?", "m": "The water will be treated and diluted and then released gradually into the Pacific Ocean through a tunnel."}, {"q": "Why are fishing unions against the release?", "m": "Because they think it will worry consumers and ruin more than ten years of work to convince people that Fukushima seafood is safe to eat."}], "q3": {"mode": "find", "opts": ["release", "remove", "dispose", "concern", "hold off", "ban"], "items": [["extract", "remove"], ["prohibition", "ban"], ["postpone", "hold off"], ["worry", "concern"]]}, "q4": [{"q": "The Fukushima water treatment will be done by...", "o": ["Tokyo Electric Power.", "the International Atomic Energy Agency.", "both Tokyo Electric Power and the International Atomic Energy Agency.", "the Pacific Islands Forum."], "a": 0}, {"q": "South Korea and China want Japan to...", "o": ["explain the effects of the release on the environment.", "release the wastewater into Pacific coastal areas.", "refrain from the release into the Pacific Ocean.", "build a new nuclear plant."], "a": 2}, {"q": "South Koreans are…", "o": ["allowed to eat Fukushima seafood.", "not allowed to eat Fukushima fish.", "sure Fukushima seafood is safe to eat.", "the main buyers of Fukushima fish."], "a": 1}], "q5": {"A": "Do you think green energy is the energy source for the future? Give reasons.", "B": "For and against: Nuclear power."}}, {"id": "cv2023-jul-b", "official": true, "year": 2023, "conv": "July 2023", "opt": "B", "label": "PAU July 2023 · Text B", "cat": "Technology", "topic": "Texting", "color": "#7ec9e6", "title": "Fine, I Admit It - I Am a \"Dry Texter\"", "source": "Adapted from an article by Emma Beddington, The Guardian, 23-2-2023", "text": ["I've recently become aware of the phenomenon of dry texting: the short, single-word responses (Yes, No, OK, Lol) to messages that are viewed as inadequate, hostile or hurtful.", "Our family chat is arid. Most messages are \"k\" or \"OK.\" Supposedly interesting messages sent by those of us who are keen to maintain a feeling of connection go uncommented on; sometimes even unopened. I can be a dry texter myself: short responses to friends who send three-paragraph messages. It's partly a lack of mental capacity for more writing outside the day job. If I could bring myself to get into emojis - I can't - I would absolutely be the \"single thumbs-up\" kind of texter.", "The other reason I dry text is I can't write anything without horribly getting my typing wrong and being cruelly provoked by autocorrect. When I try to fix it, I end up hitting the Minstead of delete, so most of my messages read: \"We we're mmmmmmmm.\"", "I quite like dry texting anyway: there's an economical poetry to it. My last four messages from my stepfather are \"Yes,\" \"OK,\" \"Good\" and \"OK.\" The conversation thread between me and my husband is mainly \"Dog?\" \"Where are you?\" \"Kfé?\" (coffee) and \"Yep.\" He used a single emoji back in January and I'm still getting over it. It makes the more expansive messages extra special, too, such as when my husband spontaneously says he's missing me. Those in textual relationships with more extensive typing style will never know that thrill."], "q1": [{"s": "The author opens all the messages that she receives on her mobile.", "a": "F", "ev": "sometimes even unopened"}, {"s": "The author's typing ability adds to her tendency to dry texting.", "a": "T", "ev": "I can't write anything without horribly getting my typing wrong and being cruelly provoked by autocorrect"}, {"s": "The author always prefers her husband to dry text her.", "a": "F", "ev": "It makes the more expansive messages extra special, too, such as when my husband spontaneously says he's missing me"}, {"s": "The author regularly uses emojis.", "a": "F", "ev": "If I could bring myself to get into emojis"}], "q2": [{"q": "What is \"dry texting\"?", "m": "It means answering messages with very short, one-word replies such as 'yes', 'no' or 'OK', which other people may find inadequate or even hostile."}, {"q": "Why does the author use that kind of text?", "m": "Because she is mentally tired of writing after work, she makes many typing mistakes that autocorrect makes worse, and she likes the economy of short messages."}], "q3": {"mode": "find", "opts": ["hurtful", "maintain", "bring", "fix", "extensive", "thrill"], "items": [["persuade", "bring"], ["considerable", "extensive"], ["upsetting", "hurtful"], ["keep", "maintain"]]}, "q4": [{"q": "Something that causes the author's dry texting is her...", "o": ["habit of never replying to substantial messages.", "mental exhaustion after writing in her job.", "inability to use emojis alongside typed texts.", "dislike of her family."], "a": 1}, {"q": "Autocorrect…", "o": ["gets in the way of the author's typing.", "suggests more words than the author is willing to type.", "makes the author consider using emojis.", "sends messages to her husband."], "a": 0}, {"q": "The author's conversations with her husband are…", "o": ["only extensive when typing about feelings.", "managed with an exchange of a lot of words.", "sometimes special when he is not dry texting.", "always about the dog."], "a": 2}], "q5": {"A": "Are you a regular dry texter? Give reasons.", "B": "Narrative: Write about a misunderstanding caused by a text message."}}, {"id": "cv2024-jun-a", "official": true, "year": 2024, "conv": "June 2024", "opt": "A", "label": "PAU June 2024 · Text A", "cat": "Technology", "topic": "Influencers", "color": "#7ec9e6", "title": "How Influencers Actually Influence You", "source": "Adapted from an article by Richard Dancsi, Psychology Today, 4-12-23.", "text": ["Online social networks provide a platform upon which influence can be created out of nothing. Psychologist Robert Cialdini's basic principles of influence, proposed in 1984, are all relevant and present on these networks. Consider, for example, how successful influencers share attractive stories that impact an audience. Frequent postings and interactions help make influencers easier to identify to fans and give followers a sense of familiarity. Many influencers also manage to establish themselves as experts or authorities within their topics, even without the accreditation of researchers.", "Humans are by nature social animals, as Aristotle pointed out, but we are not especially exigent about how real our connections are. People naturally form parasocial relationships, feeling a deep emotional connection to someone without any direct interaction. We feel as if we know our favorite movie stars personally, and when the voice of a podcaster fills a room, we feel less alone. We recognize familiar faces, both on the internet and on the street, and form a sense of attachment to people we have never met.", "The influence of parasocial relationships has increased as online platforms have emerged. \"Technology proposes itself as the architect of our friendships,\" sociologist Sherry Turkle suggested in a book in which she explored how technology can both shape and replace face-to-face interaction. As work becomes more remote, the distinction between \"real\" and \"virtual\" has become less clear, creating an opportunity for wise online personalities who seek to become as familiar to us, and as influential, as our closest friends."], "q1": [{"s": "Influencers in social networks always get support from well-known experts.", "a": "F", "ev": "even without the accreditation of researchers"}, {"s": "We are not particularly concerned about the strength of our relationships with other people.", "a": "T", "ev": "we are not especially exigent about how real our connections are"}, {"s": "The \"real\" and the \"virtual\" are increasingly becoming harder to differentiate.", "a": "T", "ev": "has become less clear"}, {"s": "Cialdini's principles of influence are no longer relevant on social networks.", "a": "F", "ev": "are all relevant and present on these networks"}], "q2": [{"q": "What are parasocial relationships?", "m": "They are one-sided relationships in which we feel a strong emotional connection with someone we have never met or interacted with, such as a film star or a podcaster."}, {"q": "How has technology influenced human interaction according to Sherry Turkle?", "m": "She says technology has become 'the architect of our friendships': it shapes and can even replace face-to-face interaction."}], "q3": {"mode": "find", "opts": ["audience", "accreditation", "exigent", "attachment", "remote", "wise"], "items": [["connection", "attachment"], ["demanding", "exigent"], ["intelligent", "wise"], ["public", "audience"]]}, "q4": [{"q": "Frequent online interaction…", "o": ["helps influencers to get to know their followers.", "helps influencers to identify their fans.", "is useful for influencers to become supported by experts.", "makes influencers more familiar to their followers."], "a": 3}, {"q": "We can feel a strong connection…", "o": ["especially with people we have met in person.", "with our parasocial relationships.", "only with people we meet in person and online.", "only with people who live near us."], "a": 1}, {"q": "Online platforms are a type of technology…", "o": ["that has not a direct influence on face-to-face relationships.", "that results in more parasocial relationships.", "where it is very easy to distinguish \"the real\" from \"the virtual\"", "that has made friendships disappear."], "a": 1}], "q5": {"A": "What is your opinion about influencers?", "B": "For and against: Should influencers' advertising be regulated?"}}, {"id": "cv2024-jun-b", "official": true, "year": 2024, "conv": "June 2024", "opt": "B", "label": "PAU June 2024 · Text B", "cat": "Environment", "topic": "Global warming", "color": "#7eb991", "title": "On Our Way to a New Record Global Average Temperature?", "source": "Adapted from an article by Kate Ravilious, The Guardian, 4-1-2024.", "text": ["With 2023 the warmest year on record, 2024 could see the unwelcome milestone of 1.5 of warming reached for a full year. The year 2023 has been confirmed as the warmest in recorded history, with average global temperatures topping 1.5 of heating above preindustrial levels for more than one third of the year. It continues the rapid warming trend, with the 10 warmest years in human history all having occurred since 2010.", "So, what could 2024 hold? Forecasts suggest the year ahead is likely to be another record breaker, with a strong possibility that this could be the first full year to go beyond 1.5 of warming. The ongoing El Niño event, which brings warmer waters to the tropical Pacific Ocean, is helping to push global temperatures up, but UK Met Office scientists say the main driver of the record-breaking temperatures is human-induced warming. Their global outlook for 2024 suggests we will end the next year with average global temperatures somewhere between 1.34 and 1.58 above preindustrial levels.", "Overshooting 1.5 would be an unwelcome milestone but it would not mean we have breached the Paris agreement. Curiously, the 2015 climate accord did not define how we would recognize that the 1.5 target had been surpassed, but it is widely accepted to mean a longer-term average over 20 years or so. Rather than waiting decades for data to roll in, recent research published in Nature suggests using a blend of observations and model projections to test when 1.5 has been passed."], "q1": [{"s": "For more than half of 2023, the global average temperature was over 1.5°C above preindustrial levels.", "a": "F", "ev": "for more than one third of the year"}, {"s": "Forecasts show that in 2024 global average temperatures will stay below 1.5°C of warming all year.", "a": "F", "ev": "this could be the first full year to go beyond"}, {"s": "Some studies propose combining data from several sources to confirm when the 1.5°C target has been exceeded.", "a": "T", "ev": "suggests using a blend of observations and model projections to test when"}, {"s": "The ten warmest years in human history have all occurred since 2010.", "a": "T", "ev": "the 10 warmest years in human history all having occurred since 2010"}], "q2": [{"q": "What do predictions for 2024 suggest about temperature records?", "m": "They suggest that 2024 will probably break the record again and could be the first full year with global warming above 1.5°C."}, {"q": "What does El Niño do and what are its consequences?", "m": "It brings warmer waters to the tropical Pacific Ocean, which helps to push global temperatures up, although the main cause is human activity."}], "q3": {"mode": "find", "opts": ["milestone", "reached", "trend", "outlook", "breached", "blend"], "items": [["mix", "blend"], ["landmark", "milestone"], ["arrived", "reached"], ["prospect", "outlook"]]}, "q4": [{"q": "Year 2023 has been the hottest...", "o": ["ever recorded.", "of preindustrial times.", "in the last 10 years.", "in Europe only."], "a": 0}, {"q": "The UK Met Office states that the main cause of the record temperatures is...", "o": ["the El Niño event.", "warmer waters.", "human activity.", "the Paris agreement."], "a": 2}, {"q": "The Paris agreement set the 1.5°C limit...", "o": ["before 2015.", "after the agreement was signed.", "as an average over the next 20 years.", "without defining how to recognise when it is passed."], "a": 3}], "q5": {"A": "Do you agree that the climate is changing and having an impact on the Earth? Give reasons.", "B": "Opinion: What can young people do to fight climate change?"}}];
